288		public static IEnumerator LoadRoomData(MonoBehaviour givenMono)
289		{
290			while (roomDataLoading)
291			{
292				yield return null;
293			}
294			if (roomDataLoaded)
295			{
296				yield break;
297			}
298			roomDataLoading = true;
299			mainRoomDict = GetMapDirectionsDict<RoomStub>();
300			mainHallwayDict = GetMapDirectionsDict<RoomStub>();
301			mainFloorPlanDict = GetMapDirectionsDict<RoomStub>();
302			mainEndRoomDict = GetMapDirectionsDict<RoomStub>();
303			List<RoomStub> roomStubList = new List<RoomStub>();
304			yield return givenMono.StartCoroutine(RoomStub.LoadAll(roomStubList));
305			foreach (RoomStub rs in roomStubList)
306			{
307				switch (rs.type)
308				{
309				case RoomType.Start:
310					startRoom = rs;
311					break;
312				case RoomType.Exit:
313					exitRoom = rs;
314					break;
315				case RoomType.ItemStore:
316					itemStoreRoom = rs;
317					break;
318				case RoomType.SkillStore:
319					skillStoreRoom = rs;
320					break;
321				case RoomType.Misc:
322					if (rs.name == "CursedStore")
323					{
324						cursedStoreRoom = rs;
325						break;
326					}
327					mainMiscList.Add(rs);
328					switch (rs.name)
329					{
330					case "SlotsRoom":
331						shufflerRoom = rs;
332						break;
333					case "NurseRoom":
334						doctorRoom = rs;
335						break;
336					case "TailorRoom":
337						tailorRoom = rs;
338						break;
339					case "CollectorRoom":
340						collectorRoom = rs;
341						break;
342					case "BankerRoom":
343						bankerRoom = rs;
344						break;
345					case "PinataRoom":
346						pinataRoom = rs;
347						break;
348					}
349					break;
350				case RoomType.FloorPlan:
351					AddToRoomDict(rs, ref mainFloorPlanDict);
352					break;
353				case RoomType.Hallway:
354					switch (rs.name)
355					{
356					case "ge_NS_stVertHall":
357						nsHallway = rs;
358						break;
359					case "ge_EW_stHoriHall":
360						ewHallway = rs;
361						break;
362					}
363					AddToRoomDict(rs, ref mainHallwayDict);
364					break;
365				case RoomType.End:
366					AddToRoomDict(rs, ref mainEndRoomDict);
367					break;
368				case RoomType.Party:
369					partyRoom = rs;
370					break;
371				default:
372					AddToRoomDict(rs, ref mainRoomDict);
373					break;
374				}
375				yield return null;
376			}
377			roomDataLoading = false;
378			roomDataLoaded = true;
379		}
