382		{
383			forceQuitGenerate = false;
384			while (!roomDataLoaded)
385			{
386				yield return null;
387			}
388			if (Level.resetUsedRooms)
389			{
390				Level.resetUsedRooms = false;
391				ClearLists();
392				createdRoomsList.Clear();
393				availableMiscList = new List<RoomStub>(mainMiscList);
394			}
395			Level.startPosition = new Vector2(mapStart.y, -mapStart.x) + new Vector2(12f, -14f);
396			if (Level.isBossRushMode)
397			{
398				PlaceRoom(mapStart, MapDirections.None, exitRoom);
399				yield return null;
400				ConnectionInfo[] rushConns = new ConnectionInfo[4]
401				{
402					GetDirectionConnection(MapDirections.West),
403					GetDirectionConnection(MapDirections.North),
404					GetDirectionConnection(MapDirections.East),
405					GetDirectionConnection(MapDirections.South)
406				};
407				foreach (List<IntVec2> value in connectionDict.Values)
408				{
409					value.Clear();
410				}
411				foreach (List<IntVec2> value2 in priorityConnDict.Values)
412				{
413					value2.Clear();
414				}
415				PlaceHallway(rushConns[0].position, rushConns[0].direction, ewHallway);
416				PlaceHallway(rushConns[1].position, rushConns[1].direction, nsHallway);
417				PlaceHallway(rushConns[2].position, rushConns[2].direction, ewHallway);
418				PlaceHallway(rushConns[3].position, rushConns[3].direction, nsHallway);
419				ref ConnectionInfo reference = ref rushConns[0];
420				reference = GetDirectionConnection(MapDirections.West);
421				ref ConnectionInfo reference2 = ref rushConns[1];
422				reference2 = GetDirectionConnection(MapDirections.North);
423				ref ConnectionInfo reference3 = ref rushConns[2];
424				reference3 = GetDirectionConnection(MapDirections.East);
425				ref ConnectionInfo reference4 = ref rushConns[3];
426				reference4 = GetDirectionConnection(MapDirections.South);
427				Level.ClearRoomPositions();
428				PlaceRoom(rushConns[0].position, rushConns[0].direction, itemStoreRoom);
429				yield return null;
430				selectedMiscRoom = GetMiscRoom(cursedDisabled: true);
431				availableMiscList.Remove(selectedMiscRoom);
432				PlaceRoom(rushConns[1].position, rushConns[1].direction, selectedMiscRoom);
433				yield return null;
434				PlaceRoom(rushConns[2].position, rushConns[2].direction, skillStoreRoom);
435				yield return null;
436				PlaceRoom(rushConns[3].position, rushConns[3].direction, cursedStoreRoom);
437				yield return null;
438				Level.startPosition += Vector2.down * 3f;
439				Level.tileGrid = currentTileGrid;
440				isGenerating = false;
441				yield break;
442			}
443			PlaceRoom(mapStart, MapDirections.None, startRoom);
444			ConnectionInfo connInfo = GetRandomConnection();
445			currentMonobehaviour.StartCoroutine(StartArchitect(connInfo.position, connInfo.direction));
446			while (!AllRoomsCreated || architectActive)
447			{
448				if (forceQuitGenerate)
449				{
450					yield break;
451				}
452				yield return null;
453			}
454			if (forceQuitGenerate)
455			{
456				yield break;
457			}
458			disableConnections = true;
459			Level.ClearRoomPositions();
460			priorityRoomGenList.Clear();
461			priorityRoomGenList.Add(itemStoreRoom);
462			priorityRoomGenList.Add(skillStoreRoom);
463			connInfo = GetRandomConnection();
464			currentMonobehaviour.StartCoroutine(StartArchitect(connInfo.position, connInfo.direction));
465			while (architectActive || !RoomPlaced(itemStoreRoom) || !RoomPlaced(skillStoreRoom))
466			{
467				if (forceQuitGenerate)
468				{
469					yield break;
470				}
471				yield return null;
472			}
473			selectedMiscRoom = GetMiscRoom();
474			priorityRoomGenList.Clear();
475			priorityRoomGenList.Add(selectedMiscRoom);
476			connInfo = GetRandomConnection();
477			currentMonobehaviour.StartCoroutine(StartArchitect(connInfo.position, connInfo.direction));
478			while ((selectedMiscRoom != null && architectActive) || !RoomPlaced(selectedMiscRoom))
479			{
480				if (forceQuitGenerate)
481				{
482					yield break;
483				}
484				yield return null;
485			}
486			priorityRoomGenList.Clear();
487			priorityRoomGenList.Add(exitRoom);
488			connInfo = GetFurthestConnectionInfo(mapStart);
489			currentMonobehaviour.StartCoroutine(StartArchitect(connInfo.position, connInfo.direction));
490			while (architectActive || !RoomPlaced(exitRoom))
491			{
492				if (forceQuitGenerate)
493				{
494					yield break;
495				}
496				yield return null;
497			}
498			if (!createdRoomsList.Contains(partyRoom) && Random.value < 0.02f)
499			{
500				priorityRoomGenList.Clear();
501				priorityRoomGenList.Add(partyRoom);
502				connInfo = GetRandomConnection();
503				currentMonobehaviour.StartCoroutine(StartArchitect(connInfo.position, connInfo.direction));
504				while (architectActive || !RoomPlaced(partyRoom))
505				{
506					if (forceQuitGenerate)
507					{
508						yield break;
509					}

510					yield return null;
511				}
512			}
513			AddDeadEndRooms(priorityConnDict);
514			FillMissedConnections();
515			RemoveExtraConnectionsFromSectionList(Level.GridRoomTupleList, new IntVec2(4, 2));
516			availableMiscList.Remove(selectedMiscRoom);
517			Level.tileGrid = currentTileGrid;
518			isGenerating = false;
519		}
