521		private static IEnumerator StartArchitect(IntVec2 startPosition, MapDirections startDirection)
522		{
523			architectActive = true;
524			RoomStub architectStub = null;
525			IntVec2 position = startPosition;
526			MapDirections direction = startDirection;
527			yield return null;
528			while ((!AllRoomsCreated || priorityRoomGenList.Count > 0 || architectStub != null) && !forceQuitGenerate)
529			{
530				if (priorityRoomGenList.Count > 0 && architectStub == null)
531				{
532					architectStub = priorityRoomGenList[0];
533					priorityRoomGenList.RemoveAt(0);
534				}
535				if ((Random.value < 0.75f || architectStub != null) && PlaceRoom(position, direction, architectStub, Level.doubleEnemies || Random.value < 0.3f))
536				{
537					architectStub = null;
538					priorityConnDict[direction].Remove(position);
539					connectionDict[direction].Remove(position);
540					yield return null;
541				}
542				if (PlaceHallway(position, direction))
543				{
544					priorityConnDict[direction].Remove(position);
545					connectionDict[direction].Remove(position);
546					yield return null;
547				}
548				ConnectionInfo connInfo = GetRandomConnection();
549				direction = connInfo.direction;
550				position = connInfo.position;
551				yield return null;
552			}
553			architectActive = false;
554		}
