556		private static bool PlaceRoom(IntVec2 startPosition, MapDirections givenDirection, RoomStub givenRoom = null, bool isRandom = false)
557		{
558			incomingPlaceRoomDir = GetOppositeDirection(givenDirection);
559			selectedPlaceRoom = givenRoom ?? GetAvailableRoom(startPosition, incomingPlaceRoomDir, isRandom) ?? GetAvailableRoom(startPosition, incomingPlaceRoomDir, isRandom: true);
560			if (selectedPlaceRoom == null)
561			{
562				Debug.Log("Error with available room list!! Catastrophic disaster!!");
563				return false;
564			}
565			loadedPlaceRoom = GetRoomFromLevelDict(selectedPlaceRoom.name);
566			if (!PlaceTileGrid(startPosition, incomingPlaceRoomDir, selectedPlaceRoom, loadedPlaceRoom.tileGrid, isRoom: true))
567			{
568				return false;
569			}
570			createdRoomsList.Add(selectedPlaceRoom);
571			Level.CurrentRoomList.Add(loadedPlaceRoom);
572			roomsRemaining--;
573			return true;
574		}
575	
576		private static bool PlaceHallway(IntVec2 startPosition, MapDirections givenDirection, RoomStub givenHall = null)
577		{
578			RoomStub roomStub = givenHall;
579			MapDirections oppositeDirection = GetOppositeDirection(givenDirection);
580			if (roomStub == null)
581			{
582				List<RoomStub> list = mainHallwayDict[oppositeDirection];
583				roomStub = list[Random.Range(0, list.Count)];
584			}
585			if (roomStub == null)
586			{
587				Debug.Log("Error with hallway dictionary!! Catastrophic disaster!!");
588				return false;
589			}
590			Room roomFromLevelDict = GetRoomFromLevelDict(roomStub.name);
591			if (!PlaceTileGrid(startPosition, oppositeDirection, roomStub, roomFromLevelDict.tileGrid, isRoom: false))
592			{
593				return false;
594			}
595			roomFromLevelDict.randomEnemies = false;
596			roomFromLevelDict.randomInteractables = false;
597			Level.CurrentHallList.Add(roomFromLevelDict);
598			return true;
599		}
600	
601		private static bool PlaceTileGrid(IntVec2 startPosition, MapDirections givenDirection, RoomStub givenStub, TileGrid givenGrid, bool isRoom)
602		{
603			if (roomContainer == null || hallContainer == null)
604			{
605				return false;
606			}
607			placedGrid = new TileGrid(givenGrid);
608			foundConnDict.Clear();
609			usedConnList.Clear();
610			LayoutGeneratorHelper.GetAdjustedTileGrid(ref placedGrid, givenStub, ref foundConnDict, isRoom);
611			LayoutGeneratorHelper.PaveConnectionPaths(ref placedGrid, givenDirection, ref foundConnDict, ref usedConnList);
612			if (usedConnList.Count == 0 && givenStub.type != RoomType.Start && !Level.isBossRushMode)
613			{
614				Debug.LogError(givenStub.name + " doesn't have connections!! " + startPosition.y + " | " + startPosition.x + " || " + foundConnDict.Count);
615			}
616			queueLoadRoom = true;
617			roomConnOffset = startPosition - ((usedConnList.Count <= 0) ? IntVec2.zero : usedConnList[Random.Range(0, usedConnList.Count)]);
618			switch (LayoutGeneratorHelper.CanPlaceGrid(placedGrid, currentTileGrid, roomConnOffset))
619			{
620			case 1:
621				queueLoadRoom = false;
622				break;
623			case 2:
624				return false;
625			}
626			if (queueLoadRoom)
627			{
628				if (isRoom)
629				{
630					Level.GridRoomTupleList.Add(new Tuple<TileGridSection, Room>(new TileGridSection(Level.tileGrid, roomConnOffset.x, roomConnOffset.y, placedGrid.RowCount, placedGrid.ColCount), Room.Load(givenStub.name, instantiate: true, roomContainer, new Vector3(roomConnOffset.y + 2, -roomConnOffset.x - 4))));
631				}
632				else
633				{
