public class OrganicPathGenerator
{
	public static Dictionary<MapOrdinalDirections, Vector2> dirToOffset = new Dictionary<MapOrdinalDirections, Vector2>
	{
		{
			MapOrdinalDirections.None,
			new Vector2(0f, 0f)
		},
		{
			MapOrdinalDirections.North,
			new Vector2(-1f, 0f)
		},
		{
			MapOrdinalDirections.NorthWest,
			new Vector2(-1f, -1f)
		},
		{
			MapOrdinalDirections.NorthEast,
			new Vector2(-1f, 1f)
		},
		{
			MapOrdinalDirections.West,
			new Vector2(0f, -1f)
		},
