	public static MapOrdinalDirections[] allOrdinalDirs = new MapOrdinalDirections[8]
	{
		MapOrdinalDirections.North,
		MapOrdinalDirections.NorthWest,
		MapOrdinalDirections.NorthEast,
		MapOrdinalDirections.West,
		MapOrdinalDirections.East,
		MapOrdinalDirections.South,
		MapOrdinalDirections.SouthWest,
		MapOrdinalDirections.SouthEast
	};

	public static List<Vector2> visitedNodes;

	public static int floorTileID = 808;

	public static int overlayTileID = 993;

	public static void GenerateOrganicPaths(TileGrid tileGrid, TileSet tileSet)
	{
		List<Vector2> list = new List<Vector2>();
		List<Vector2[]> list2 = new List<Vector2[]>();
		if (tileSet.pathTileSets == null || tileSet.pathTileSets.Keys.Count == 0)
		{
			return;
		}
		WeightedRandomizer weightedRandomizer = new WeightedRandomizer();
		foreach (PathTileSet value in tileSet.pathTileSets.Values)
		{
			weightedRandomizer.Add(value);
		}
		if (visitedNodes == null)
		{
			visitedNodes = new List<Vector2>();
		}
		else
		{
			visitedNodes.Clear();
		}
		int rowCount = tileGrid.RowCount;
		int colCount = tileGrid.ColCount;
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				Tile tile = tileGrid[i, j];
				if (tile == null || tile.terrain != Tile.TerrainType.Floor || tile.path != Tile.FloorType.None || tile.obstacle || tile.pitOverrideType != Tile.FloorType.None || tile.layers["FloorDoodad"].hasDoodad || tile.layers["FloorDoodad2"].hasDoodad || tile.layers["FloorDoodad3"].hasDoodad)
				{
					continue;
				}
				PathTileSet curPathTileSet = (PathTileSet)weightedRandomizer.weightedItems[weightedRandomizer.GetRandomGroupID()];
				if (Random.value > curPathTileSet.newPathSpawnChance)
				{
					continue;
				}
				bool flag = false;
				if (curPathTileSet.minPathDist > 0)
				{
					for (int k = 0; k < list2.Count; k++)
					{
						int num = 0;
						if (num < list2[k].Length && Vector2.Distance(new Vector2(i, j), list2[k][num]) < (float)curPathTileSet.minPathDist)
						{
							flag = true;
						}
						if (flag)
						{
							break;
						}
					}
				}
				if (flag)
				{
					continue;
				}
				bool flag2 = false;
				for (int l = 0; l < 2; l++)
				{
					if (flag2)
					{
						break;
					}
					for (int m = 0; m < 2; m++)
					{
						Tile tile2 = tileGrid[i + l, j + m];
						if (tile2.obstacle || tile2.pitOverrideType != Tile.FloorType.None)
						{
							flag2 = true;
							break;
						}
						if (tile2.layers["FloorDoodad"].hasDoodad || tile2.layers["FloorDoodad2"].hasDoodad || tile2.layers["FloorDoodad3"].hasDoodad)
						{
							flag2 = true;
							break;
						}
						if (TileSet.CheckAdjacentTiles(i + l, j + m, tileGrid, (Tile t) => t.layers["FloorDoodad"].hasDoodad || t.layers["FloorDoodad2"].hasDoodad || t.layers["FloorDoodad3"].hasDoodad || t.pitOverrideType != Tile.FloorType.None) != MapOrdinalDirections.None)
						{
							flag2 = true;
							break;
						}
						MapOrdinalDirections adjacentTerrainDirs = TileSet.GetAdjacentTerrainDirs(i + l, j + m, tileGrid);
						MapOrdinalDirections mapOrdinalDirections = TileSet.CheckAdjacentTiles(i + l, j + m, tileGrid, (Tile t) => t.path != Tile.FloorType.None);
						if (TileSet.CheckAdjacentTiles(i + l, j + m, tileGrid, (Tile t) => t.path != Tile.FloorType.None && t.pathTileSetID != curPathTileSet.name) != MapOrdinalDirections.None)
						{
							flag2 = true;
							break;
						}
						MapOrdinalDirections mapOrdinalDirections2 = TileSet.CheckAdjacentTiles(i + l, j + m, tileGrid, (Tile t) => !t.obstacle && t.terrain != Tile.TerrainType.Pit && t.pitOverrideType == Tile.FloorType.None);
						if (mapOrdinalDirections2 != MapOrdinalDirections.Everything)
						{
							flag2 = true;
							break;
						}
						if (!AdjTileTest.NoPitSurround2.Test(tileGrid, i + l, j + m))
						{
							flag2 = true;
							break;
						}
						if (l == 0 && m == 0 && ((mapOrdinalDirections.HasFlag(MapOrdinalDirections.North) ^ mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthEast)) || (mapOrdinalDirections.HasFlag(MapOrdinalDirections.West) ^ mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthWest))))
						{
							flag2 = true;
							break;
						}
						if (l == 1 && m == 1 && ((mapOrdinalDirections.HasFlag(MapOrdinalDirections.South) ^ mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthWest)) || (mapOrdinalDirections.HasFlag(MapOrdinalDirections.East) ^ mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthEast))))
						{
							flag2 = true;
							break;
						}
					}
				}
				if (flag2)
				{
					continue;
				}
				list.Clear();
				for (int num2 = 0; num2 < 2; num2++)
				{
					for (int num3 = 0; num3 < 2; num3++)
					{
						Tile tile3 = tileGrid[i + num2, j + num3];
						tile3.path = Tile.FloorType.Center;
						tile3.terrainMaterial = curPathTileSet.terrainMaterial;
						tile3.pathTileSetID = curPathTileSet.name;
						list.Add(new Vector2(i + num2, j + num3));
					}
				}
				CarveNewPath(seedLocation: new Vector2(i, j), tileGrid: tileGrid, row: i, col: j, pathTileList: list, curPathTileSet: curPathTileSet);
				if (curPathTileSet.minTileCount == 0 || list.Count >= curPathTileSet.minTileCount)
				{
					list2.Add(list.ToArray());
					continue;
				}
				for (int num4 = 0; num4 < list.Count; num4++)
				{
					int x = (int)list[num4].x;
					int y = (int)list[num4].y;
					tileGrid[x, y].path = Tile.FloorType.None;
					tileGrid[x, y].terrainMaterial = Tile.TerrainMaterial.Stone;
					tileGrid[x, y].pathTileSetID = string.Empty;
				}
			}
		}
		SetFloorTypes(tileGrid, tileSet, list2);
	}

	public static void CarveNewPath(TileGrid tileGrid, int row, int col, List<Vector2> pathTileList, PathTileSet curPathTileSet, Vector2 seedLocation)
	{
		if (pathTileList.Count >= curPathTileSet.maxTileCount || tileGrid[row, col] == null)
		{
			return;
		}
		Tile tile = tileGrid[row, col];
		if (tile.terrain != Tile.TerrainType.Floor || tile.path == Tile.FloorType.None || tile.obstacle || tile.pitOverrideType != Tile.FloorType.None || tile.layers["FloorDoodad"].hasDoodad || tile.layers["FloorDoodad2"].hasDoodad || tile.layers["FloorDoodad3"].hasDoodad || TileSet.CheckAdjacentTiles(row, col, tileGrid, (Tile t) => t.layers["FloorDoodad"].hasDoodad || t.layers["FloorDoodad2"].hasDoodad || t.layers["FloorDoodad3"].hasDoodad) != MapOrdinalDirections.None)
		{
			return;
		}
		MapOrdinalDirections adjacentTerrainDirs = TileSet.GetAdjacentTerrainDirs(row, col, tileGrid);
		if (adjacentTerrainDirs != MapOrdinalDirections.Everything || Vector2.Distance(new Vector2(row, col), seedLocation) >= curPathTileSet.maxDistFromSeed)
		{
			return;
		}
		MapOrdinalDirections mapOrdinalDirections = MapOrdinalDirections.Everything;
		MapOrdinalDirections mapOrdinalDirections2 = TileSet.CheckAdjacentTiles(row, col, tileGrid, (Tile t) => t.path != Tile.FloorType.None);
		mapOrdinalDirections &= ~mapOrdinalDirections2;
		MapOrdinalDirections mapOrdinalDirections3 = TileSet.CheckAdjacentTiles(row, col, tileGrid, (Tile t) => t.obstacle);
		mapOrdinalDirections &= ~mapOrdinalDirections3;
		MapOrdinalDirections mapOrdinalDirections4 = TileSet.CheckAdjacentTiles(row, col, tileGrid, (Tile t) => t.pitOverrideType != Tile.FloorType.None);
		mapOrdinalDirections &= ~mapOrdinalDirections4;
		MapOrdinalDirections[] array = allOrdinalDirs;
		foreach (MapOrdinalDirections mapOrdinalDirections5 in array)
		{
			if (mapOrdinalDirections.HasFlag(mapOrdinalDirections5))
			{
				int num2 = (int)((float)row + dirToOffset[mapOrdinalDirections5].x);
				int num3 = (int)((float)col + dirToOffset[mapOrdinalDirections5].y);
				adjacentTerrainDirs = TileSet.GetAdjacentTerrainDirs(num2, num3, tileGrid);
				if (adjacentTerrainDirs != MapOrdinalDirections.Everything)
				{
					mapOrdinalDirections &= ~mapOrdinalDirections5;
				}
				else if (!AdjTileTest.NoPitSurround2.Test(tileGrid, num2, num3))
				{
					mapOrdinalDirections &= ~mapOrdinalDirections5;
				}
			}
		}
		List<Tuple<MapOrdinalDirections, MapOrdinalDirections>> list = new List<Tuple<MapOrdinalDirections, MapOrdinalDirections>>();
		if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.North))
		{
			if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthWest))
			{
				list.Add(new Tuple<MapOrdinalDirections, MapOrdinalDirections>(MapOrdinalDirections.North, MapOrdinalDirections.NorthWest));
			}
			if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.NorthEast))
			{
				list.Add(new Tuple<MapOrdinalDirections, MapOrdinalDirections>(MapOrdinalDirections.North, MapOrdinalDirections.NorthEast));
			}
		}
		if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.South))
		{
			if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthWest))
			{
				list.Add(new Tuple<MapOrdinalDirections, MapOrdinalDirections>(MapOrdinalDirections.South, MapOrdinalDirections.SouthWest));
			}
			if (mapOrdinalDirections.HasFlag(MapOrdinalDirections.SouthEast))
			{
				list.Add(new Tuple<MapOrdinalDirections, MapOrdinalDirections>(MapOrdinalDirections.South, MapOrdinalDirections.SouthEast));
