		{
			tilePos = null;
			tiles = null;
		}
	}

	public bool IsValidTile(int row, int col)
	{
		if (InBounds(row, col) && this[row, col] != null)
		{
			return true;
		}
		return false;
	}

	public static bool SkipTile(Tile curTile, string tileLayerName)
	{
		if (curTile == null || curTile.layers == null || !curTile.layers.ContainsKey(tileLayerName))
		{
			return true;
		}
		if (tileLayerName == "Overlay" && curTile.overlay == Tile.OverlayType.None)
		{
			return true;
		}
		if (tileLayerName == "Wall" && curTile.terrain != Tile.TerrainType.Wall)
		{
			return true;
		}
		if (tileLayerName == "Pit" && curTile.terrain != Tile.TerrainType.Pit)
		{
			return true;
		}
		if (tileLayerName == "Floor" && curTile.terrain != Tile.TerrainType.Floor)
		{
			return true;
		}
		switch (tileLayerName)
		{
		case "SubFloor":
		case "WallDoodad":
		case "WallDoodad2":
		case "WallDoodad3":
		case "WallDoodad4":
		case "FloorDoodad":
		case "FloorDoodad2":
		case "FloorDoodad3":
		case "Debug":
		case "OverlayDoodad":
			if (curTile.layers[tileLayerName].tileSetID == 0)
			{
				return true;
			}
			break;
		}
		return false;
	}

	public TileGrid Padd(int topPadding = 0, int rightPadding = 0, int botPadding = 0, int leftPadding = 0)
	{
		int rowCount = RowCount;
		int colCount = ColCount;
		int row = rowCount + topPadding + botPadding;
		int col = colCount + leftPadding + rightPadding;
		TileGrid tileGrid = new TileGrid(row, col);
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				tileGrid[i + topPadding, j + leftPadding] = this[i, j];
			}
		}
		return tileGrid;
	}

	public void FinalizeTerrain()
	{
		for (int i = WallGenerator.wallHeight; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				Tile tile = this[i, j];
				if (tile == null || (tile.terrain != Tile.TerrainType.Floor && tile.terrain != Tile.TerrainType.Pit))
				{
					continue;
				}
				bool flag = true;
				int num = 0;
				for (int k = 1; k < WallGenerator.wallHeight + 2; k++)
				{
					Tile tile2 = this[i - k, j];
					if (tile2 != null && (tile2.terrain == Tile.TerrainType.Floor || tile2.terrain == Tile.TerrainType.Pit))
					{
						flag = false;
						break;
					}
					num++;
				}
				if (flag)
				{
					for (int l = 1; l < WallGenerator.wallHeight + 1; l++)
					{
						if (this[i - l, j] == null)
						{
							this[i - l, j] = new Tile(Tile.TerrainType.Wall);
						}
						else
						{
							this[i - l, j].terrain = Tile.TerrainType.Wall;
						}
					}
				}
				else
				{
					if (num <= 0)
					{
						continue;
					}
					for (int m = 1; m < WallGenerator.wallHeight + 2; m++)
					{
						if (this[i - m, j] == null)
						{
							this[i - m, j] = new Tile(Tile.TerrainType.Floor);
						}
						else
						{
							this[i - m, j].terrain = Tile.TerrainType.Floor;
						}
					}
				}
			}
		}
	}

	public void InitLayerVertices(bool forceVertexUpdate = false, string forceTileSet = "")
	{
		if (layerVertexData != null && !forceVertexUpdate)
		{
			return;
		}
		if (layerVertexData == null)
		{
			layerVertexData = new Dictionary<string, LayerVertexData>();
		}
		layerVertexData.Clear();
		for (int i = 0; i < Tile.tileLayerNames.Length; i++)
		{
			if (!layerVertexData.ContainsKey(Tile.tileLayerNames[i]))
			{
				layerVertexData[Tile.tileLayerNames[i]] = new LayerVertexData();
			}
			string text = Tile.tileLayerNames[i];
			layerVertexData[text].vertices = InitVertices(text, forceTileSet);
		}
	}

	public Vector3[] InitVertices(string tileLayerName, string forceTileSet = "")
	{
		List<Vector3> list = new List<Vector3>();
		int num = 0;
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				if (!SkipTile(this[i, j], tileLayerName))
				{
					Vector3[] array = new Vector3[4]
					{
						new Vector3(j + 1, -i, 0f),
						new Vector3(j + 1, -i + -1, 0f),
						new Vector3(j, -i, 0f),
						new Vector3(j, -i + -1, 0f)
					};
					list.AddRange(array);
					this[i, j].vertices = array;
					string text = ((!(forceTileSet != string.Empty)) ? this[i, j].layers[tileLayerName].tileSetName : forceTileSet);
					layerVertexData[tileLayerName].tileSetNames.Add(text);
					if (!layerVertexData[tileLayerName].subMeshIndices.ContainsKey(text))
					{
						layerVertexData[tileLayerName].subMeshIndices[text] = new List<int>();
					}
					layerVertexData[tileLayerName].subMeshIndices[text].Add(num * 4);
					num++;
				}
			}
		}
		return list.ToArray();
	}

	public void OnBeforeSerialize()
	{
		List<Vector2> list = new List<Vector2>();
		List<Tile> list2 = new List<Tile>();
		for (int i = 0; i < _rowCount; i++)
		{
			for (int j = 0; j < _colCount; j++)
			{
				if (this[i, j] != null)
				{
					list.Add(new Vector2(i, j));
					list2.Add(this[i, j]);
				}
			}
		}
		tiles = list2.ToArray();
		tilePos = list.ToArray();
	}

	public void OnAfterDeserialize()
	{
		InitTileArray(_rowCount, _colCount, clearSerializedArrays: false);
		for (int i = 0; i < tiles.Length; i++)
		{
			this[(int)tilePos[i].x, (int)tilePos[i].y] = tiles[i];
		}
	}

