	public void Print(string layerName = "terrain", string tileLayerName = "")
	{
		if (grid == null)
		{
			Debug.Log("Null TileGrid");
			return;
		}
		string text = string.Empty;
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				if (this[i, j] == null)
				{
					text += "-";
					continue;
				}
				switch (layerName.ToLower())
				{
				case "terrain":
					text += (uint)this[i, j].terrain;
					break;
				case "connection":
					text += (uint)this[i, j].connection;
					break;
				case "overlay":
					text += (uint)this[i, j].overlay;
					break;
				case "obstacle":
					text = (this[i, j].obstacle ? (text + "x") : (text + (uint)this[i, j].terrain));
					break;
				case "hasenemy":
				{
					bool flag2 = false;
					text = ((!this[i, j].hasEnemy) ? (text + (uint)this[i, j].terrain) : (text + "x"));
					break;
				}
				case "hasdoodad":
				{
					bool flag = false;
					flag = ((!(tileLayerName != string.Empty)) ? this[i, j].hasDoodad : this[i, j].layers[tileLayerName].hasDoodad);
					text = ((!flag) ? (text + (uint)this[i, j].terrain) : (text + "x"));
					break;
				}
				case "tilesetid":
					text += Convert.ToInt32(this[i, j].layers[tileLayerName].tileSetID);
					break;
				default:
					Debug.Log("Invalid tileGrid print option");
					return;
				}
			}
			text += "\n";
		}
		Debug.Log(text);
	}

