	public int CountTilesInDir(int row, int col, Func<Tile, bool> comparisonFunc, MapOrdinalDirections dir, bool excludeFirstTile = true, int maxTiles = 40, bool endOnFailure = true)
	{
		int num = 0;
		Vector2 directionalOffset = Globals.GetDirectionalOffset(dir);
		for (int i = 0; i < maxTiles; i++)
		{
			if (i == 0 && excludeFirstTile)
			{
				continue;
			}
			Vector2 vector = i * directionalOffset;
			int num2 = (int)((float)row + vector.x);
			int num3 = (int)((float)col + vector.y);
			if (!IsValidTile(num2, num3))
			{
				if (endOnFailure)
				{
					return num;
				}
			}
			else if (!comparisonFunc(this[num2, num3]))
			{
				if (endOnFailure)
				{
					return num;
				}
			}
			else
			{
				num++;
			}
		}
		return num;
	}
