	public static void GetChildrenPolygonPaths(List<PolyNode> children, List<List<Vector2>> polyPaths, List<Vector2> polyPath = null)
	{
		for (int i = 0; i < children.Count; i++)
		{
			PolyNode polyNode = children[i];
			if (polyPath == null || !polyNode.IsHole)
			{
				polyPath = new List<Vector2>();
				polyPaths.Add(polyPath);
			}
			Vector2 item = Vector2.zero;
			for (int j = 0; j < polyNode.Contour.Count; j++)
			{
				Vector2 vector = new Vector2(polyNode.Contour[j].X, polyNode.Contour[j].Y);
				polyPath.Add(vector);
				if (j == 0)
				{
					item = vector;
				}
			}
			polyPath.Add(item);
			if (polyNode.Childs.Count > 0)
			{
				GetChildrenPolygonPaths(polyNode.Childs, polyPaths, polyPath);
			}
		}
	}
