	public static void GeneratePits(TileGrid tileGrid, Transform parentTrans = null)
	{
		GameObject gameObject = Globals.FindOrCreateGameObject("Colliders", parentTrans);
		parentTrans = gameObject.transform;
		GameObject gameObject2 = Globals.FindOrCreateGameObject("PitColliders", parentTrans);
		if (parentTrans != null)
		{
			gameObject2.transform.position = parentTrans.position;
			gameObject2.transform.SetParent(parentTrans);
		}
		gameObject2.tag = "BottomlessPit";
		gameObject2.layer = LayerMask.NameToLayer("Pit");
