		gameObject3.layer = LayerMask.NameToLayer("PreventFallPitCollider");
		Collider2D[] components2 = gameObject3.GetComponents<Collider2D>();
		foreach (Collider2D collider2D in components2)
		{
			collider2D.isTrigger = false;
		}
	}
}

