public class OverlayGenerator
{
	public static Tile.TerrainType[] validTerrainTypes = new Tile.TerrainType[3]
	{
		Tile.TerrainType.Floor,
		Tile.TerrainType.Wall,
		Tile.TerrainType.Pit
	};

	public static readonly Tile overlayCompleteTile = new Tile(Tile.TerrainType.None, Tile.OverlayType.Complete);

	private static WaitForFixedUpdate fixedWait = new WaitForFixedUpdate();

	public static bool overlayGenerationInProgress;

	public static Tile.OverlayType GetOverlayType(int row, int col, Tile[,] tileMap)
	{
		return GetOverlayTypeBase(tileMap[row, col], TileSet.GetAdjacentTerrainDirs(row, col, tileMap, validTerrainTypes));
	}

	public static Tile.OverlayType GetOverlayType(int row, int col, TileGrid tileGrid)
	{
		return GetOverlayTypeBase(tileGrid[row, col], GetOverlayAdjTerrainDirs(row, col, tileGrid));
	}

	public static MapOrdinalDirections GetOverlayAdjTerrainDirs(int tileRow, int tileCol, TileGrid tileGrid)
	{
		MapOrdinalDirections mapOrdinalDirections = MapOrdinalDirections.None;
		int colCount = tileGrid.ColCount;
		int rowCount = tileGrid.RowCount;
		if (tileRow < rowCount - 1 && tileGrid[tileRow + 1, tileCol] != null && (tileGrid[tileRow + 1, tileCol].terrain == Tile.TerrainType.Floor || tileGrid[tileRow + 1, tileCol].terrain == Tile.TerrainType.Pit || tileGrid[tileRow + 1, tileCol].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.South;
		}
		if (tileRow > 0 && tileGrid[tileRow - 1, tileCol] != null && (tileGrid[tileRow - 1, tileCol].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 1, tileCol].terrain == Tile.TerrainType.Pit || tileGrid[tileRow - 1, tileCol].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.North;
		}
		if (tileCol > 0 && tileGrid[tileRow, tileCol - 1] != null && (tileGrid[tileRow, tileCol - 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow, tileCol - 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow, tileCol - 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.West;
		}
		if (tileCol < colCount - 1 && tileGrid[tileRow, tileCol + 1] != null && (tileGrid[tileRow, tileCol + 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow, tileCol + 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow, tileCol + 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.East;
		}
		if (tileRow < rowCount - 1 && tileCol > 0 && tileGrid[tileRow + 1, tileCol - 1] != null && (tileGrid[tileRow + 1, tileCol - 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow + 1, tileCol - 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow + 1, tileCol - 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.SouthWest;
		}
		if (tileRow < rowCount - 1 && tileCol < colCount - 1 && tileGrid[tileRow + 1, tileCol + 1] != null && (tileGrid[tileRow + 1, tileCol + 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow + 1, tileCol + 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow + 1, tileCol + 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.SouthEast;
		}
		if (tileRow > 0 && tileCol > 0 && tileGrid[tileRow - 1, tileCol - 1] != null && (tileGrid[tileRow - 1, tileCol - 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 1, tileCol - 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow - 1, tileCol - 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.NorthWest;
		}
		if (tileRow > 0 && tileCol < colCount - 1 && tileGrid[tileRow - 1, tileCol + 1] != null && (tileGrid[tileRow - 1, tileCol + 1].terrain == Tile.TerrainType.Floor || tileGrid[tileRow - 1, tileCol + 1].terrain == Tile.TerrainType.Pit || tileGrid[tileRow - 1, tileCol + 1].terrain == Tile.TerrainType.Wall))
		{
			mapOrdinalDirections |= MapOrdinalDirections.NorthEast;
		}
		return mapOrdinalDirections;
	}

	public static Tile.OverlayType GetOverlayTypeBase(Tile curTile, MapOrdinalDirections validDirs)
	{
		bool flag = false;
		bool flag2 = validDirs.HasFlag(MapOrdinalDirections.East) || validDirs.HasFlag(MapOrdinalDirections.West);
		if (curTile != null)
		{
			flag = curTile.terrain == Tile.TerrainType.Floor || curTile.terrain == Tile.TerrainType.Wall || curTile.terrain == Tile.TerrainType.Pit;
		}
		else if (validDirs == MapOrdinalDirections.None)
		{
			return Tile.OverlayType.None;
		}
		if (validDirs.HasFlag(MapOrdinalDirections.South) && (validDirs.HasFlag(MapOrdinalDirections.SouthEast) || validDirs.HasFlag(MapOrdinalDirections.SouthWest)) && !flag2)
		{
			return Tile.OverlayType.TopWall;
		}
		if (!flag && validDirs.HasFlag(MapOrdinalDirections.East) && !validDirs.HasFlag(MapOrdinalDirections.South) && validDirs.HasFlag(MapOrdinalDirections.SouthEast))
		{
			return Tile.OverlayType.LeftWall;
		}
		if (!flag && validDirs.HasFlag(MapOrdinalDirections.West) && !validDirs.HasFlag(MapOrdinalDirections.South) && validDirs.HasFlag(MapOrdinalDirections.SouthWest))
		{
			return Tile.OverlayType.RightWall;
		}
		if (flag && !validDirs.HasFlag(MapOrdinalDirections.South) && !validDirs.HasFlag(MapOrdinalDirections.SouthEast) && !validDirs.HasFlag(MapOrdinalDirections.SouthWest))
		{
			return Tile.OverlayType.BottomWall;
		}
		if (validDirs.HasFlag(MapOrdinalDirections.SouthEast) && !validDirs.HasFlag(MapOrdinalDirections.East) && !validDirs.HasFlag(MapOrdinalDirections.South))
		{
			return Tile.OverlayType.TopLeftCorner;
		}
		if (validDirs.HasFlag(MapOrdinalDirections.SouthWest) && !validDirs.HasFlag(MapOrdinalDirections.West) && !validDirs.HasFlag(MapOrdinalDirections.South))
		{
			return Tile.OverlayType.TopRightCorner;
		}
		if (validDirs == (MapOrdinalDirections.East | MapOrdinalDirections.North | MapOrdinalDirections.NorthEast) || (!flag && !validDirs.HasFlag(MapOrdinalDirections.South) && validDirs.HasFlag(MapOrdinalDirections.East)))
		{
			return Tile.OverlayType.BottomLeftCorner;
		}
		if (validDirs == (MapOrdinalDirections.West | MapOrdinalDirections.North | MapOrdinalDirections.NorthWest) || (!flag && !validDirs.HasFlag(MapOrdinalDirections.South) && validDirs.HasFlag(MapOrdinalDirections.West)))
		{
			return Tile.OverlayType.BottomRightCorner;
		}
		if (!flag && validDirs.HasFlag(MapOrdinalDirections.East) && validDirs.HasFlag(MapOrdinalDirections.South))
		{
			return Tile.OverlayType.BottomRightWall;
		}
		if (!flag && validDirs.HasFlag(MapOrdinalDirections.West) && validDirs.HasFlag(MapOrdinalDirections.South))
		{
			return Tile.OverlayType.BottomLeftWall;
		}
		if (flag && !validDirs.HasFlag(MapOrdinalDirections.South) && !validDirs.HasFlag(MapOrdinalDirections.SouthWest))
		{
			return Tile.OverlayType.TopRightWall;
		}
		if (flag && !validDirs.HasFlag(MapOrdinalDirections.South) && !validDirs.HasFlag(MapOrdinalDirections.SouthEast))
		{
			return Tile.OverlayType.TopLeftWall;
		}
		return Tile.OverlayType.None;
	}

	public static void GenerateDirectionalOverlay(Tile[,] tileMap)
	{
		int length = tileMap.GetLength(0);
		int length2 = tileMap.GetLength(1);
		for (int i = 0; i < length; i++)
		{
			for (int j = 0; j < length2; j++)
			{
				Tile.OverlayType overlayType = GetOverlayType(i, j, tileMap);
				Tile tile = tileMap[i, j];
				if (tile == null)
				{
					if (overlayType == Tile.OverlayType.None)
					{
						continue;
					}
					tileMap[i, j] = new Tile();
					tile = tileMap[i, j];
				}
				tile.overlay = overlayType;
			}
		}
	}

	public static IEnumerator GenerateOverlay(TileGrid tileGrid, int thickness, int yieldInterval = 64)
	{
		overlayGenerationInProgress = true;
		int heightComparison = tileGrid.RowCount - thickness + 1;
		int widthComparison = tileGrid.ColCount - thickness + 1;
		bool yIsZero = false;
		bool yIsNeg = false;
		bool xIsZero = false;
		bool xIsNeg = false;
		bool tileIsValid = false;
		for (int row = thickness - 1; row < heightComparison; row++)
		{
			for (int i = thickness - 1; i < widthComparison; i++)
			{
				Tile.OverlayType overlayType = GetOverlayType(row, i, tileGrid);
				if (overlayType == Tile.OverlayType.None)
				{
					continue;
				}
				if (tileGrid[row, i] == null)
				{
					tileGrid[row, i] = new Tile(Tile.TerrainType.None, overlayType);
				}
				else if (overlayType != Tile.OverlayType.Complete || tileGrid[row, i].overlay == Tile.OverlayType.None)
				{
					tileGrid[row, i].overlay = overlayType;
				}
				Tile currentTile = tileGrid[row, i];
				tileIsValid = false;
				switch (currentTile.overlay)
				{
				case Tile.OverlayType.TopWall:
					yIsZero = false;
					yIsNeg = true;
					xIsZero = true;
					xIsNeg = false;
					tileIsValid = true;
					break;
				case Tile.OverlayType.LeftWall:
					yIsZero = true;
					yIsNeg = false;
					xIsZero = false;
					xIsNeg = true;
					tileIsValid = true;

					tileIsValid = true;
					break;
				case Tile.OverlayType.RightWall:
					yIsZero = true;
					yIsNeg = false;
					xIsZero = false;
					xIsNeg = false;
					tileIsValid = true;
					break;
				case Tile.OverlayType.BottomWall:
					yIsZero = false;
					yIsNeg = false;
					xIsZero = true;
					xIsNeg = false;
					tileIsValid = true;
					break;
				case Tile.OverlayType.TopLeftCorner:
					yIsZero = false;
					yIsNeg = true;
					xIsZero = false;
					xIsNeg = true;
					tileIsValid = true;
					break;
				case Tile.OverlayType.TopRightCorner:
					yIsZero = false;
					yIsNeg = true;
					xIsZero = false;
					xIsNeg = false;
					tileIsValid = true;
					break;
				case Tile.OverlayType.BottomLeftCorner:
					yIsZero = false;
					yIsNeg = false;
					xIsZero = false;
					xIsNeg = true;
					tileIsValid = true;
					break;
				case Tile.OverlayType.BottomRightCorner:
					yIsZero = false;
					yIsNeg = false;
					xIsZero = false;
					xIsNeg = false;
					tileIsValid = true;
					break;
				}
				if (!tileIsValid)
				{
					continue;
				}
				for (int j = 0; j < thickness; j++)
				{
					for (int k = 0; k < thickness; k++)
					{
						if (j != 0 || k != 0)
						{
							int innerHeight = ((!yIsZero) ? ((!yIsNeg) ? j : (-j)) : 0);
							int innerWidth = ((!xIsZero) ? ((!xIsNeg) ? k : (-k)) : 0);
							Tile tile = tileGrid[row + innerHeight, i + innerWidth];
							if (tile == null)
							{
								tileGrid[row + innerHeight, i + innerWidth] = new Tile(Tile.TerrainType.None, Tile.OverlayType.Complete);
							}
							else if (tile.overlay == Tile.OverlayType.None && (tile.terrain == Tile.TerrainType.None || tile.terrain == Tile.TerrainType.Impassable))
							{
								tile.overlay = Tile.OverlayType.Complete;
							}
						}
					}
				}
			}
			if (yieldInterval > 0 && row % yieldInterval == 0)
			{
				yield return fixedWait;
			}
		}
		overlayGenerationInProgress = false;
	}
}

