public class GridDecoGroupManager
{
	public Dictionary<string, List<IGridDecorator>> groups;

	public GridDimensions dimensions;

	public IntVec2[] availableDimensions;

	public Dictionary<IntVec2, List<List<IGridDecorator>>> dimensionToGridGroups;

	public GridDecoGroupManager()
	{
		dimensions = new GridDimensions();
		groups = new Dictionary<string, List<IGridDecorator>>();
		availableDimensions = new IntVec2[0];
		dimensionToGridGroups = new Dictionary<IntVec2, List<List<IGridDecorator>>>();
	}

	public void Remove(string decoGroupName)
	{
		if (groups.ContainsKey(decoGroupName))
		{
			groups.Remove(decoGroupName);
		}
	}

	public void Add(string decoGroupName, IGridDecorator newGridDeco)
	{
		if (newGridDeco == null)
		{
			return;
		}
		if (!groups.ContainsKey(decoGroupName))
		{
			groups[decoGroupName] = new List<IGridDecorator>();
		}
		List<IGridDecorator> list = groups[decoGroupName];
		if (list.Count > 0 && (list[0].RowCount != newGridDeco.RowCount || list[0].ColCount != newGridDeco.ColCount))
		{
			throw new ArgumentException("Provided GridDecorator for group \"" + decoGroupName + "\" does not have matching dimensions compared to already existing GridDecorators " + list[0].RowCount + "x" + list[0].ColCount + " vs " + newGridDeco.RowCount + "x" + newGridDeco.ColCount);
		}
		newGridDeco.GroupName = decoGroupName;
		list.Add(newGridDeco);
		if (list.Count == 1)
		{
			IntVec2 key = new IntVec2(newGridDeco.RowCount, newGridDeco.ColCount);
			if (!dimensionToGridGroups.ContainsKey(key))
			{
				dimensionToGridGroups[key] = new List<List<IGridDecorator>>();
			}
			dimensionToGridGroups[key].Add(list);
		}
		availableDimensions = dimensionToGridGroups.Keys.ToArray();
		int num = 0;
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		for (int i = 0; i < availableDimensions.Length; i++)
		{
			if (num == 0 || num > availableDimensions[i].x)
			{
				num = availableDimensions[i].x;
			}
			if (num2 == 0 || num2 < availableDimensions[i].x)
			{
				num2 = availableDimensions[i].x;
			}
			if (num3 == 0 || num3 > availableDimensions[i].y)
			{
				num3 = availableDimensions[i].y;
			}
			if (num4 == 0 || num4 < availableDimensions[i].y)
			{
				num4 = availableDimensions[i].y;
			}
		}
		dimensions.MinRows = num;
		dimensions.MaxRows = num2;
		dimensions.MinCols = num3;
		dimensions.MaxCols = num4;
	}
}
