	if (tileGrid == null)
	{
		return GetDefaultFloorTile();
	}
	curPitFloorTileSetID = PitFloorToTileSetID(tileRow, tileCol, tileGrid);
	if (curPitFloorTileSetID != -1)
	{
		return curPitFloorTileSetID;
	}
	curPathFloorTileSetID = PathFloorToTileSetID(tileRow, tileCol, tileGrid);
	if (curPathFloorTileSetID != -1)
	{
		return curPathFloorTileSetID;
	}
	curPitOverrideTileSetID = PitOverrideToTileSetID(tileRow, tileCol, tileGrid);
	if (curPitOverrideTileSetID != -1)
	{
		return curPitOverrideTileSetID;
	}
	switch (GetFloorType(tileGrid, tileRow, tileCol, (Tile t) => t.terrain == Tile.TerrainType.Floor))
	{
	case Tile.FloorType.Top:
		return topFloorTiles.GetRandomValue();
	case Tile.FloorType.TopLeft:
		return topLeftFloorTile;
	case Tile.FloorType.TopRight:
		return topRightFloorTile;
	case Tile.FloorType.Left:
		return leftFloorTiles.GetRandomValue();
	case Tile.FloorType.Center:
		tileGrid[tileRow, tileCol].layers["Floor"].flipX = UnityEngine.Random.value < 0.5f;
		if (UnityEngine.Random.value >= 1f - floorVarChance)
		{
			return floorVarTiles.GetRandomValue();
		}
		return GetDefaultFloorTile();
	case Tile.FloorType.Right:
		return rightFloorTiles.GetRandomValue();
	case Tile.FloorType.Bottom:
		return botFloorTiles.GetRandomValue();
	case Tile.FloorType.BottomLeft:
		return botLeftFloorTile;
	case Tile.FloorType.BottomRight:
		return botRightFloorTile;
	case Tile.FloorType.TopLeftCorner:
		return topLeftCornerFloorTile;
	case Tile.FloorType.TopRightCorner:
		return topRightCornerFloorTile;
	case Tile.FloorType.BotLeftCorner:
		return botLeftCornerFloorTile;
	case Tile.FloorType.BotRightCorner:
		return botRightCornerFloorTile;
	default:
		return GetDefaultFloorTile();
	}
}

