	protected int lifeStopwatchID;

	public bool autoPickup = true;

	public bool increaseSpeedOverTime;

	public float speedModifier = 3f;

	private float currentSpeed;

	private float originalSpeed;

	public float autoPickupRange = 3f;

	public float autoPickupDelay;

	public float autoPickupDelayTimer;

	public bool finishedMoving;

	public bool stopMovementOnFall;

	public float fallRadius = 0.25f;

	[HideInInspector]
	public Collider2D itemFloorCollider;

	private int movingStopwatchID;

	public float maxMovingTime = 1f;

	public Vector2 targetVector;

	public float initXDistance;

	private float initHeight;

	private bool finishedUpMove;

	private float simGrav;

	public CircleCollider2D pickupCollider;

	[HideInInspector]
	public List<Player> players;

	[HideInInspector]
	public Movement movement;

	[HideInInspector]
	public TargetInfo targetPlayerInfo;

	public bool requireInteract;

	private static ParticleSystemOverride _sparkleOverride;

	private OverheadPrompt overHeadPrompt;

	[HideInInspector]
	public float overheadPromptHeight = 3f;

	private NumVarStatMod speedUpOverTimeMod;

	public float LifeTimeRemaining => ChaosStopwatch.GetRemainingTime(lifeStopwatchID);

	public static ParticleSystemOverride SparkleOverride
	{
		get
		{
			if (_sparkleOverride == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.radius = 0.1f;
				particleSystemOverride.startLifetime = 1f;
				_sparkleOverride = particleSystemOverride;
			}
			return _sparkleOverride;
		}
	}

	public OverheadPrompt CurrentOverheadPrompt
	{
		get
		{
			return overHeadPrompt ?? (overHeadPrompt = PoolManager.GetPoolItem<OverheadPrompt>());
		}
		set
		{
			if (value == null && overHeadPrompt != null)
			{
				overHeadPrompt.HidePrompt(string.Empty);
				overHeadPrompt = null;
			}
		}
	}

	public virtual void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
		movement = GetComponent<Movement>();
		if (movement != null)
		{
			speedUpOverTimeMod = new NumVarStatMod("SpeedUpOverTime", 0f, 10, VarStatModType.Override);
			currentSpeed = movement.moveSpeedStat.CurrentValue;
			originalSpeed = movement.moveSpeedStat.CurrentValue;
		}
		Transform transform = base.transform.Find("ItemFloorCollider");
		if (transform != null)
		{
			itemFloorCollider = transform.GetComponent<Collider2D>();
		}
		Transform transform2 = base.transform.Find("ItemHitBox");
		if (transform2 != null)
		{
			pickupCollider = transform2.GetComponent<CircleCollider2D>();
		}
	}

	public virtual void Activate(bool disableActivationSFX = false)
	{
		gameObject.SetActive(value: true);
		movingStopwatchID = ChaosStopwatch.Begin(maxMovingTime);
		if (useLifeTime)
		{
			lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		}
	}

	public virtual void Disable()
	{
		Reset();
		gameObject.SetActive(value: false);
	}

	public virtual void Update()
	{
		if (useLifeTime && ChaosStopwatch.Check(lifeStopwatchID))
		{
			Disable();
			return;
		}
		Player player = HandleInteractRequirement();
		if (player != null)
		{
			OnInteract(player);
		}
	}

	public virtual void FixedUpdate()
	{
		if (!finishedMoving && movement != null && !ChaosStopwatch.Check(movingStopwatchID))
		{
			if (stopMovementOnFall && !Globals.CheckCircle(transform.position, fallRadius, ChaosCollisions.layerPit))
			{
				finishedMoving = true;
				movement.EndMovement();
				itemFloorCollider.enabled = false;
				return;
			}
			movement.MoveToTarget(targetVector, 0.02f, simGrav);
			if (Mathf.Abs(targetVector.x - transform.position.x) > initXDistance)
			{
				simGrav -= 10f * Time.fixedDeltaTime;
				targetVector.y += 5f * Time.fixedDeltaTime;
			}
			else
			{
				finishedUpMove = true;
				simGrav += 10f * Time.fixedDeltaTime;
				targetVector.y -= 5f * Time.fixedDeltaTime;
			}
			if (transform.position.y < initHeight && finishedUpMove)
			{
				finishedMoving = true;
				movement.EndMovement();
			}
		}
		else if (autoPickupDelayTimer > 0f)
		{
			autoPickupDelayTimer -= Time.fixedDeltaTime;
		}
		else
		{
			if (!autoPickup || !(movement != null))
			{
				return;
			}
			if (!lockOnPlayer || targetPlayerInfo == null)
			{
				targetPlayerInfo = Entity.GetClosestTarget(GameController.players, transform.position, autoPickupRange, playerTagOnly: true);
			}
			if (targetPlayerInfo != null && targetPlayerInfo.hurtBoxTransform != null)
			{
				if (increaseSpeedOverTime && movement != null)
				{
					currentSpeed = Mathf.Clamp(currentSpeed + Time.fixedDeltaTime * speedModifier, originalSpeed * 0.5f, originalSpeed * 3f);
					speedUpOverTimeMod.modValue = currentSpeed;
					movement.moveSpeedStat.AddMod(speedUpOverTimeMod);
				}
				movement.MoveToTarget(targetPlayerInfo.hurtBoxTransform.position);
			}
			else
			{
				ResetMovement();
			}
		}
	}

	public void SetInitDistance()
	{
		initXDistance = Mathf.Abs(targetVector.x - transform.position.x);
		initXDistance *= 0.5f;
		initHeight = targetVector.y;
		finishedUpMove = false;
		finishedMoving = false;
		simGrav = 12f;
	}

	public void ResetMovement()
	{
		if (!(movement == null))
		{
			currentSpeed = movement.moveSpeedStat.CurrentValue;
			movement.moveSpeedStat.RemoveMod(speedUpOverTimeMod.ID);
			movement.EndMovement();
		}
	}

	public virtual void Reset()
	{
		ResetMovement();
		autoPickupDelayTimer = autoPickupDelay;
		targetPlayerInfo = null;
		CurrentOverheadPrompt = null;
		players.Clear();
	}

	public Player HandleInteractRequirement()
	{
		if (!requireInteract || players.Count == 0)
		{
			return null;
		}
		for (int i = 0; i < players.Count; i++)
		{
			IState currentState = players[i].fsm.currentState;
			if (players[i].inputDevice.GetButtonDown("Interact"))
			{
				if (currentState.name.Contains("Idle") || currentState.name.Contains("Run"))
				{
					players[i].fsm.QueueChangeState(players[i].fsm.defaultStateName);
					return players[i];
				}
				if (currentState is Player.SkillState && (currentState as Player.SkillState).isDash)
				{
					return players[i];
				}
			}
		}
		return null;
	}

	public void BaseOnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.tag == "Player")
		{
			CurrentOverheadPrompt = null;
			if (col.transform.parent != null)
			{
				players.Remove(col.transform.parent.GetComponent<Player>());
			}
		}
	}

	public virtual void OnInteract(Player player)
	{
		if (!(player == null))
		{
			Disable();
		}
	}
}
