		}
		isCollected = true;
		transform.position = col.transform.position;
		debtValue = Player.goldDebtWallet.balance;
		if (debtValue > 0)
		{
			if (value >= debtValue)
			{
				value -= debtValue;
				Player.goldDebtWallet.Withdraw(Player.goldDebtWallet.balance);
			}
			else
			{
				Player.goldDebtWallet.Withdraw(value);
				SoundManager.PlayAudio("CoinDebt");
				OverheadNumberPool.DisplayOverheadNumber("+" + value, transform.position, goldTextColor, OverheadNumber.defaultBorderColor, transform.position, transform, 0.5f);
				value = 0;
			}
		}
		GameController.levelGold += value;
		GameController.totalGold += value;
		if (value > 0)
		{
			Player.goldWallet.Deposit(value);
			OverheadNumberPool.DisplayOverheadNumber("+" + value, transform.position, goldTextColor, OverheadNumber.defaultBorderColor, transform.position, transform, 0.5f);
			SoundManager.PlayAudio("Coin");
		}
		anim.Play("Pickup", -1, 0f);
	}

