	{
		switch (coinType)
		{
		case CoinType.Bronze:
			sprite.color = bronzeColor;
			value = 1;
			break;
		case CoinType.Silver:
			sprite.color = silverColor;
			value = 5;
			break;
		case CoinType.Gold:
			sprite.color = goldColor;
			value = 10;
			break;
		}
		anim.Play("Spin");
	}

