public class ItemSpawner : MonoBehaviour
{
	[Serializable]
	public class ItemPoolEntry
	{
		public GameObject itemPrefab;

		public int itemPoolCount;

		public PoolType poolType;

		public int currentPoolIndex;

		[HideInInspector]
		public PickupItem[] itemArray;
	}

	public enum PoolType
	{
		Gold,
		HealthPowerup,
		ManaPowerup,
		SkillDrop,
		SoulPowerup,
		ItemDrop,
		Platinum
	}

	public List<ItemPoolEntry> itemPrefabs;

	public Dictionary<PoolType, ItemPoolEntry> itemPoolDict;

	private Collider2D[] spawnLocationCheck;

	private static ItemSpawner instance;

	public static ItemSpawner Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			UnityEngine.Object.Destroy(gameObject);
			return;
		}
		instance = this;
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
		spawnLocationCheck = new Collider2D[50];
		itemPoolDict = new Dictionary<PoolType, ItemPoolEntry>();
	}

	private void Start()
	{
		foreach (ItemPoolEntry itemPrefab in itemPrefabs)
		{
			if (itemPrefab != null && itemPrefab.itemPrefab != null)
			{
				GameObject gameObject = new GameObject();
				gameObject.transform.SetParent(transform);
				itemPrefab.itemArray = new PickupItem[itemPrefab.itemPoolCount];
				gameObject.name = itemPrefab.poolType.ToString() + "Pool";
				for (int i = 0; i < itemPrefab.itemPoolCount; i++)
				{
					GameObject gameObject2 = UnityEngine.Object.Instantiate(itemPrefab.itemPrefab);
					itemPrefab.itemArray[i] = gameObject2.GetComponent<PickupItem>();
					gameObject2.transform.SetParent(gameObject.transform);
				}
				itemPoolDict[itemPrefab.poolType] = itemPrefab;
			}
		}
		Reset();
	}

	public void Reset()
	{
		foreach (ItemPoolEntry value in itemPoolDict.Values)
		{
			PickupItem[] itemArray = value.itemArray;
			foreach (PickupItem pickupItem in itemArray)
			{
				pickupItem.Disable();
			}
		}
	}

	public PickupItem GetCurrentItem(PoolType poolType)
	{
		ItemPoolEntry itemPoolEntry = null;
		if (!itemPoolDict.ContainsKey(poolType) || itemPoolDict[poolType] == null)
		{
			return null;
		}
		itemPoolEntry = itemPoolDict[poolType];
		if (itemPoolEntry.currentPoolIndex >= itemPoolEntry.itemPoolCount)
		{
			itemPoolEntry.currentPoolIndex = 0;
		}
		int currentPoolIndex = itemPoolEntry.currentPoolIndex;
		itemPoolEntry.currentPoolIndex++;
		return itemPoolEntry.itemArray[currentPoolIndex];
	}

	public PickupItem SpawnItem(PoolType poolType, Vector2 spawnLocation, bool randomizeSpawnLocation = true, float randomRange = 1.5f, string otherValue = "", bool useMinDist = false, bool useLifeTime = false, bool randomizeMovement = true, bool disableActivationSFX = false)
	{
		PickupItem currentItem = GetCurrentItem(poolType);
		if (currentItem == null)
		{
			return null;
		}
		currentItem.Reset();
		currentItem.useLifeTime = useLifeTime;
		switch (poolType)
		{
		case PoolType.ItemDrop:
			(currentItem as ItemDrop).itemID = otherValue;
			break;
		case PoolType.SkillDrop:
		{
			SkillDrop skillDrop = (SkillDrop)currentItem;
			string text = otherValue;
			if (otherValue.StartsWith("New"))
			{
				skillDrop.lockedSkillSelected = true;
				text = text.Substring(3);
			}
			if (otherValue.EndsWith("Signature"))
			{
				skillDrop.isSignature = true;
				text = text.Substring(0, text.Length - 9);
			}
			if (otherValue.EndsWith("Empowered"))
			{
				skillDrop.isEmpowered = true;
				text = text.Substring(0, text.Length - 9);
			}
			skillDrop.skillID = text;
			break;
		}
		case PoolType.SoulPowerup:
			currentItem.useLifeTime = true;
			break;
		}
		currentItem.transform.position = spawnLocation;
		if (randomizeSpawnLocation)
		{
			Vector2 randomSpawnLocation = GetRandomSpawnLocation(spawnLocation, randomRange, useMinDist);
			randomSpawnLocation = Entity.GetAvailableNearbyLocation(randomSpawnLocation);
			if (randomSpawnLocation != Vector2.zero)
			{
				currentItem.targetVector = randomSpawnLocation;
				currentItem.SetInitDistance();
				currentItem.finishedMoving = false;
			}
			else
			{
				currentItem.finishedMoving = true;
			}
		}
		else
		{
			currentItem.finishedMoving = true;
		}
		currentItem.Activate(disableActivationSFX);
		if (randomizeMovement && currentItem.rigidbody2D != null && currentItem.finishedMoving)
		{
			currentItem.rigidbody2D.MovePosition(spawnLocation.Randomize(1f, 0.125f));
		}
		return currentItem;
	}

	public void SpawnItemWithCount(PoolType poolType, Vector2 spawnLocation, int count, bool randomizedSpawnLocation = true, float randomRange = 1.5f)
	{
		for (int i = 0; i < count; i++)
		{
			SpawnItem(poolType, spawnLocation, randomizedSpawnLocation, randomRange, string.Empty);
		}
	}

	public void SpawnItemBetweenMinMax(PoolType poolType, Vector2 spawnOrigin, int minCount = 1, int maxCount = 1)
	{
		int num = UnityEngine.Random.Range(minCount, maxCount);
		for (int i = 0; i < num; i++)
		{
			SpawnItem(poolType, spawnOrigin, randomizeSpawnLocation: true, 1.5f, string.Empty);
		}
	}

	public void SpawnItemWithChance(PoolType poolType, Vector2 spawnOrigin, float spawnChance)
	{
		if (UnityEngine.Random.Range(0f, 1f) > 1f - spawnChance)
		{
			SpawnItem(poolType, spawnOrigin, randomizeSpawnLocation: true, 1.5f, string.Empty);
		}
	}

	public Vector2 GetRandomSpawnLocation(Vector2 spawnOrigin, float range = 1.5f, bool useMinDist = false)
	{
		float num;
		float num2;
		if (useMinDist)
		{
			num = ((UnityEngine.Random.Range(0, 2) != 0) ? UnityEngine.Random.Range(1f, range) : UnityEngine.Random.Range(0f - range, -1f));
			num2 = ((UnityEngine.Random.Range(0, 2) != 0) ? UnityEngine.Random.Range(1f, range) : UnityEngine.Random.Range(0f - range, -1f));
		}
		else
		{
			num = UnityEngine.Random.Range(0f - range, range);
			num2 = UnityEngine.Random.Range(0f - range, range);
		}
		Vector2 vector = new Vector2(spawnOrigin.x + num, spawnOrigin.y + num2);
		Array.Clear(spawnLocationCheck, 0, spawnLocationCheck.Length);
		Physics2D.OverlapPointNonAlloc(vector, spawnLocationCheck);
		Collider2D[] array = spawnLocationCheck;
		foreach (Collider2D collider2D in array)
		{
			if (collider2D != null && collider2D.gameObject.layer == LayerMask.NameToLayer("Wall"))
			{
				return spawnOrigin;
			}
		}
		return vector;
	}

	public void SpawnGoldValue(int value, Vector2 spawnOrigin, bool randomizeSpawnLocation = true, float spawnRange = 1.5f)
	{
		StartCoroutine(SpawnGoldVal(value, spawnOrigin, randomizeSpawnLocation, spawnRange));
	}

	private IEnumerator SpawnGoldVal(int val, Vector2 origin, bool randomSpawnLoc = true, float range = 1.5f)
	{
		while (val > 0)
		{
			CoinType value = UnityEngine.Random.Range(0, 3) switch
			{
				0 => CoinType.Bronze, 
				1 => (val >= 5) ? CoinType.Silver : CoinType.Bronze, 
				2 => (val >= 10) ? CoinType.Gold : ((val >= 5) ? CoinType.Silver : CoinType.Bronze), 
				_ => CoinType.Bronze, 
			};
			Gold gold = GameController.itemSpawner.SpawnItem(PoolType.Gold, origin, randomSpawnLoc, range, string.Empty) as Gold;
			gold.SetValue(value);
			val -= gold.value;
		}
		yield break;
	}
}

