				canvasBG = transform.GetComponent<Image>();
			}
			transform = canvasTrans.Find("InfoContainer");
			if (transform != null)
			{
				infoBoxObj = transform.gameObject;
			}
		}
		ToggleItemInfo(status: false);
		priceMarkerPrefab = ChaosBundle.Get("Assets/Prefabs/Environment/Store/PriceMarker.prefab");
	}

	public void UpdatePrice(string forceTopText = null)
	{
		if (!(priceMarker == null) && !(priceMarker.GetText() == "x"))
		{
			if (topText != null && forceTopText != null)
			{
				topText.text = forceTopText;
			}
			priceMarker.SetText(Cost.ToString());
		}
	}

	public virtual void Start()
	{
		Vector2 vector = transform.position;
		vector.y += priceMarkerYOffset;
		priceMarker = Globals.ChaosInst<PriceMarker>(priceMarkerPrefab, transform.parent, vector);
		priceMarker.SetText(Cost.ToString());
		priceMarker.PlatinumMarker = usePlatinumCost;
		if (disablePriceMarker)
		{
			priceMarker.gameObject.SetActive(value: false);
		}
	}

	private void ToggleVisibility(bool status)
	{
		if (visible == status)
		{
			visible = !visible;
			if (visible)
			{
				StartCoroutine(ShowSelf());
			}
			else
			{
				StartCoroutine(HideSelf());
			}
		}
	}

	private IEnumerator ShowSelf()
	{
		Collider2D[] componentsInChildren = GetComponentsInChildren<Collider2D>();
		foreach (Collider2D collider2D in componentsInChildren)
		{
			collider2D.enabled = true;
		}
		Graphic[] componentsInChildren2 = GetComponentsInChildren<Graphic>();
		foreach (Graphic graphic in componentsInChildren2)
		{
			graphic.CrossFadeAlpha(1f, 1f, ignoreTimeScale: false);
		}
		bool transitionComplete = false;
		while (visible && !transitionComplete)
		{
			transitionComplete = true;
			if (itemSpriteRenderer.color.a < itemSpriteAlpha)
			{
				tempColor = itemSpriteRenderer.color;
				tempColor.a += Time.deltaTime;
				itemSpriteRenderer.color = tempColor;
				transitionComplete = false;
			}
			else
			{
				tempColor = itemSpriteRenderer.color;
				tempColor.a = itemSpriteAlpha;
				itemSpriteRenderer.color = tempColor;
			}
			if (itemBGSpriteRenderer.color.a < itemBGAlpha)
			{
				tempColor = itemBGSpriteRenderer.color;
				tempColor.a += Time.deltaTime;
				itemBGSpriteRenderer.color = tempColor;
				transitionComplete = false;
			}
			else
			{
				tempColor = itemBGSpriteRenderer.color;
				tempColor.a = itemBGAlpha;
				itemBGSpriteRenderer.color = tempColor;
			}
			if (itemLight.intensity < itemLightIntensity)
			{
				itemLight.intensity += Time.deltaTime * 2f;
				transitionComplete = false;
			}
			else
			{
				itemLight.intensity = itemLightIntensity;
			}
			yield return null;
		}
	}

	private IEnumerator HideSelf()
	{
		shoppers.Clear();
		CurrentOverheadPrompt = null;
		Collider2D[] componentsInChildren = GetComponentsInChildren<Collider2D>();
		foreach (Collider2D collider2D in componentsInChildren)
		{
			collider2D.enabled = false;
		}
		Graphic[] componentsInChildren2 = GetComponentsInChildren<Graphic>();
		foreach (Graphic graphic in componentsInChildren2)
		{
			graphic.CrossFadeAlpha(0f, 1f, ignoreTimeScale: false);
		}
		bool transitionComplete = false;
		while (!visible && !transitionComplete)
		{
			transitionComplete = true;
			if (itemSpriteRenderer.color.a > 0f)
			{
				tempColor = itemSpriteRenderer.color;
				tempColor.a -= Time.deltaTime;
				itemSpriteRenderer.color = tempColor;
				transitionComplete = false;
			}
			if (itemBGSpriteRenderer.color.a > 0f)
			{
				tempColor = itemBGSpriteRenderer.color;
				tempColor.a -= Time.deltaTime;
				itemBGSpriteRenderer.color = tempColor;
				transitionComplete = false;
			}
			if (itemLight.intensity > 0f)
			{
				itemLight.intensity -= Time.deltaTime * 2f;
				transitionComplete = false;
			}
			yield return null;
		}
	}

	public virtual void Update()
	{
		ToggleVisibility(Entity.GetAllTargetsInRange(GameController.enemies, transform.position, disableRange).Count > 0);
		if (shoppers.Count == 0)
		{
			return;
		}
		List<Player> list = new List<Player>();
		foreach (Player shopper in shoppers)
		{
			if (shopper == null)
			{
				list.Add(shopper);
				continue;
			}
			if (shopper.inputDevice.GetButtonDown("Interact") && (shopper.fsm.currentStateName.Contains("Idle") || shopper.fsm.currentStateName.Contains("Run")))
			{
				shopper.fsm.QueueChangeState(shopper.fsm.defaultStateName);
				Buy(shopper);
				break;
			}
			if (Vector2.SqrMagnitude(shopper.hurtBoxTransform.position - transform.position) > 10f)
			{
				list.Add(shopper);
			}
		}
		foreach (Player item in list)
		{
			RemoveShopper(item);
		}
	}

	public virtual bool Buy(Player givenPlayer)
	{
		AnnounceBalanceCheckEvent(givenPlayer, this);
		if (Player.goldWallet.balance < Cost)
		{
			SoundManager.PlayAudio("MenuError");
			if (parentNpc != null)
			{
				parentNpc.PlayEmote(EmoteType.No);
			}
			return false;
		}
		int finalCost = Cost;
		AnnouncePreBuyEvent(givenPlayer, this, ref finalCost);
		Player.goldWallet.Withdraw(finalCost);
		if (finalCost > 0)
		{
			SoundManager.PlayAudio("MenuBuy");
			HandleGoldEndStat(givenPlayer);
		}
		CurrentOverheadPrompt = null;
		priceMarker.SetText("x");
		AnnounceBuyEvent(givenPlayer, this);
		if (parentNpc != null)
		{
			parentNpc.PlayDefaultEmote();
		}
		return true;
	}

	public void AnnounceBalanceCheckEvent(Player player, StoreItem storeItem)
	{
		if (globalBalanceCheckEventHandlers != null)
		{
			globalBalanceCheckEventHandlers(player, storeItem);
		}
	}

	public void AnnouncePreBuyEvent(Player player, StoreItem storeItem, ref int finalCost)
	{
		if (globalPreBuyEventHandlers != null)
		{
			globalPreBuyEventHandlers(player, storeItem, ref finalCost);
		}
	}

	public void AnnounceBuyEvent(Player player, StoreItem storeItem)
	{
		if (buyEventHandlers != null)
		{
			buyEventHandlers(player, storeItem);
		}
		if (globalBuyEventHandlers != null)
		{
			globalBuyEventHandlers(player, storeItem);
		}
	}

	public virtual void HandleGoldEndStat(Player givenPlayer = null)
	{
		if (givenPlayer != null)
		{
			givenPlayer.stats.ModifyValue(PlayerEndStats.Stat.Spent, Cost);
		}
	}

	public void RemoveShopper(Player shopper)
	{
		shoppers.Remove(shopper);
		if (shoppers.Count == 0)
		{
			CurrentOverheadPrompt = null;
		}
		ToggleItemInfo(status: false);
	}

	public void ToggleItemInfo(bool status = true)
	{
		if (topText != null)
		{
			topText.enabled = !status;
		}
		if (infoBoxObj != null)
		{
			infoBoxObj.SetActive(status);
		}
		else
		{
			itemText.enabled = status;
		}
	}

	public void SetCanvasStatus(bool status)
	{
		if (canvasTrans != null)
		{
			canvasTrans.gameObject.SetActive(status);
		}
	}

	public void SetPriceMarkerStatus(bool status)
	{
		if (priceMarker != null)
		{
			priceMarker.gameObject.SetActive(!status);
		}
	}

	public void SetPromptTriggerStatus(bool status)
	{
		if (promptTrigger != null)
		{
			promptTrigger.gameObject.SetActive(status);
		}
	}

	public void SetLightStatus(bool status)
	{
		if (itemLight != null)
		{
			itemLight.gameObject.SetActive(status);
		}
	}

	public void SetAllowedPlayerID(int givenID)
	{
		allowedShopperID = givenID;
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (Entity.GetAllTargetsInRange(GameController.enemies, transform.position, disableRange).Count > 0)
		{
			OnTriggerExit2D(col);
		}
		else
		{
			if (!(col.gameObject.name == "AllyFloorContact") || !(col.gameObject.tag == "Player"))
			{
				return;
			}
			triggeringPlayer = col.transform.parent.gameObject.GetComponent<Player>();
			if (!PlayerIsValid(triggeringPlayer))
			{
				return;
			}
			if (triggeringPlayer.fsm.currentStateName.Contains("Dead"))
			{
				RemoveShopper(triggeringPlayer);
				return;
			}
			if (!shoppers.Contains(triggeringPlayer))
			{
				shoppers.Add(triggeringPlayer);
			}
			CurrentOverheadPrompt.Initialize(transform, triggeringPlayer.inputDevice.inputScheme, overheadPromptHeight);
			CurrentOverheadPrompt.DisplayPrompt("Interact");
			ToggleItemInfo();
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact" && col.gameObject.tag == "Player")
		{
			triggeringPlayer = col.transform.parent.gameObject.GetComponent<Player>();
			if (PlayerIsValid(triggeringPlayer))
			{
				RemoveShopper(triggeringPlayer);
			}
		}
	}

	private bool PlayerIsValid(Player givenPlayer)
	{
		return givenPlayer != null && (allowedShopperID < 0 || givenPlayer.playerID == allowedShopperID);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class ItemStoreItem : StoreItem
{
	public delegate void SpawnEventHandler(ItemStoreItem item);

	private const int CursedPlatCost = 25;

	private const float CombinedItemChance = 0.03f;

	private static GameObject prefab;

	public static SpawnEventHandler spawnEventHandlers;

	private static string lastUsedCursedHubItemID = string.Empty;

	private string itemID = string.Empty;

	public static bool mimiSpawned;

	public static bool audioPlayed;

	private static bool brdtSpawned;

	private static List<string> currentItemIDs = new List<string>();

	public static List<ItemStoreItem> currentItems = new List<ItemStoreItem>();

	public static List<ItemStoreItem> cursedItems = new List<ItemStoreItem>();

	public bool disableMarkerOffset;

	public bool cursedOnly;

	public Light lightAux;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Items/ItemStoreItem.prefab"));

	public string ID => itemID;

	public static void ResetSpawnedItems()
	{
		currentItemIDs.Clear();
		currentItems.Clear();
		cursedItems.Clear();
		mimiSpawned = false;
		audioPlayed = false;
		brdtSpawned = false;
	}

	public override void Start()
	{
		base.Start();
		if (descText != null && canvasBG != null)
		{
			canvasBG.transform.localScale = new Vector3(descText.transform.localScale.x * 1.12f, canvasBG.transform.localScale.y, 1f);
		}
		transform.Find("ItemShadow").GetComponent<SortSpriteLayer>().yValueOffset = transform.GetComponent<SortSpriteLayer>().yValueOffset;
		if (usePlatinumCost)
		{
			if (cursedOnly)
			{
				if (HubEventHandler.cursePurchased)
				{
					if (priceMarker != null)
					{
						priceMarker.SetText("x");
					}
					Object.Destroy(gameObject);
					return;
				}
				if (lastUsedCursedHubItemID != string.Empty)
				{
					itemID = lastUsedCursedHubItemID;
					lastUsedCursedHubItemID = string.Empty;
					LootManager.RemoveIDFromAvailableList(itemID);
				}
				else
				{
					itemID = LootManager.GetAvailableItemID(1f, hubOnly: true);
				}
				PoolManager.GetPoolItem<CursedAura>("CursedAura").Play(gameObject, new Vector3(0f, -0.25f, 0f));
				EnableCursedLight();
				cursedItems.Add(this);
			}
			else
			{
				itemID = LootManager.GetLockedItemID();
				if (currentItemIDs.Contains(itemID))
				{
					itemID = string.Empty;
				}
			}
		}
		else if (cursedOnly)
		{
			if (Level.isBossRushMode && !brdtSpawned && GameController.tierCount == 0 && GameController.stageCount == 1)
			{
				brdtSpawned = true;
				itemID = DoubleTrouble.staticID;
				LootManager.RemoveIDFromAvailableList(itemID);
			}
			else
			{
				itemID = GetCombinedID(findCursed: true);
			}
			if (itemID == string.Empty)
			{
				itemID = LootManager.GetAvailableItemID(1f);
			}
			PoolManager.GetPoolItem<CursedAura>("CursedAura").Play(gameObject, new Vector3(0f, -0.25f, 0f));
			EnableCursedLight();
			cursedItems.Add(this);
		}
		else
		{
			itemID = GetCombinedID();
			if (itemID == string.Empty)
			{
				itemID = LootManager.GetAvailableItemID();
			}
		}
		if (!usePlatinumCost && !cursedOnly && !disableMarkerOffset)
		{
			priceMarker.OffsetSortValue(priceMarkerYOffset);
		}
		if (itemID == string.Empty)
		{
			CurrentOverheadPrompt = null;
			priceMarker.SetText("x");
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
			return;
		}
		itemSpriteRenderer.sprite = IconManager.GetItemIcon(itemID);
		itemText.text = TextManager.GetItemName(itemID);
		if (descText != null)
		{
			descText.text = TextManager.GetItemDescription(itemID);
		}
		overheadPromptHeight = 1f;
		if (usePlatinumCost)
		{
			costStat.Initialize((!cursedOnly) ? Mathf.Max(10, LootManager.GetPlatPrice(itemID)) : 25);
			topText.text = string.Empty;
		}
		else
		{
			costStat.Initialize(LootManager.GetPrice(itemID));
			isOnSale = !cursedOnly && Random.value < saleChance;
			if (isOnSale)
			{
				costStat.AddMod(StoreItem.SaleMod);
				topText.color = saleColor;
				topText.text = TextManager.GetUIText("storeItem-sale");
			}
			else
			{
				topText.text = string.Empty;
			}
		}
		if (cursedOnly && Cost == 0)
		{
			priceMarker.gameObject.SetActive(value: false);
		}
		priceMarker.SetText(Cost.ToString());
		currentItems.Add(this);
		currentItemIDs.Add(itemID);
		AnnounceSpawnEvent();
	}

	public void PlayDenyBuyEffects()
	{
		SoundManager.PlayAudio("MenuError");
		if (parentNpc != null)
		{
			parentNpc.PlayEmote(EmoteType.No);
		}
	}

	private void CurseBuyEvent(bool inRun = true)
	{
		SoundManager.PlayAudio("CursedMerchant0");
		if (inRun)
		{
			RunData.miscCursedStoreFound = true;
		}
		else
		{
			HubEventHandler.cursePurchased = true;
			lastUsedCursedHubItemID = itemID;
		}
		foreach (ItemStoreItem cursedItem in cursedItems)
		{
			if (cursedItem != null && cursedItem.transform != null && cursedItem != this && cursedItem.gameObject != null)
			{
				if (cursedItem.priceMarker != null)
				{
					cursedItem.priceMarker.SetText("x");
				}
				Object.Destroy(cursedItem.gameObject);
			}
		}
	}

	private bool BuyWithPlat()
	{
		if (Player.platWallet.balance < Cost)
		{
			SoundManager.PlayAudio("MenuError");
			if (parentNpc != null)
			{
				parentNpc.PlayEmote(EmoteType.No);
			}
			return false;
		}
		Player.platWallet.Withdraw(Cost);
		SoundManager.PlayAudio("MenuBuy");
		CurrentOverheadPrompt = null;
		priceMarker.SetText("x");
		return true;
	}

	public override bool Buy(Player player)
	{
		if (usePlatinumCost && cursedOnly)
		{
			if (player.inventory.ContainsItem(itemID) || player.inventory.IsFull)
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (!BuyWithPlat())
			{
				return false;
			}
			if (!player.inventory.AddItem(Item.CreateItem(itemID), showNotice: true))
			{
				PlayDenyBuyEffects();
				return false;
			}
			CurseBuyEvent(inRun: false);
		}
		else if (usePlatinumCost)
		{
			if (!BuyWithPlat())
			{
				return false;
			}
			Item.IsUnlocked(itemID, setUnlocked: true);
			GameController.unlockNotifier.Notify(itemID, UnlockNotifier.NoticeType.Relic);
			Player.newItems[LootManager.completeItemDict[itemID].category].Add(itemID);
			if (!mimiSpawned)
			{
				mimiSpawned = true;
				SpawnMimi();
			}
		}
		else
		{
			if (player.inventory.CursedCount >= 12)
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (player.inventory.ContainsItem(itemID) || !base.Buy(player) || !player.inventory.AddItem(Item.CreateItem(itemID), showNotice: true))
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (cursedOnly)
			{
				CurseBuyEvent();
			}
			else
			{
				RunData.reqItemStoreFound = true;
			}
		}
		if (!cursedOnly && !audioPlayed)
		{
			audioPlayed = true;
			SoundManager.PlayAudio((!Globals.RandBool) ? "Artisan1" : "Artisan0");
		}
		if ((usePlatinumCost && !cursedOnly) || itemID == StoreRestock.staticID)
		{
			ItemStoreItem itemStoreItem = Globals.ChaosInst<ItemStoreItem>(Prefab, transform.parent, transform.position);
			itemStoreItem.usePlatinumCost = usePlatinumCost;
			itemStoreItem.cursedOnly = cursedOnly;
			itemStoreItem.priceMarkerYOffset = priceMarkerYOffset;
			if (transform.GetComponent<SortSpriteLayer>() != null)
			{
				itemStoreItem.GetComponent<SortSpriteLayer>().yValueOffset = transform.GetComponent<SortSpriteLayer>().yValueOffset;
			}
			itemStoreItem.parentNpc = parentNpc;
			if (priceMarker != null && priceMarker.gameObject != null)
			{
				Object.Destroy(priceMarker.gameObject);
			}
		}
		if (parentNpc != null)
		{
			parentNpc.PlayDefaultEmote();
		}
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
		return true;
	}

	public void EnableCursedLight()
	{
		if (!(lightAux == null))
		{
			lightAux.enabled = true;
			lightAux.color = new Color32(92, 0, 0, byte.MaxValue);
			lightAux.intensity = 4f;
			lightAux.range = 3f;
			lightAux.transform.position = new Vector3(lightAux.transform.position.x, lightAux.transform.position.y, -0.5f);
		}
	}

	public void AnnounceSpawnEvent()
	{
		if (spawnEventHandlers != null)
		{
			spawnEventHandlers(this);
		}
	}

	public string GetCombinedID(bool findCursed = false)
	{
		if (Random.value > 0.03f)
		{
			return string.Empty;
		}
		string empty = string.Empty;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player == null || player.inventory == null)
			{
				continue;
			}
			foreach (Item value in player.inventory.itemDict.Values)
			{
				if (value != null && value.parentCombineID != string.Empty)
				{
					empty = ItemRecipe.GetMissingRecipeItem(value.ID, findCursed);
					if (!currentItemIDs.Contains(empty) && findCursed == Item.IsCursedItem(empty))
					{
						LootManager.RemoveIDFromAvailableList(empty);
						return empty;
					}
					empty = string.Empty;
				}
			}
		}
		return string.Empty;
	}

	public static void SpawnMimi()
	{
		Vector2 vector = new Vector2(-14f, 8f);
		PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(vector, string.Empty);
		Globals.ChaosInst<MimicNpc>(MimicNpc.Prefab, null, vector);
		Attack attack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, vector);
		attack.SetAttackInfo("Player", Player.ShootFireball.staticID);
		attack.transform.localScale = Vector3.one * 4f;
		Object.Destroy(attack.gameObject, 0.25f);
	}
}

