	public static void ResetSpawnedSkills()
	{
		currentSkillIDs.Clear();
		currentSkills.Clear();
		tomiSpawned = false;
		audioPlayed = false;
		shufflerHasChaos = false;
	}

	public override void Start()
	{
		base.Start();
		if (descText != null && canvasBG != null)
		{
			canvasBG.transform.localScale = new Vector3(descText.transform.localScale.x * 1.12f, canvasBG.transform.localScale.y, 1f);
		}
	}

	public override void Update()
	{
		base.Update();
		if (initialized)
		{
			return;
		}
		if (!inRange)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (rollRadius >= Vector2.Distance(transform.position, player.transform.position))
				{
					inRange = true;
					break;
				}
			}
			return;
		}
		if (skillID != string.Empty)
		{
			Initialize();
			return;
		}
		if (usePlatinumCost && SetSkillIDFromList(locked: true))
		{
			lockedSkillSelected = true;
		}
		if (!lockedSkillSelected && SetSkillIDFromList())
		{
			isOnSale = Random.value < saleChance;
		}
		if (skillID != string.Empty)
		{
			Initialize();
			return;
		}
		priceMarker.SetText("x");
		Object.Destroy(gameObject);
	}

	private bool SetSkillIDFromList(bool locked = false)
	{
		if (isShufflerItem)
		{
			ignoreEmpoweredReqs = shufflerHasChaos;
		}
		if (isEmpowered && !ignoreEmpoweredReqs)
		{
			empIDList.Clear();
			if ((Inventory.EitherPlayerHasItem(PlayerWinItem.staticID) && Random.value < winItemChance) || (GameController.loopCount >= chaosLoopReq && Random.value < chaosChance))
			{
				empIDList = new List<string>(LootManager.chaosSkillList);
				for (int num = empIDList.Count - 1; num >= 0; num--)
				{
					if (!GameDataManager.gameData.CheckSkillDataEntry(empIDList[num]) || currentSkillIDs.Contains(empIDList[num]))
					{
						empIDList.RemoveAt(num);
					}
				}
				Player[] activePlayers = GameController.activePlayers;
				foreach (Player player in activePlayers)
				{
					if (player == null || player.assignedSkills == null)
					{
						continue;
					}
					Player.SkillState[] assignedSkills = player.assignedSkills;
					foreach (Player.SkillState skillState in assignedSkills)
					{
						if (skillState != null)
						{
							empIDList.Remove(skillState.skillID);
						}
					}
					if (player.stockSkill != null)
					{
						empIDList.Remove(player.stockSkill.skillID);
					}
				}
				if (empIDList.Count > 0)
				{
					isChaosSpell = true;
					skillID = empIDList[Random.Range(0, empIDList.Count)];
					if (isShufflerItem)
					{
						shufflerHasChaos = true;
					}
				}
			}
			if (!isChaosSpell && !isShufflerItem && Random.value < ownedEmpowerChance)
			{
				Player[] activePlayers2 = GameController.activePlayers;
				foreach (Player player2 in activePlayers2)
				{
					if (player2 == null || player2.assignedSkills == null)
					{
						continue;
					}
					Player.SkillState[] assignedSkills2 = player2.assignedSkills;
					foreach (Player.SkillState skillState2 in assignedSkills2)
					{
						if (skillState2 != null && !skillState2.IsEmpowered && !currentSkillIDs.Contains(skillState2.skillID))
						{
							empIDList.Add(skillState2.skillID);
						}
					}
					if (player2.stockSkill != null && !player2.stockSkill.IsEmpowered && !currentSkillIDs.Contains(player2.stockSkill.skillID))
					{
						empIDList.Add(player2.stockSkill.skillID);
					}
				}
				if (empIDList.Count > 0)
				{
					isOwnedEmpowered = true;
					skillID = empIDList[Random.Range(0, empIDList.Count)];
				}
			}
		}
		if (skillID == string.Empty)
		{
			skillID = LootManager.GetSkillID(locked, signatureOnly);
		}
		if (signatureOnly && skillID == string.Empty)
		{
			signatureOnly = false;
			skillID = LootManager.GetSkillID(locked: true);
		}
		if (skillID != string.Empty)
		{
			currentSkillIDs.Add(skillID);
			return true;
		}
		return false;
	}

	public override bool Buy(Player player)
	{
		if (usePlatinumCost)
		{
			if (Player.platWallet.balance < Cost)
			{
				SoundManager.PlayAudio("MenuError");
				if (parentNpc != null)
				{
					parentNpc.PlayEmote(EmoteType.No);
				}
				return false;
			}
			Player.platWallet.Withdraw(Cost);
			SoundManager.PlayAudio("MenuBuy");
			CurrentOverheadPrompt = null;
			priceMarker.SetText("x");
			player.HandleSkillUnlock(skillID, signatureOnly);
			if (!tomiSpawned)
			{
				tomiSpawned = true;
				SpawnTomi();
			}
			SkillStoreItem skillStoreItem = Globals.ChaosInst<SkillStoreItem>(Prefab, transform.parent, transform.position);
			skillStoreItem.usePlatinumCost = true;
			skillStoreItem.signatureOnly = signatureOnly;
			skillStoreItem.parentNpc = parentNpc;
			Object.Destroy(priceMarker.gameObject);
		}
		else
		{
			if (!base.Buy(player))
			{
				return false;
			}
			string givenID = skillID;
			bool flag = isEmpowered;
			player.PickUpSkill(givenID, isSignature: false, flag);
			RunData.reqSkillStoreFound = true;
		}
		if (!audioPlayed && !disablePriceMarker)
		{
			audioPlayed = true;
			SoundManager.PlayAudio("Virtuoso0");
		}
		if (parentNpc != null)
		{
			parentNpc.PlayDefaultEmote();
		}
		Object.Destroy(gameObject);
		return true;
	}

	public void Initialize()
	{
		if (skillID == string.Empty)
		{
			return;
		}
		itemSpriteRenderer.sprite = IconManager.GetSkillIcon(skillID);
		itemText.text = TextManager.GetSkillName(skillID);
		descText.text = TextManager.GetSkillDescription(skillID, empowered: false, isChaos: true);
		overheadPromptHeight = 2.5f;
		if (isEmpowered)
		{
			if (isChaosSpell)
			{
				costStat.Initialize(LootManager.GetPrice(skillID));
			}
			else if (isOwnedEmpowered)
			{
				costStat.Initialize(empoweredBaseCost);
			}
			else
			{
				costStat.Initialize(LootManager.GetPrice(skillID) + empoweredCostIncrease);
			}
			topText.text = string.Empty;
			topText.color = newSkillColor;
		}
		else if (isOnSale)
		{
			costStat.Initialize(LootManager.GetPrice(skillID));
			costStat.AddMod(StoreItem.SaleMod);
			topText.text = TextManager.GetUIText("storeItem-sale");
			topText.color = saleColor;
		}
		else
		{
			costStat.Initialize(LootManager.GetPrice(skillID));
			topText.text = string.Empty;
		}
		if (usePlatinumCost)
		{
			costStat.Initialize((!signatureOnly) ? Mathf.Max(10, LootManager.GetPlatPrice(skillID, isItem: false)) : signatureCost);
			if (!lockedSkillSelected)
			{
				CurrentOverheadPrompt = null;
				priceMarker.SetText("x");
				Object.Destroy(gameObject);
				return;
			}
		}
		SetCardSprite();
		priceMarker.SetText(Cost.ToString());
		initialized = true;
		currentSkills.Add(this);
		AnnounceSpawnEvent();
	}

	private void SetCardSprite()
	{
		if (signatureOnly)
		{
			sigSR.enabled = true;
		}
		else if (isEmpowered)
		{
			empoweredSR.enabled = true;
		}
		else
		{
			standardSR.enabled = true;
		}
	}

	public void AnnounceSpawnEvent()
	{
		if (spawnEventHandlers != null)
		{
			spawnEventHandlers(this);
		}
	}

	public static void SpawnTomi()
	{
		Vector2 vector = new Vector2(14f, 8f);
