	}

	public void Update()
	{
		if (shoppers.Count == 0)
		{
			return;
		}
		foreach (Player shopper in shoppers)
		{
			if (!(shopper.fsm.currentStateName == "Paused") && shopper.inputDevice.GetButton("Interact") && (shopper.fsm.currentStateName.Contains("Idle") || shopper.fsm.currentStateName.Contains("Run")))
			{
				shopper.fsm.ChangeState("Paused");
				storeUI.Load(shopper);
			}
		}
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyHurtBox" && col.gameObject.tag == "Player")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (!shoppers.Contains(component))
			{
				shoppers.Add(component);
			}
			component.overheadPrompt.DisplayPrompt("Interact");
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyHurtBox" && col.gameObject.tag == "Player")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			shoppers.Remove(component);
			component.overheadPrompt.HidePrompt(string.Empty);
		}
	}
}
