using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class ChallengeMerchant : MonoBehaviour
{
	public enum ChallengeStatus
	{
		NotStarted,
		InProgress,
		Completed,
		Failed
	}

	public enum ChallengeType
	{
		StraightSurvival,
		NoDamage,
		SkillRemoval
	}

	public ChallengeType challengeType;

	private Text challengeTypeText;

	public ChallengeStatus status;

	public string rewardLootTableName = "TreasureChestChallenge";

	private GameObject spriteObject;

	private GameObject questionBox;

	private GameObject minimapBox;

	private Image acceptIconImage;

	private Image refuseIconImage;

	private CircleCollider2D[] circColliders;

	private ChaosInputDevice currentInput;

	private Player playerScript;

	private GameObject challengeRoom;

	private SurvivalRoom[] survivalRooms;

	private bool skillsRemoved;

	private Dictionary<int, Player.SkillState> removedSkills = new Dictionary<int, Player.SkillState>();

	private bool[] playerDead;

	private bool playerConfirm;

	private bool playerExit;

	private void Awake()
	{
		spriteObject = transform.Find("Sprite").gameObject;
		questionBox = transform.Find("Canvas/QuestionBox").gameObject;
		acceptIconImage = questionBox.transform.Find("Accept/AcceptButton").GetComponent<Image>();
		refuseIconImage = questionBox.transform.Find("Refuse/RefuseButton").GetComponent<Image>();
		challengeTypeText = questionBox.transform.Find("ChallengeTypeText").GetComponent<Text>();
		circColliders = GetComponentsInChildren<CircleCollider2D>();
		currentInput = null;
		status = ChallengeStatus.NotStarted;
	}

	private void Start()
	{
		survivalRooms = GetComponentsInChildren<SurvivalRoom>();
		challengeRoom = transform.Find("ChallengeRoom").gameObject;
		challengeRoom.SetActive(value: false);
		minimapBox = transform.Find("MinimapBox").gameObject;
	}

	private void SetUIButtonsToMatchInputDev()
	{
		if (playerScript.IsKeyboardInput)
		{
			acceptIconImage.sprite = GameUI.KeyboardKeyIcons["Space"];
			refuseIconImage.sprite = GameUI.KeyboardKeyIcons["Escape"];
		}
		else
		{
			acceptIconImage.sprite = GameUI.UIButtonIcons["GamepadButtonGreen"];
			refuseIconImage.sprite = GameUI.UIButtonIcons["GamepadButtonRed"];
		}
	}

	private void Update()
	{
		if (currentInput == null)
		{
			return;
		}
		status = CheckChallengeStatus();
		switch (status)
		{
		case ChallengeStatus.NotStarted:
			if (currentInput.GetButtonDown("Interact") && !playerScript.fsm.currentStateName.Contains("Dead"))
			{
				playerScript.overheadPrompt.HidePrompt(string.Empty);
				string text = "Take the challenge?\nDefeat ";
				string text2 = "all enemies ";
				switch (challengeType)
				{
				case ChallengeType.NoDamage:
					text = text + text2 + "without taking damage!";
					break;
				case ChallengeType.SkillRemoval:
					text = text + text2 + "without using spells!";
					break;
				case ChallengeType.StraightSurvival:
					text = text + text2 + "!";
					break;
				}
				challengeTypeText.text = text;
				questionBox.SetActive(value: true);
				SetUIButtonsToMatchInputDev();
				playerScript.fsm.ChangeState("Paused");
				return;
			}
			if (!questionBox.activeSelf)
			{
				playerConfirm = false;
				playerExit = false;
			}
			break;
		case ChallengeStatus.Completed:
			HandleChallengeComplete();
			break;
		case ChallengeStatus.Failed:
			SoundManager.PlayAudio("MenuError");
			if (challengeType == ChallengeType.SkillRemoval)
			{
				EditPlayerSkills(remove: false);
			}
			Object.Destroy(gameObject);
			break;
		}
		if (status == ChallengeStatus.InProgress)
		{
			GameUI.BroadcastNoticeMessage("Enemies: " + GetEnemyCount(), 1f);
		}
		if (!questionBox.activeSelf)
		{
			return;
		}
		if (currentInput.GetButtonUp("Confirm") || playerConfirm)
		{
			ToggleNPC(on: false);
			challengeRoom.SetActive(value: true);
			if (challengeType == ChallengeType.SkillRemoval)
			{
				EditPlayerSkills();
			}
			if (challengeType == ChallengeType.NoDamage)
			{
				playerDead = new bool[GameController.activePlayers.Length];
				for (int i = 0; i < GameController.activePlayers.Length; i++)
				{
					if (GameController.activePlayers[i] != null)
					{
						playerDead[i] = GameController.activePlayers[i].fsm.currentStateName.Contains("Dead");
					}
					else
					{
						playerDead[i] = false;
					}
				}
			}
			playerScript.fsm.ChangeState(playerScript.fsm.defaultStateName);
			questionBox.SetActive(value: false);
			minimapBox.SetActive(value: false);
		}
		if (currentInput.GetButtonUp("Cancel") || playerExit)
		{
			playerScript.fsm.ChangeState(playerScript.fsm.defaultStateName);
			questionBox.SetActive(value: false);
		}
	}

	private int GetEnemyCount()
	{
		int num = 0;
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			EnemyFactory[] enemyFactories = survivalRoom.enemyFactories;
			foreach (EnemyFactory enemyFactory in enemyFactories)
			{
				num += (enemyFactory.maxSpawnCycles - enemyFactory.currentSpawnCycle) * enemyFactory.enemiesPerCycle;
			}
			Enemy[] componentsInChildren = survivalRoom.transform.parent.Find("EnemyLocations").GetComponentsInChildren<Enemy>();
			foreach (Enemy enemy in componentsInChildren)
			{
				if (!enemy.fsm.currentStateName.Contains("Dead"))
				{
					num++;
				}
			}
		}
		return num;
	}

	private void EditPlayerSkills(bool remove = true)
	{
		if (remove)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.fsm.currentStateName.Contains("Dead"))
				{
					continue;
				}
				for (int j = 0; j < 6; j++)
				{
					int key = j + player.playerID * 6;
					if (player.assignedSkills[j] != null && player.assignedSkills[j].name != "Slash" && player.assignedSkills[j].name != "Dash")
					{
						removedSkills.Add(key, player.assignedSkills[j]);
						player.AssignSkillSlot(j + 1, string.Empty);
					}
				}
				player.lowerHUD.cooldownUI.RefreshEntries();
			}
			return;
		}
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			for (int l = 0; l < 6; l++)
			{
				int key = l + player2.playerID * 6;
				if (removedSkills.ContainsKey(key))
				{
					player2.AssignSkillSlot(l + 1, removedSkills[key].skillID);
				}
			}
			player2.lowerHUD.cooldownUI.RefreshEntries();
		}
	}

	private void HandleChallengeComplete()
	{
		if (challengeType == ChallengeType.SkillRemoval)
		{
			EditPlayerSkills(remove: false);
		}
		ToggleNPC(on: true, includeOverheadImage: false);
		TreasureChest component = Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/Environment/Destructibles/TreasureChest.prefab"), transform.position + Vector3.down * 2f, Quaternion.identity).GetComponent<TreasureChest>();
		if (rewardLootTableName != string.Empty)
		{
			component.lootTableName = rewardLootTableName;
		}
		enabled = false;
	}

	private void ToggleNPC(bool on, bool includeOverheadImage = true)
	{
		spriteObject.SetActive(on);
		CircleCollider2D[] array = circColliders;
		foreach (CircleCollider2D circleCollider2D in array)
		{
			circleCollider2D.enabled = on;
		}
		if (includeOverheadImage)
		{
			playerScript.overheadPrompt.DisplayPrompt("Interact");
		}
		if (!on)
		{
			playerScript.overheadPrompt.HidePrompt(string.Empty);
		}
	}

	private ChallengeStatus CheckChallengeStatus()
	{
		bool flag = false;
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			if (!survivalRoom.triggered)
			{
				continue;
			}
			flag = true;
			if (challengeType == ChallengeType.NoDamage)
			{
				for (int j = 0; j < GameController.activePlayers.Length; j++)
				{
					Player player = GameController.activePlayers[j];
					if (player != null && (player.fsm.currentStateName.Contains("Hurt") || (player.fsm.currentStateName.Contains("Dead") && !playerDead[j])))
					{
						return ChallengeStatus.Failed;
					}
				}
			}
			if (!survivalRoom.CheckPlayers())
			{
				return ChallengeStatus.Failed;
			}
			if (!survivalRoom.roomCleared)
			{
				return ChallengeStatus.InProgress;
			}
		}
		if (!flag)
		{
			return ChallengeStatus.NotStarted;
		}
		return ChallengeStatus.Completed;
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 8f).Count > 0)
		{
			if (playerScript != null)
			{
				playerScript.fsm.ChangeState(playerScript.fsm.defaultStateName);
			}
			questionBox.SetActive(value: false);
			OnTriggerExit2D(col);
		}
		else if (col.gameObject.name == "AllyHurtBox" && enabled && col.transform.parent.gameObject.GetComponent<Player>() != null && currentInput == null)
		{
			playerScript = GameController.playerScripts[col.transform.parent.gameObject.GetComponent<Player>().playerID];
			currentInput = playerScript.inputDevice;
			playerScript.overheadPrompt.DisplayPrompt("Interact");
		}
	}

	private void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyHurtBox" && col.transform.parent.gameObject.GetComponent<Player>() != null && playerScript == GameController.playerScripts[col.transform.parent.gameObject.GetComponent<Player>().playerID])
		{
			playerScript.overheadPrompt.HidePrompt(string.Empty);
			playerScript = null;
			currentInput = null;
		}
	}

	public void PlayerPressedConfirm()
	{
		playerConfirm = true;
	}

	public void PlayerPressedExit()
	{
		playerExit = true;
	}
}
using System.Collections.Generic;
using Chaos.ListExtensions;
using UnityEngine;

public class RelicWell : MonoBehaviour
{
	public struct RelicInRange
	{
		public ItemDrop item;

		public Vector2 startPos;
	}

	public delegate void CollectRelicEventHandler(int givenCost);

	private static GameObject prefab;

	private Dictionary<RelicInRange, ChaosQuickStopwatch> relicTimers;

	private Dictionary<RelicInRange, float> relicRangeDuration;

	private List<RelicInRange> itemsInRange;

	private List<RelicInRange> itemsToRemove;

	private const float attractDelay = 1f;

	private const float attractTime = 1f;

	private Vector2 lootDropLocation;

	private float costModifier = 0.4f;

	private int goldValue;

	public CollectRelicEventHandler collectRelicEventHandler;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/RelicWell.prefab"));

	private void Start()
	{
		lootDropLocation = transform.position;
		itemsInRange = new List<RelicInRange>(20);
		itemsToRemove = new List<RelicInRange>(20);
		relicTimers = new Dictionary<RelicInRange, ChaosQuickStopwatch>(20);
		relicRangeDuration = new Dictionary<RelicInRange, float>(20);
	}

	public void Update()
	{
		if (itemsInRange.Count == 0)
		{
			return;
		}
		itemsInRange.RemoveNullValues();
		for (int i = 0; i < itemsInRange.Count; i++)
		{
			RelicInRange relicInRange = itemsInRange[i];
			if (relicRangeDuration[relicInRange] < 1f)
			{
				relicRangeDuration[relicInRange] += Time.deltaTime;
				continue;
			}
			if (!relicTimers[relicInRange].IsRunning)
			{
				relicTimers[relicInRange].IsRunning = true;
				continue;
			}
			if (Vector2.Distance(relicInRange.item.transform.position, transform.position) <= 1f)
			{
				CollectRelic(relicInRange.item);
				itemsToRemove.Add(relicInRange);
			}
			else
			{
				itemsInRange[i].item.rigidbody2D.MovePosition(Vector2.Lerp(itemsInRange[i].startPos, transform.position, Globals.GetSmoothLerpValue(relicTimers[relicInRange].TimePercentage)));
			}
			relicRangeDuration[relicInRange] += Time.deltaTime;
		}
		if (itemsToRemove.Count > 0)
		{
			for (int j = 0; j < itemsToRemove.Count; j++)
			{
				itemsInRange.Remove(itemsToRemove[j]);
				relicRangeDuration.Remove(itemsToRemove[j]);
				relicTimers.Remove(itemsToRemove[j]);
			}
			itemsToRemove.Clear();
		}
	}

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (!(col.name != "ItemHitBox") && !(col.transform.parent == null))
		{
			ItemDrop component = col.transform.parent.GetComponent<ItemDrop>();
			if (!(component == null))
			{
				RelicInRange relicInRange = new RelicInRange
				{
					item = component,
					startPos = component.transform.position
				};
				itemsInRange.Add(relicInRange);
				relicRangeDuration[relicInRange] = 0f;
				relicTimers[relicInRange] = new ChaosQuickStopwatch();
			}
		}
	}

	private void CollectRelic(ItemDrop givenID)
	{
		if (!(givenID == null) && !(givenID.itemID == string.Empty))
		{
			goldValue = Mathf.CeilToInt((float)LootManager.GetPrice(givenID.itemID) * costModifier);
			if (givenID.itemID == "TokenCollector")
			{
				goldValue *= 3;
			}
			else if (Inventory.EitherPlayerHasItem("TokenCollector"))
			{
				goldValue *= 2;
			}
			LootManager.DropGold(lootDropLocation, goldValue);
			SoundManager.PlayAudio("MenuBuy");
			givenID.Disable();
			if (collectRelicEventHandler != null)
			{
				collectRelicEventHandler(goldValue);
			}
		}
	}
}
