using System.Collections.Generic;
using UnityEngine;

public class OutfitModStat
{
	public enum OutfitModType
	{
		None,
		Health,
		Speed,
		Run,
		Evade,
		Armor,
		CritChance,
		CritDamage,
		Damage,
		Cooldown,
		Pride,
		Fall,
		ODRate,
		ODDamage,
		HealAmount,
		HealCrit,
		Gold,
		Platinum,
		AllowUpgrade
	}

	public OutfitModType modType;

	protected string modIDPrefix = "OutfitModifier";

	protected string modifierID = string.Empty;

	protected string statDescription = string.Empty;

	protected string statDataFieldKey = string.Empty;

	protected bool updateValue;

	protected bool isIncrease;

	public bool hasAddValue;

	public NumVarStatMod addModifier;

	public bool hasMultiValue;

	public NumVarStatMod multiModifier;

	public bool hasOverrideValue;

	public NumVarStatMod overrideModifier;

	private BoolVarStatMod boolModifier;

	protected List<NumVarStat> targetNumVarStatList;

	protected List<BoolVarStat> targetBoolVarStatList;

	public OutfitModStat(OutfitModType givenType = OutfitModType.None, float addValue = 0f, float multiValue = 0f, float overrideValue = 0f, bool boolValue = false)
	{
		Initialize(givenType, addValue, multiValue, overrideValue, boolValue);
	}

	public OutfitModStat(OutfitModStat givenOM)
	{
		Initialize(givenOM.modType, givenOM.addModifier.modValue, givenOM.multiModifier.modValue, givenOM.overrideModifier.modValue, givenOM.boolModifier.modValue);
	}

	private void Initialize(OutfitModType givenType, float givenAdd, float givenMulti, float givenOver, bool givenBool)
	{
		modType = givenType;
		SetInitialVars();
		isIncrease = givenAdd + givenMulti > 0f;
		hasAddValue = givenAdd != 0f;
		hasMultiValue = givenMulti != 0f;
		hasOverrideValue = givenOver != 0f;
		addModifier = new NumVarStatMod(modIDPrefix + "Add" + modifierID, givenAdd);
		multiModifier = new NumVarStatMod(modIDPrefix + "Multi" + modifierID, givenMulti, 10, VarStatModType.Multiplicative);
		overrideModifier = new NumVarStatMod(modIDPrefix + "Override" + modifierID, givenOver, 1, VarStatModType.Override);
		targetNumVarStatList = new List<NumVarStat>();
		boolModifier = new BoolVarStatMod(modIDPrefix + "Bool" + modifierID, givenBool);
		targetBoolVarStatList = new List<BoolVarStat>();
	}

	private void SetInitialVars()
	{
		switch (modType)
		{
		case OutfitModType.Health:
			modifierID = "Health";
			statDescription = "wardrobeUI-statHealth";
			updateValue = true;
			break;
		case OutfitModType.Speed:
			modifierID = "MoveSpeed";
			statDescription = "wardrobeUI-statSpeed";
			break;
		case OutfitModType.Run:
			modifierID = "RunTime";
			statDescription = "wardrobeUI-statRun";
			break;
		case OutfitModType.Evade:
			modifierID = "Evade";
			statDescription = "wardrobeUI-statEvade";
			break;
		case OutfitModType.Armor:
			modifierID = "Armor";
			statDescription = "wardrobeUI-statArmor";
			break;
		case OutfitModType.CritChance:
			modifierID = "CritChance";
			statDescription = "wardrobeUI-statCritChance";
			statDataFieldKey = StatData.critChStr;
			break;
		case OutfitModType.CritDamage:
			modifierID = "CritDamage";
			statDescription = "wardrobeUI-statCritDamage";
			statDataFieldKey = StatData.critDmgStr;
			break;
		case OutfitModType.Damage:
			modifierID = "Damage";
			statDescription = "wardrobeUI-statDamage";
			statDataFieldKey = StatData.damageStr;
			break;
		case OutfitModType.Cooldown:
			modifierID = "Cooldown";
			statDescription = "wardrobeUI-statCooldown";
			statDataFieldKey = StatData.cdStr;
			break;
		case OutfitModType.ODRate:
			modifierID = "ODRate";
			statDescription = "wardrobeUI-statODRate";
			statDataFieldKey = StatData.odProgStr;
			break;
		case OutfitModType.ODDamage:
			modifierID = "ODDamage";
			statDescription = "wardrobeUI-statODDamage";
			statDataFieldKey = StatData.odDmgStr;
			break;
		case OutfitModType.HealAmount:
			modifierID = "HealAmount";
			statDescription = "wardrobeUI-statHealAmount";
			break;
		case OutfitModType.HealCrit:
			modifierID = "HealCrit";
			statDescription = "wardrobeUI-statHealCrit";
			break;
		case OutfitModType.Gold:
			modifierID = "Gold";
			statDescription = "wardrobeUI-gold";
			break;
		case OutfitModType.Platinum:
			modifierID = "Platinum";
			statDescription = "wardrobeUI-platinum";
			break;
		default:
			modifierID = string.Empty;
			statDescription = string.Empty;
			statDataFieldKey = string.Empty;
			updateValue = false;
			break;
		}
	}

	private void SetTargetVarStatList(Player p)
	{
		if (targetNumVarStatList != null)
		{
			targetNumVarStatList.Clear();
		}
		if (targetBoolVarStatList != null)
		{
			targetBoolVarStatList.Clear();
		}
		switch (modType)
		{
		case OutfitModType.Health:
			targetNumVarStatList.Add(p.health.healthStat);
			return;
		case OutfitModType.Speed:
			targetNumVarStatList.Add(p.movement.moveSpeedStat);
			return;
		case OutfitModType.Run:
			targetNumVarStatList.Add(p.runSpeedupStat);
			return;
		case OutfitModType.Evade:
			targetNumVarStatList.Add(p.health.evadeStat);
			return;
		case OutfitModType.Armor:
			targetNumVarStatList.Add(p.health.armorStat);
			return;
		case OutfitModType.Pride:
			targetNumVarStatList.Add(p.health.shieldStat);
			return;
		case OutfitModType.Fall:
			targetBoolVarStatList.Add(p.healthRegenStat);
			return;
		case OutfitModType.AllowUpgrade:
			targetBoolVarStatList.Add(p.outfitEnhanceAllowStat);
			return;
		case OutfitModType.HealAmount:
			targetNumVarStatList.Add(p.health.healModifierStat);
			return;
		case OutfitModType.HealCrit:
			targetNumVarStatList.Add(p.health.critHealModStat);
			return;
		case OutfitModType.Gold:
			targetNumVarStatList.Add(LootManager.globalGoldModifier);
			return;
		case OutfitModType.Platinum:
			targetNumVarStatList.Add(LootManager.globalPlatModifier);
			return;
		}
		if (!(statDataFieldKey != string.Empty))
		{
			return;
		}
		List<StatData> allStatData = StatManager.GetAllStatData("Skills", p.skillCategory);
		int count = allStatData.Count;
		for (int i = 0; i < count; i++)
		{
			if (!allStatData[i].GetValue<bool>("isStatusEffect"))
			{
				allStatData[i].EnsureVarStatEntry(statDataFieldKey);
				targetNumVarStatList.Add(allStatData[i].numVarStatDict[statDataFieldKey]);
			}
		}
	}

	public virtual void SetModStatus(Player givenPlayer, bool givenStatus, bool allowUpdate = true)
	{
		if (givenPlayer == null)
		{
			return;
		}
		isIncrease = addModifier.modValue + multiModifier.modValue > 0f;
		SetTargetVarStatList(givenPlayer);
		if (targetNumVarStatList != null && targetNumVarStatList.Count > 0)
		{
			int count = targetNumVarStatList.Count;
			if (givenStatus)
			{
				for (int i = 0; i < count; i++)
				{
					NumVarStat numVarStat = targetNumVarStatList[i];
					if (hasAddValue)
					{
						numVarStat.AddMod(addModifier);
					}
					if (hasMultiValue)
					{
						numVarStat.AddMod(multiModifier);
					}
					if (hasOverrideValue)
					{
						numVarStat.AddMod(overrideModifier);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
			else
			{
				for (int j = 0; j < count; j++)
				{
					NumVarStat numVarStat = targetNumVarStatList[j];
					if (hasAddValue)
					{
						numVarStat.RemoveMod(addModifier.ID);
					}
					if (hasMultiValue)
					{
						numVarStat.RemoveMod(multiModifier.ID);
					}
					if (hasOverrideValue)
					{
						numVarStat.RemoveMod(overrideModifier.ID);
					}
					if (updateValue && allowUpdate)
					{
						numVarStat.CurrentValue = numVarStat.ModifiedValue;
					}
				}
			}
		}
		if (targetBoolVarStatList != null && targetBoolVarStatList.Count > 0)
		{
			int count = targetBoolVarStatList.Count;
			for (int k = 0; k < count; k++)
			{
				targetBoolVarStatList[k].Modify(boolModifier, givenStatus);
			}
		}
	}

	public virtual string GetDescription(bool addExtra = false)
	{
		return modType switch
		{
			OutfitModType.Platinum => TextManager.GetUIText("wardrobeUI-platinum") + (addExtra ? (" <color=#009999>( </color><color=#00dddd> + " + Mathf.FloorToInt(addModifier.modValue) + " </color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Gold => TextManager.GetUIText("wardrobeUI-gold") + (addExtra ? (" <color=#009999>( </color><color=#00dddd>" + Globals.PercentToStr(multiModifier, "+") + "</color><color=#009999> )</color>") : string.Empty), 
			OutfitModType.Pride => TextManager.GetUIText("wardrobeUI-statPride"), 
			OutfitModType.Fall => TextManager.GetUIText("wardrobeUI-statFall"), 
			OutfitModType.None => TextManager.GetUIText("wardrobeUI-statNone"), 
			OutfitModType.AllowUpgrade => string.Empty, 
			_ => ((!isIncrease) ? TextManager.GetUIText("wardrobeUI-decreaseStat") : TextManager.GetUIText("wardrobeUI-increaseStat")) + TextManager.GetUIText(statDescription) + ((!addExtra) ? string.Empty : (" <color=#009999>( </color><color=#00dddd>" + (hasAddValue ? Globals.PercentToStr(addModifier, (!isIncrease) ? "-" : "+") : (hasMultiValue ? Globals.PercentToStr(multiModifier, (!isIncrease) ? "-" : "+") : ((!hasOverrideValue) ? string.Empty : ((int)overrideModifier.modValue/*cast due to constrained. prefix*/).ToString()))) + "</color><color=#009999> )</color>")), 
		};
	}
}
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;

public class Headgear : MonoBehaviour
{
	private static Dictionary<Entity, List<Headgear>> _equippedHeadgearList;

	private Animator anim;

	[HideInInspector]
	public bool disabled = true;

	[HideInInspector]
	public bool hidden = true;

	private string ID = "UndefinedHeadgear";

	private bool initialized;

	private bool destroyOnHide;

	private Entity parentEntity;

	private SpriteRenderer parentSprite;

	public Sprite[] spriteVariations;

	private bool[] spriteVarAvailable;

	private SpriteRenderer spriteRenderer;

	private SortSpriteLayer spriteSorter;

	private string initialSpriteSortingLayer;

	private float initialYOffset;

	private FacingDirection lastFacingDir = FacingDirection.Down;

	private static Vector3 leftScale = new Vector3(-1f, 1f, 1f);

	private HeadPosition parentHeadPos;

	private ThrownItem parentThrownItem;

	private ChaosQuickStopwatch hideTimer;

	private float hideFlashTime = 0.0333f;

	private float hideFadeOutTime = 0.5f;

	private ChaosQuickStopwatch equipTimer;

	private float equipFlashTime = 0.0333f;

	private float equipTime = 0.15f;

	private ChaosQuickStopwatch enableTimer;

	public static Dictionary<Entity, List<Headgear>> EquippedHeadgearList
	{
		get
		{
			if (_equippedHeadgearList == null)
			{
				_equippedHeadgearList = new Dictionary<Entity, List<Headgear>>();
			}
			return _equippedHeadgearList;
		}
	}

	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteRenderer = transform.Find("Sprite").GetComponent<SpriteRenderer>();
	}

	public void Initialize(Entity parentEntity, string ID, Transform newParent = null)
	{
		this.ID = ID;
		this.parentEntity = parentEntity;
		if (newParent != null)
		{
			transform.SetParent(newParent);
		}
		transform.localPosition = Vector3.zero;
		InitHeadGearSprites();
		parentSprite = parentEntity.spriteRenderer;
		parentHeadPos = parentEntity.GetComponentInChildren<HeadPosition>();
		parentThrownItem = parentEntity.transform.GetComponent<ThrownItem>();
		initialized = true;
		Equip();
	}

	private void InitHeadGearSprites()
	{
		spriteRenderer.sprite = spriteVariations[2];
		spriteSorter = spriteRenderer.transform.GetComponent<SortSpriteLayer>();
		spriteVarAvailable = new bool[spriteVariations.Length];
		for (int i = 0; i < spriteVarAvailable.Length; i++)
		{
			spriteVarAvailable[i] = spriteVariations[i] != null;
		}
	}

	public static void UpdateEquippedHeadgearList(Entity parentEntity, Headgear curHeadgear, bool remove = false)
	{
		if (!EquippedHeadgearList.ContainsKey(parentEntity))
		{
			EquippedHeadgearList[parentEntity] = new List<Headgear>();
		}
		List<Headgear> list = EquippedHeadgearList[parentEntity];
		list.RemoveAll((Headgear h) => h == null);
		if (remove)
		{
			if (list.Count == 1)
			{
				list.Remove(curHeadgear);
			}
			else if (list.IndexOf(curHeadgear) == list.Count - 1 && list.Count > 1)
			{
				list.Remove(curHeadgear);
				list[list.Count - 1].Equip(skipUpdate: true);
			}
			else
			{
				list.Remove(curHeadgear);
			}
			return;
		}
		if (list.Contains(curHeadgear))
		{
			list.Remove(curHeadgear);
		}
		if (list.Count > 0)
		{
			list[list.Count - 1].Hide(destroyOnHide: false, disable: true);
		}
		list.Add(curHeadgear);
	}

	private void Show(bool equip = false)
	{
		hidden = false;
		if (equip)
		{
			anim.Play("Equip", -1, 0f);
		}
		else
		{
			anim.Play("Idle", -1, 0f);
		}
	}

	private void OnDisable()
	{
		bool disable = disabled;
		Hide(destroyOnHide: false, disable);
	}

	public void Equip(bool skipUpdate = false)
	{
		disabled = false;
		if (!skipUpdate)
		{
			UpdateEquippedHeadgearList(parentEntity, this);
		}
		Show(equip: true);
	}

	public void Hide(bool destroyOnHide = false, bool disable = false)
	{
		if (!(gameObject == null))
		{
			disabled = disable;
			hidden = true;
			if (destroyOnHide)
			{
				UpdateEquippedHeadgearList(parentEntity, this, remove: true);
			}
			this.destroyOnHide = destroyOnHide;
			anim.Play("Hidden", -1, 0f);
			if (destroyOnHide)
			{
				Object.Destroy(gameObject);
			}
		}
	}

	public bool SetOverrideDirection()
	{
		if (parentHeadPos == null || parentHeadPos.dirOverride == Vector2.zero)
		{
			return false;
		}
		int num = -1;
		if (parentHeadPos.dirOverride == Globals.Vector2UpRight || parentHeadPos.dirOverride == Globals.Vector2UpLeft)
		{
			num = 3;
		}
		else if (parentHeadPos.dirOverride == Globals.Vector2DownRight || parentHeadPos.dirOverride == Globals.Vector2DownLeft)
		{
			num = 4;
		}
		else if (parentHeadPos.dirOverride == Vector2.down)
		{
			num = 2;
		}
		else if (parentHeadPos.dirOverride == Vector2.right || parentHeadPos.dirOverride == Vector2.left)
		{
			num = 1;
		}
		else if (parentHeadPos.dirOverride == Vector2.up)
		{
			num = 0;
		}
		if (num < 0 || !spriteVarAvailable[num])
		{
			return false;
		}
		spriteRenderer.sprite = spriteVariations[num];
		if (parentHeadPos.useOverrideX)
		{
			if (parentHeadPos.dirOverride.x >= 0f)
			{
				spriteRenderer.transform.localScale = Vector3.one;
			}
			else
			{
				spriteRenderer.transform.localScale = leftScale;
			}
		}
		lastFacingDir = FacingDirection.Neutral;
		return true;
	}

	public void SetFacingDirection()
	{
		if (disabled || hidden || !(parentEntity != null))
		{
			return;
		}
		if (parentHeadPos != null && parentHeadPos.flipX)
		{
			if (parentEntity.facingDirection == FacingDirection.Left)
			{
				spriteRenderer.transform.localScale = Vector3.one;
			}
			else
			{
				spriteRenderer.transform.localScale = leftScale;
			}
		}
		else
		{
			spriteRenderer.transform.localScale = Vector3.one;
		}
		if (!SetOverrideDirection() && parentEntity.facingDirection != lastFacingDir)
		{
			switch (parentEntity.facingDirection)
			{
			case FacingDirection.Up:
				spriteRenderer.sprite = spriteVariations[0];
				break;
			case FacingDirection.Right:
				spriteRenderer.sprite = spriteVariations[1];
				break;
			case FacingDirection.Down:
				spriteRenderer.sprite = spriteVariations[2];
				break;
			case FacingDirection.Left:
				spriteRenderer.sprite = spriteVariations[1];
				break;
			case FacingDirection.Neutral:
				spriteRenderer.sprite = spriteVariations[2];
				break;
			}
			lastFacingDir = parentEntity.facingDirection;
		}
	}

	public void MirrorParentSprite()
	{
		if (!disabled && !hidden)
		{
			spriteRenderer.material.SetVector("_FlashColor", parentSprite.material.GetVector("_FlashColor"));
			spriteRenderer.material.SetFloat("_FlashAmount", parentSprite.material.GetFloat("_FlashAmount"));
			spriteRenderer.material.SetColor("_OutlineColor", parentSprite.material.GetColor("_OutlineColor"));
			spriteRenderer.sortingLayerName = parentSprite.sortingLayerName;
			if (parentHeadPos != null)
			{
				spriteSorter.yValueOffset = 0f - parentHeadPos.transform.localPosition.y;
			}
		}
	}

	public void LateUpdate()
	{
		if (!initialized || disabled || (hidden && parentEntity.currentStateName.Contains("Dead")))
		{
			return;
		}
		if (!hidden && parentEntity.currentStateName.Contains("Dead") && parentEntity.anim.AnimPlayed(0.1f))
		{
			Hide();
			return;
		}
		if (!hidden && (!parentSprite.enabled || !parentSprite.gameObject.activeSelf || parentSprite.sprite == null))
		{
			bool disable = disabled;
			Hide(destroyOnHide: false, disable);
			return;
		}
		if (hidden && parentSprite.enabled && parentSprite.gameObject.activeSelf && parentSprite.sprite != null)
		{
			Show();
		}
		SetFacingDirection();
		MirrorParentSprite();
	}
}

using System;
using UnityEngine;

public class TailorNpc : Npc
{
	private static GameObject sparklePrefab;

	private static bool[] playerBuffed = new bool[GameController.maxPlayerCount];

	private static int goldCost = 100;

	private static int healthCost = 100;

	private Outfit currentOutfit;

	private OutfitModStat currentMod;

	private int currentHealth;

	private static float upgradeValue = 1.5f;

	public static GameObject SparklePrefab => sparklePrefab ?? (sparklePrefab = ChaosBundle.Get("Assets/Prefabs/Effects/OutfitSparkle.prefab"));

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 3f;
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.TailorRoom, transform.position, transform);
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Remove(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Combine(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
	}

	public static void PlayerDestroyEvent(Player player)
	{
		playerBuffed[player.playerID] = false;
	}

	public static void PlayerOutfitEquipEvent(Player player, string outfitID)
	{
		playerBuffed[player.playerID] = false;
	}

	public override bool HandleConditionalInteraction()
	{
		switch (CurrentDialogIndex)
		{
		case 0:
			if (playerBuffed[player.playerID])
			{
				CurrentDialogIndex = 4;
			}
			else if (!player.outfitEnhanceAllowStat.CurrentValue)
			{
				CurrentDialogIndex = 6;
			}
			break;
		case 1:
			if (!player.inventory.ContainsItem("TokenTailor"))
			{
				CurrentDialogIndex = 2;
			}
			break;
		case 2:
			if (player.inventory.ContainsItem("TokenTailor"))
			{
				HandleUpgradeOutfit(useToken: true);
				CurrentDialogIndex = 4;
			}
			else
			{
				CurrentDialogIndex = 3;
			}
			break;
		case 3:
			if (Player.goldWallet.balance < goldCost)
			{
				CurrentDialogIndex = 5;
			}
			break;
		case 4:
			HandleUpgradeOutfit();
			break;
		case 5:
			playerLeavingDialog = true;
			return true;
		case 6:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	private void HandleUpgradeOutfit(bool useToken = false)
	{
		if (playerBuffed[player.playerID])
		{
			CurrentDialogIndex = 4;
			return;
		}
		playerBuffed[player.playerID] = true;
		currentHealth = player.health.CurrentHealthValue + ((!useToken) ? (-healthCost) : 0);
		PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(15, player.transform.position + Vector3.up * 0.25f);
		SoundManager.PlayAudio("MenuBuy");
		SoundManager.PlayAudio("Tailor0");
		UpgradePlayerOutfit();
		if (useToken)
		{
			player.inventory.RemoveItem("TokenTailor", forceOverride: false, showNotice: true);
		}
		else
		{
			Player.goldWallet.Withdraw(goldCost);
		}
		player.health.CurrentHealthValue = Mathf.Max(1, currentHealth);
		RunData.miscTailorRoomFound = true;
	}

	private void UpgradePlayerOutfit()
	{
		if (Outfit.GetAvailableOutfit(player.outfitID) == null)
		{
			return;
		}
		if (player.equippedOutfit.useLeveling)
		{
			player.equippedOutfit.levelModStat.AddMod(new NumVarStatMod("TailorNPC", upgradeValue - 1f, 10, VarStatModType.Multiplicative));
			RunData.prdDict[player.playerID].outFitEnhanced = true;
			player.outfitEnhanced = true;
			Globals.ChaosInst<Transform>(SparklePrefab, player.attackOriginTrans, player.attackOriginTrans.position);
			return;
		}
		currentOutfit = new Outfit(Outfit.GetAvailableOutfit(player.outfitID));
		Outfit.GetAvailableOutfit(player.outfitID).SetEquipStatus(player, status: false);
		if (currentOutfit.outfitID == "Hope" && currentOutfit.modList.Count <= 1)
		{
			currentOutfit = Outfit.enhancedHope;
		}
		else if (currentOutfit.outfitID == "Patience" && currentOutfit.modList.Count <= 1)
		{
			currentOutfit = Outfit.enhancedPatience;
		}
		else
		{
			foreach (OutfitModStat mod in currentOutfit.modList)
			{
				currentMod = mod;
				if (currentMod == null)
				{
					continue;
				}
				if (currentMod.modType == OutfitModStat.OutfitModType.Health)
				{
					if (currentMod.addModifier.modValue > 0f)
					{
						currentMod.addModifier.modValue *= upgradeValue;
					}
					if (currentMod.multiModifier.modValue > 0f)
					{
						currentMod.multiModifier.modValue *= upgradeValue;
					}
				}
				else
				{
					currentMod.addModifier.modValue *= upgradeValue;
					currentMod.multiModifier.modValue *= upgradeValue;
					currentMod.overrideModifier.modValue *= upgradeValue;
				}
			}
		}
		currentOutfit.SetEquipStatus(player, status: true);
		player.equippedOutfit = currentOutfit;
		player.outfitEnhanced = true;
		if (RunData.prdDict.ContainsKey(player.playerID) && RunData.prdDict[player.playerID] != null)
		{
			RunData.prdDict[player.playerID].outFitEnhanced = true;
		}
		Globals.ChaosInst<Transform>(SparklePrefab, player.attackOriginTrans, player.attackOriginTrans.position);
	}
}
using System;
using System.Collections.Generic;
using UnityEngine;

public class OutfitMerchantNpc : Npc
{
	private bool wardrobeUnlocked;

	public bool noOutfitsAvailable;

	private static bool[] playerBuffed = new bool[GameController.maxPlayerCount];

	public int outfitsOnSaleCount = 3;

	public int availableOutfitCount;

	private List<string> lockedOutfitIDList = new List<string>();

	private Vector2 spawnOrigin = Vector2.zero;

	private Vector2[] spawnPositions = new Vector2[3]
	{
		new Vector2(-2f, 0f),
		new Vector2(0f, 0f),
		new Vector2(2f, 0f)
	};

	private int cost = 5;

	private int endDialogIndex = 4;

	private List<string> bossNameList = new List<string> { "EarthBoss", "FireBoss", "IceBoss", "AirBoss", "LightningBoss" };

	public override void Awake()
	{
		base.Awake();
		Transform transform = base.transform.Find("OutfitSpawnLocation");
		if (transform != null)
		{
			spawnOrigin = transform.position;
		}
	}

	public override void Start()
	{
		base.Start();
		wardrobeUnlocked = GameDataManager.gameData.CheckNPCStatus("Ward");
		overheadPromptHeight = 3f;
		if (wardrobeUnlocked)
		{
			LoadOutfitItems();
		}
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Remove(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.playerDestroyEventHandlers = (Player.PlayerEventHandler)Delegate.Combine(Player.playerDestroyEventHandlers, new Player.PlayerEventHandler(PlayerDestroyEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Remove(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
		Player.outfitEquipEventHandlers = (Player.OutfitEquipEventHandler)Delegate.Combine(Player.outfitEquipEventHandlers, new Player.OutfitEquipEventHandler(PlayerOutfitEquipEvent));
	}

	public static void PlayerDestroyEvent(Player player)
	{
		playerBuffed[player.playerID] = false;
	}

	public static void PlayerOutfitEquipEvent(Player player, string outfitID)
	{
		if (playerBuffed[player.playerID])
		{
			playerBuffed[player.playerID] = false;
			Outfit.SavileOutfit.SetEquipStatus(player, status: false);
		}
	}

	public override bool HandleConditionalInteraction()
	{
		if (myDialogID != "OutfitMerchant-Hub")
		{
			return false;
		}
		if (playerBuffed[player.playerID] && CurrentDialogIndex < endDialogIndex)
		{
			CurrentDialogIndex = endDialogIndex;
			return false;
		}
		switch (CurrentDialogIndex)
		{
		case 0:
			if (!player.outfitEnhanceAllowStat.CurrentValue)
			{
				CurrentDialogIndex = 6;
				return false;
			}
			break;
		case 2:
			if (Player.platWallet.balance >= cost)
			{
				CurrentDialogIndex = 3;
			}
			break;
		case 3:
			playerLeavingDialog = true;
			return true;
		case 4:
			playerBuffed[player.playerID] = true;
			Player.platWallet.Withdraw(cost);
			SoundManager.PlayAudio("MenuBuy");
			SoundManager.PlayAudio("Tailor0");
			Outfit.SavileOutfit.outfitColorIndex = player.outfitColorIndex;
			Outfit.GetAvailableOutfit(player.outfitID).SetEquipStatus(player, status: false);
			Outfit.SavileOutfit.SetEquipStatus(player, status: true);
			player.equippedOutfit = Outfit.SavileOutfit;
			PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(13, player.transform.position + Vector3.up * 0.25f);
			GameDataManager.Save();
			break;
		case 6:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	private void LoadOutfitItems()
	{
		lockedOutfitIDList.Clear();
		Outfit.UpdateOutfitDictData();
		foreach (Outfit outfit in Outfit.OutfitList)
		{
			if (outfit != null && !outfit.unlocked)
			{
				lockedOutfitIDList.Add(outfit.outfitID);
			}
		}
		availableOutfitCount = lockedOutfitIDList.Count;
		noOutfitsAvailable = availableOutfitCount == 0;
		int num = 0;
		for (int i = 0; i < availableOutfitCount; i++)
		{
			if (num >= outfitsOnSaleCount)
			{
				break;
			}
			if (ConditionalRequirementMet(lockedOutfitIDList[i]))
			{
				CreateOutfitStoreItem(spawnPositions[num] + spawnOrigin, lockedOutfitIDList[i]);
				num++;
			}
		}
		for (int j = num; j < outfitsOnSaleCount; j++)
		{
			CreateOutfitStoreItem(spawnPositions[j] + spawnOrigin, string.Empty);
		}
	}

	private void CreateOutfitStoreItem(Vector2 givenPosition, string givenID)
	{
		OutfitStoreItem outfitStoreItem = Globals.ChaosInst<OutfitStoreItem>(OutfitStoreItem.Prefab, transform, givenPosition);
		outfitStoreItem.outfitID = givenID;
		outfitStoreItem.outfitMerchant = this;
		outfitStoreItem.parentNpc = this;
		outfitStoreItem.usePlatinumCost = true;
	}

	private bool ConditionalRequirementMet(string givenName)
	{
		if (GameDataManager.gameData == null || GameDataManager.gameData.gameStats == null)
		{
			return true;
		}
		switch (givenName)
		{
		case "Venture":
			foreach (string bossName in bossNameList)
			{
				if (GameDataManager.gameData.gameStats.GetEnemyDefeatedCount(bossName) > 0)
				{
					return true;
				}
			}
			return false;
		case "Fall":
			return GameDataManager.GameCleared;
		case "Pride":
			return GameDataManager.GameCleared;
		case "Level":
			return GameDataManager.GameCleared;
		default:
			return true;
		}
	}
}
