using UnityEngine;

public class WardrobeNpc : Npc
{
	private static GameObject prefab;

	private bool closeAnimPlayed = true;

	private int idleAnimTimer = -1;

	private float idleAnimTime = 1f;

	private float minIdleAnimTime = 2f;

	private float maxIdleAnimTime = 5f;

	private string[] idleAnimNames = new string[2] { "Mustache", "Blink" };

	private bool dialogCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/WardrobeNpc.prefab"));

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 4f;
	}

