	{
		if (col.gameObject.name == "AllyFloorContact")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (player == null && component != null && !PlayerRoomUI.CurrentUI.IsUsingWardrobe(component))
			{
				player = component;
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}

	public void HandleIdleAnim()
	{
		if (!PlayerRoomUI.CurrentUI.WardrobeIsOpen && closeAnimPlayed && anim.AnimPlayed() && ChaosStopwatch.Check(idleAnimTimer))
		{
			anim.Play(idleAnimNames.GetRandomValue(), -1, 0f);
			idleAnimTimer = ChaosStopwatch.Begin(idleAnimTime);
			idleAnimTime = Random.Range(minIdleAnimTime, maxIdleAnimTime);
		}
	}
}

