using UnityEngine;
using UnityEngine.SceneManagement;

public class Npc : MonoBehaviour
{
	[HideInInspector]
	public Player player;

	[HideInInspector]
	public bool playerLeavingDialog;

	[HideInInspector]
	public bool isSpeaking;

	[HideInInspector]
	public SpriteRenderer sprite;

	[HideInInspector]
	public Animator anim;

	public bool autoFacePlayer = true;

	public bool facingRight = true;

	protected float defaultXScale = 1f;

	[HideInInspector]
	private SpriteRenderer headSpriteRenderer;

	public Sprite headLeftSprite;

	public Sprite headRightSprite;

	public Vector3 headLeftOffset;

	private OverheadPrompt overHeadPrompt;

	protected float overheadPromptHeight;

	public float overheadPromptXOffset;

	public float overheadPromptYOffset;

	public bool ignoreEnemiesInRange;

	public bool flipAutoX;

	public bool hidePrompt = true;

	public bool autoTriggerDialog;

	public bool disableAutoTrigger;

	public bool autoDisableNpc;

	public Collider2D activationTrigger;

	public string myDialogID = string.Empty;

	public bool useObjectNameAsDialogID;

	public bool appendSceneNameToDialogID = true;

	public float enemyDetectionRange = 8f;

	public float maxPlayerRange = 3f;

	private float dialogDelay = 0.0625f;

	private int dialogDelayStopwatchID = -1;

	public bool randomizeDialog;

	public int randomizeCount;

	public int randomDialogMsgLength = 1;

	protected int randomDialogIndex = -1;

	public EmoteType defaultEmote;

	private Vector3 emoteOffset = new Vector3(0f, 2.75f, 0f);

	public OverheadPrompt CurrentOverheadPrompt
	{
		get
		{
			return overHeadPrompt ?? (overHeadPrompt = PoolManager.GetPoolItem<OverheadPrompt>());
		}
		set
		{
			if (value == null && overHeadPrompt != null)
			{
				overHeadPrompt.HidePrompt(string.Empty);
				overHeadPrompt = null;
			}
		}
	}

	public int CurrentDialogIndex
	{
		get
		{
			return DialogManager.dialogDict[myDialogID].CurrentIndex;
		}
		set
		{
			DialogManager.dialogDict[myDialogID].CurrentIndex = value;
		}
	}

	public virtual void Awake()
	{
		playerLeavingDialog = false;
		activationTrigger = GetComponent<Collider2D>();
		anim = GetComponent<Animator>();
		overheadPromptHeight = 2.75f;
		Transform transform = base.transform.Find("NpcSprite");
		if (transform != null)
		{
			sprite = transform.GetComponent<SpriteRenderer>();
		}
		transform = base.transform.Find("NpcHeadSprite");
		if (transform != null)
		{
			headSpriteRenderer = transform.GetComponent<SpriteRenderer>();
		}
		defaultXScale = base.transform.localScale.x;
	}

	public virtual void Start()
	{
		SpawnCompassTrigger();
		if (useObjectNameAsDialogID)
		{
			myDialogID = gameObject.name;
		}
		if (appendSceneNameToDialogID)
		{
			myDialogID = myDialogID + "-" + SceneManager.GetActiveScene().name;
		}
		if (randomizeDialog)
		{
			randomDialogIndex = Random.Range(0, randomizeCount) * randomDialogMsgLength;
		}
	}

	public virtual void Update()
	{
		if (player == null)
		{
			return;
		}
		if (Vector2.Distance(player.transform.position, transform.position) > maxPlayerRange)
		{
			player = null;
			CurrentOverheadPrompt = null;
			return;
		}
		if (autoFacePlayer)
		{
			FacePlayer();
		}
		if (playerLeavingDialog)
		{
			playerLeavingDialog = false;
			Exiting();
		}
		else
		{
			if (player.fsm.currentStateName.Contains("Dead"))
			{
				return;
			}
			if (GameUI.dialogManager.IsActive)
			{
				if (!(DialogManager.currentDialogID == myDialogID) || !ChaosStopwatch.Check(dialogDelayStopwatchID))
				{
					return;
				}
				if (player.inputDevice.GetButtonDown("Confirm") || player.inputDevice.GetButtonDown("Interact"))
				{
					if (!HandleDialogDelay())
					{
						Interacted();
					}
				}
				else if (player.inputDevice.GetButtonUp("Cancel") && !HandleDialogDelay())
				{
					playerLeavingDialog = true;
				}
			}
			else if (!player.fsm.currentStateName.Contains("Paused") && player.inputDevice.GetButtonDown("Interact"))
			{
				if (randomizeDialog)
				{
					CurrentDialogIndex = randomDialogIndex;
				}
				Interacted();
			}
		}
	}

	public virtual bool HandleDialogDelay()
	{
		if (GameUI.dialogManager.EndGhostWrite())
		{
			dialogDelayStopwatchID = ChaosStopwatch.Begin(dialogDelay);
			return true;
		}
		return false;
	}

	public virtual void SpawnCompassTrigger()
	{
		Compass.CompassIndicatorType indicatorType;
		switch (myDialogID)
		{
		default:
			return;
		case "ItemMerchant":
			indicatorType = Compass.CompassIndicatorType.ItemMerchant;
			break;
		case "SpellMerchant":
			indicatorType = Compass.CompassIndicatorType.SpellMerchant;
			break;
		case "CursedMerchant":
			indicatorType = Compass.CompassIndicatorType.CursedStore;
			break;
		}
		CompassIndicatorTrigger.Spawn(indicatorType, transform.position, transform);
	}

	public virtual void FacePlayer(float worldXPos = 99999f)
	{
		if (worldXPos == 99999f)
		{
			worldXPos = player.transform.position.x;
		}
		if (!(sprite != null))
		{
			return;
		}
		bool flag = worldXPos > transform.position.x;
		if (flag == facingRight)
		{
			return;
		}
		facingRight = flag;
		if (headSpriteRenderer != null)
		{
			if (!facingRight)
			{
				if (headLeftSprite != null)
				{
					headSpriteRenderer.sprite = headLeftSprite;
					return;
				}
				headSpriteRenderer.transform.localScale = new Vector3(0f - defaultXScale, 1f, 1f);
				headSpriteRenderer.transform.position += headLeftOffset;
			}
			else if (headRightSprite != null)
			{
				headSpriteRenderer.sprite = headRightSprite;
			}
			else
			{
				headSpriteRenderer.transform.localScale = new Vector3(defaultXScale, 1f, 1f);
				headSpriteRenderer.transform.position -= headLeftOffset;
			}
		}
		else
		{
			Vector3 localScale = (facingRight ? Vector3.one : new Vector3(-1f, 1f, 1f));
			if (flipAutoX)
			{
				localScale = new Vector3(localScale.x * -1f, localScale.y, localScale.z);
			}
			sprite.transform.localScale = localScale;
		}
	}

	public virtual void Interacted()
	{
		if ((DialogManager.dialogInProgress && DialogManager.currentDialogID != myDialogID) || (PlayerRoomUI.CurrentUIExists && PlayerRoomUI.CurrentUI.AnyUIOpen))
		{
			return;
		}
		InteractEvent();
		isSpeaking = true;
		player.fsm.ChangeState("Paused");
		if (hidePrompt)
		{
			CurrentOverheadPrompt = null;
		}
		if (HandleConditionalInteraction())
		{
			return;
		}
		if (randomizeDialog && CurrentDialogIndex > randomDialogIndex + randomDialogMsgLength - 1)
		{
			playerLeavingDialog = true;
			return;
		}
		DialogManager dialogManager = GameUI.dialogManager;
		string dialogID = myDialogID;
		string playerIDOverride = player.playerData.name;
		if (!dialogManager.DisplayDialog(dialogID, -1, playerIDOverride, string.Empty, string.Empty))
		{
			playerLeavingDialog = true;
		}
	}

	public virtual void InteractEvent()
	{
	}

	public virtual bool HandleConditionalInteraction()
	{
		return false;
	}

	public virtual void Exiting()
	{
		player.fsm.ChangeState(player.fsm.defaultStateName);
		player = null;
		GameUI.dialogManager.ResetDialog(myDialogID);
		GameUI.dialogManager.Deactivate();
		if (autoTriggerDialog)
		{
			autoTriggerDialog = !disableAutoTrigger;
		}
		if (autoDisableNpc)
		{
			activationTrigger.enabled = false;
			enabled = false;
		}
	}

	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (!autoTriggerDialog)
		{
			return;
		}
		if (!ignoreEnemiesInRange && Entity.GetAllTargetsInRange(GameController.enemies, transform.position, enemyDetectionRange).Count > 0)
		{
			if (player != null)
			{
				player.fsm.ChangeState(player.fsm.defaultStateName);
				GameUI.dialogManager.Deactivate();
			}
			OnTriggerExit2D(col);
		}
		else if (col.gameObject.name == "AllyFloorContact" && col.transform.parent.gameObject.GetComponent<Player>() != null && player == null)
		{
			player = col.transform.parent.gameObject.GetComponent<Player>();
			if (!GameUI.dialogManager.IsActive && !player.fsm.currentStateName.Contains("Paused") && !player.fsm.currentStateName.Contains("Dead"))
			{
				Interacted();
			}
		}
	}

	public void PlayDefaultEmote()
	{
		if (defaultEmote != EmoteType.None)
		{
			PlayEmote(defaultEmote);
		}
	}

	public void PlayEmote(EmoteType emoteType)
	{
		PoolManager.GetPoolItem<EmoteEmitter>().Emit(emoteType, 1, transform.position + emoteOffset, ParticleEffectOverrides.LayerOverlayDoodad);
	}

	public virtual void OnTriggerStay2D(Collider2D col)
	{
		if (!ignoreEnemiesInRange && Entity.GetAllTargetsInRange(GameController.enemies, transform.position, enemyDetectionRange).Count > 0)
		{
			if (player != null)
			{
				player.fsm.ChangeState(player.fsm.defaultStateName);
				GameUI.dialogManager.Deactivate();
			}
			OnTriggerExit2D(col);
		}
		else
		{
			if (!(col.gameObject.name == "AllyFloorContact") || !(col.transform.parent.gameObject.GetComponent<Player>() != null))
			{
				return;
			}
			if (autoTriggerDialog)
			{
				if (player == null)
				{
					player = col.transform.parent.gameObject.GetComponent<Player>();
				}
				if (!GameUI.dialogManager.IsActive && !player.fsm.currentStateName.Contains("Paused") && !player.fsm.currentStateName.Contains("Dead"))
				{
					Interacted();
				}
			}
			if (player == null)
			{
				player = col.transform.parent.gameObject.GetComponent<Player>();
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight + overheadPromptYOffset, overheadPromptXOffset);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}

	public void ForcePlayerActivation(Player newPlayer)
	{
		if (player == null)
		{
			player = newPlayer;
		}
		if (!GameUI.dialogManager.IsActive)
		{
			Interacted();
		}
	}

	public virtual void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact" && col.transform.parent.gameObject.GetComponent<Player>() != null && player != null && player == col.transform.parent.gameObject.GetComponent<Player>())
		{
			if (isSpeaking && GameUI.dialogManager.IsActive && DialogManager.currentDialogID == myDialogID)
			{
				Exiting();
			}
			CurrentOverheadPrompt = null;
			player = null;
			isSpeaking = false;
		}
	}
}
using UnityEngine;

public class BankerNpc : Npc
{
	private bool goldTraded;

	private bool useBonus;

	private int bonusAmount = 19;

	public override void Start()
	{
		CompassIndicatorTrigger.Spawn(Compass.CompassIndicatorType.BankerRoom, transform.position, transform);
	}

	public override bool HandleConditionalInteraction()
	{
		switch (DialogManager.dialogDict[myDialogID].CurrentIndex)
		{
		case 0:
			if (goldTraded)
			{
				DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
			}
			break;
		case 2:
			useBonus = player.inventory.ContainsItem("TokenBanker");
			if (!goldTraded && player != null && (useBonus || Player.goldWallet.balance > 0))
			{
				TradeGold(useBonus);
			}
			break;
		case 3:
			if (!goldTraded)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 4:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	private void TradeGold(bool givenBonus)
	{
		goldTraded = true;
		int num = Mathf.CeilToInt((float)Player.goldWallet.balance * ((!Inventory.EitherPlayerHasItem("TokenBanker")) ? 0.09f : 0.125f));
		Player.platWallet.Deposit(Mathf.Clamp(num, 1, Player.platWallet.maxBalance));
		GameController.levelPlat += num;
		GameController.totalPlat += num;
		Player.goldWallet.Withdraw(Player.goldWallet.balance);
		SoundManager.PlayAudio("MenuBuy");
		PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.AwwYis, 1, transform.position + Vector3.up * 2.75f);
		SoundManager.PlayAudio((!Globals.RandBool) ? "Banker1" : "Banker0");
		DialogManager.dialogDict[myDialogID].CurrentIndex = 3;
		RunData.miscBankerRoomFound = true;
		if (givenBonus)
		{
			player.inventory.RemoveItem("TokenBanker", forceOverride: false, showNotice: true);
			LootManager.DropPlat(transform.position, bonusAmount);
		}
	}
}
