using UnityEngine;

public class BossRushNpc : Npc
{
	public GameObject bossRushTP;

	public GameObject bossRushTPDisabled;

	private int cost = 10;

	public override void Start()
	{
		base.Start();
		if (GameController.runModifier.HasMod("RushRunMod"))
		{
			EnableTeleporter();
		}
	}

	public override bool HandleConditionalInteraction()
	{
		if (GameController.runModifier.HasMod("RushRunMod") && CurrentDialogIndex < 3)
		{
			CurrentDialogIndex = 4;
			return false;
		}
		switch (CurrentDialogIndex)
		{
		case 3:
			if (Player.platWallet.balance >= cost)
			{
				Player.platWallet.Withdraw(cost);
				SoundManager.PlayAudio("MenuBuy");
				SoundManager.PlayAudio("BossRush0");
				GameController.runModifier.AddMod(new RushRunMod());
				CurrentDialogIndex = 4;
				EnableTeleporter();
				PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(7, bossRushTP.transform.position);
				PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(4, bossRushTP.transform.position + Vector3.up * 2f);
				PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, bossRushTP.transform.position + Vector3.left * 1.5f);
				PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, bossRushTP.transform.position + Vector3.right * 1.5f);
			}
			break;
		case 4:
			playerLeavingDialog = true;
			return true;
		}
		return false;
	}

	public void EnableTeleporter()
	{
		bossRushTP.SetActive(value: true);
		bossRushTPDisabled.SetActive(value: false);
	}
}
