public class BroomNpc : Npc
{
	public class BroomIdleState : State<BroomNpc>
	{
		private int broomIdleStopwatchID = -1;

		private new BroomNpc parent;

		public BroomIdleState(string stateName, FSM parentFSM, BroomNpc parentObj)
			: base(stateName, parentFSM, parentObj)
		{
			parent = parentObj;
		}

		public override void OnEnter()
		{
			broomIdleStopwatchID = ChaosStopwatch.Begin(Random.Range(1f, 3f));
