			{
				InitCardShuffle();
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 4:
			if (!cardShuffleInitiated)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		case 5:
			if (cardShuffleInitiated)
			{
				playerLeavingDialog = true;
				return true;
			}
			break;
		}
		return false;
	}

	private void InitCardShuffle()
	{
		cardShuffleInitiated = true;
		shuffledPlayer = player;
		RunData.miscSlotsRoomFound = true;
		SoundManager.PlayAudio("Shuffler0");
		StartCoroutine(ShuffleCards(playerHasToken));
	}

	private IEnumerator ShuffleCards(bool useToken)
	{
		shufflingInProgress = true;
		if (useToken)
		{
			shuffledPlayer.inventory.RemoveItem("TokenShuffler", forceOverride: false, showNotice: true);
		}
		else
		{
			shuffledPlayer.RemoveSkill(player.GetRandomStandardSkill(allowEmp: false) ?? player.GetRandomStandardSkill());
		}
		for (int i = 0; i < 5; i++)
		{
			currentSSItem = skillItems[i];
			if (!(currentSSItem == null))
			{
				currentSSItem.costStat.AddMod(costOverrideMod);
				currentSSItem.anim.Play("SpawnFlipped", -1, 0f);
				currentSSItem.SetAllowedPlayerID(shuffledPlayer.playerID);
			}
		}
		SoundManager.PlayAudioWithDistance("CardSpawn", transform.position);
		yield return waitForHideDelay;
		lerpStopwatch.IsRunning = true;
		isLerping = true;
		SoundManager.PlayAudio("CardShuffle");
		while (isLerping)
		{
			for (int j = 0; j < 5; j++)
			{
				skillItems[j].transform.position = Vector2.Lerp(shuffledVectors[j], centeredVectors[j], lerpStopwatch.TimePercentage);
			}
			isLerping = lerpStopwatch.IsRunning;
			yield return null;
		}
		yield return waitForGatherDelay;
		for (int k = 0; k < 4; k++)
		{
			StartCoroutine(SpinCard(skillItems[k].transform));
			yield return waitForSpinDelay;
		}
		yield return StartCoroutine(SpinCard(skillItems[4].transform));
		shuffledVectors.Shuffle();
		lerpStopwatch.IsRunning = true;
		isLerping = true;
		while (isLerping)
		{
			for (int l = 0; l < 5; l++)
			{
				skillItems[l].transform.position = Vector2.Lerp(centeredVectors[l], shuffledVectors[l], lerpStopwatch.TimePercentage);
			}
			isLerping = lerpStopwatch.IsRunning;
			yield return null;
		}
		for (int m = 0; m < 5; m++)
		{
			currentSSItem = skillItems[m];
			if (!(currentSSItem == null))
			{
				currentSSItem.overheadPromptHeight = 2.25f;
				currentSSItem.SetPromptTriggerStatus(status: true);
				currentSSItem.SetLightStatus(status: true);
				currentSSItem.anim.Play("Unflip", -1, UnityEngine.Random.Range(0f, 0.125f));
				SoundManager.PlayAudio("CardSelect");
			}
		}
		shufflingInProgress = false;
		pickingInProgress = true;
	}

	private IEnumerator SpinCard(Transform givenTrans)
	{
		Vector2 spinVector = Vector2.zero;
		int spinCount = 4;
		float minAngle = -(float)Math.PI / 2f;
		float maxAngle = (2f * (float)spinCount - 0.5f) * (float)Math.PI;
		float spinAngle = 0f;
		int spinStopwatchID = ChaosStopwatch.Begin(4f);
		bool isSpinning = true;
		float minRadius = 0f - givenTrans.localPosition.y;
		float maxRadius = 3f;
		float radiusValue = 0f;
		for (int i = 0; i < 5; i++)
		{
			skillItems[i].itemSpriteRenderer.sortingLayerName = "Overlay";
			skillItems[i].itemBGSpriteRenderer.sortingLayerName = "Overlay";
			skillItems[i].standardSR.sortingLayerName = "Overlay";
			skillItems[i].empoweredSR.sortingLayerName = "Overlay";
			skillItems[i].sigSR.sortingLayerName = "Overlay";
		}
		while (isSpinning)
		{
			float spinValue = Globals.GetSmoothLerpValue(ChaosStopwatch.GetTimePercentage(spinStopwatchID));
			spinAngle = Mathf.Lerp(minAngle, maxAngle, spinValue);
			spinVector.x = Mathf.Cos(spinAngle);
			spinVector.y = Mathf.Sin(spinAngle);
			radiusValue = Mathf.Lerp(minRadius, maxRadius, Mathf.PingPong(spinValue * 4f, 1f));
			if (spinValue > 0.25f && spinValue < 0.75f)
			{
				radiusValue = Mathf.Clamp(radiusValue, 0.25f, maxRadius);
			}
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.SetDelay(Mathf.Lerp(0.2f, 0.0625f, Mathf.Pow(1f + Mathf.PingPong(spinValue * 2f, 1f), 2f) - 1f), stopCurrent: false, autoStart: true);
				SoundManager.PlayAudioWithDistance("CardSelect", transform.position);
			}
			givenTrans.position = currentPosition + spinVector * (radiusValue + 1f);
			isSpinning = !ChaosStopwatch.Check(spinStopwatchID);
			yield return null;
		}
		for (int j = 0; j < 5; j++)
		{
			skillItems[j].itemSpriteRenderer.sortingLayerName = "Actor";
			skillItems[j].itemBGSpriteRenderer.sortingLayerName = "Actor";
			skillItems[j].standardSR.sortingLayerName = "Actor";
			skillItems[j].empoweredSR.sortingLayerName = "Actor";
			skillItems[j].sigSR.sortingLayerName = "Actor";
		}
	}

	private void OnCardSelected(Player givenPlayer, StoreItem storeItem)
	{
		pickCounter++;
		SoundManager.PlayAudio("Powerup");
		if (pickCounter < allowedPickCount)
		{
			return;
		}
		pickingInProgress = false;
		for (int i = 0; i < 5; i++)
		{
			currentSSItem = skillItems[i];
			if (!(currentSSItem == null))
			{
				SkillStoreItem skillStoreItem = currentSSItem;
				skillStoreItem.buyEventHandlers = (StoreItem.BuyEventHandler)Delegate.Remove(skillStoreItem.buyEventHandlers, new StoreItem.BuyEventHandler(OnCardSelected));
				currentSSItem.SetPromptTriggerStatus(status: false);
				currentSSItem.anim.Play("Hide", -1, 0f);
			}
		}
	}
}

using Chaos.AnimatorExtensions;
using UnityEngine;

public class MimicNpc : Npc
{
	private static GameObject prefab;

	private WeightedRandomizer openAnimRandomizer;

	private WeightedRandomizer closeAnimRandomizer;

	private ChaosQuickStopwatch animStopwatch;

	private bool closed = true;

	private string nextAnim = "Closed";

	private string lastAnim = "Closed";

	private bool dialogCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/Mimic.prefab"));

	public override void Awake()
	{
		base.Awake();
		openAnimRandomizer = new WeightedRandomizer();
		openAnimRandomizer.Add(new WeightedItem("LookLeft", 5));
		openAnimRandomizer.Add(new WeightedItem("LookRight", 5));
		openAnimRandomizer.Add(new WeightedItem("Opened", 20));
		openAnimRandomizer.Add(new WeightedItem("Blink", 30));
		openAnimRandomizer.Add(new WeightedItem("Close", 10));
		closeAnimRandomizer = new WeightedRandomizer();
		closeAnimRandomizer.Add(new WeightedItem("Peek", 10));
		closeAnimRandomizer.Add(new WeightedItem("Open", 10));
	}

	public override void Start()
	{
		base.Start();
		animStopwatch = new ChaosQuickStopwatch(Random.Range(4f, 7f));
		animStopwatch.IsRunning = true;
	}

	public override void Update()
	{
		if (!animStopwatch.IsRunning && anim.AnimPlayed())
		{
			nextAnim = "Closed";
			if (closed)
			{
				for (int i = 0; i < 5; i++)
				{
					nextAnim = closeAnimRandomizer.GetRandomItem().name;
					if (nextAnim != lastAnim)
					{
						break;
					}
				}
			}
			else
			{
				for (int j = 0; j < 5; j++)
				{
					nextAnim = openAnimRandomizer.GetRandomItem().name;
					if ((!isSpeaking || !(nextAnim == "Close")) && nextAnim != lastAnim)
					{
						break;
					}
				}
			}
			anim.Play(nextAnim, -1, 0f);
			lastAnim = nextAnim;
			if (nextAnim == "Close")
			{
				closed = true;
			}
			else if (nextAnim == "Open")
			{
				closed = false;
			}
			animStopwatch.SetDelay(Random.Range(4f, 7f), stopCurrent: false, autoStart: true);
		}
		if (!(player != null) || !PlayerRoomUI.CurrentUI.IsUsingSpellBook(player))
		{
			base.Update();
		}
	}

	public override void Interacted()
	{
		if (!(player != null) || !PlayerUIBase.GetLock("RelicChestUI" + player.playerID))
		{
			if (dialogCompleted || PlayerRoomUI.CurrentUI.AnyUIOpen)
			{
				CurrentOverheadPrompt = null;
				Exiting();
			}
			else
			{
				base.Interacted();
			}
		}
	}

	public override void InteractEvent()
	{
		if (!isSpeaking)
		{
			if (closed)
			{
				anim.Play("Open");
				closed = false;
			}
			else if (anim.AnimPlayed())
			{
				anim.Play("Jump", -1, 0f);
			}
			animStopwatch.SetDelay(Random.Range(4f, 7f), stopCurrent: false, autoStart: true);
		}
	}

	public override void Exiting()
	{
		Player player = base.player;
		base.Exiting();
		if (!myDialogID.EndsWith("Ending"))
		{
			if (!PlayerRoomUI.CurrentUI.IsUsingRelicChest(player))
			{
				PlayerRoomUI.CurrentUI.OpenRelicChest(player, transform.position);
			}
			dialogCompleted = true;
		}
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (player == null && component != null && !PlayerRoomUI.CurrentUI.IsUsingRelicChest(component))
			{
				player = component;
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}
}
using System.Collections;
using UnityEngine;

public class JukeboxNpc : Npc
{
	private static GameObject prefab;

	public SpriteRenderer albumIndicatorSprite;

	public Sprite[] albumIndicatorSprites;

	private const int EndDialogIndex = 4;

	private int albumDialog = 1;

	private bool trackChanged;

	private Vector2 fxPosition;

	private ParticleEffect noteEmitter;

	private static WaitForSeconds waitForNote = new WaitForSeconds(0.35f);

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/JukeboxNpc.prefab"));

	public override void Start()
	{
		base.Start();
		SetAlbumIndicator(SoundManager.bgmTrack);
		albumDialog = (int)(SoundManager.bgmTrack + 1);
	}

	public override void Interacted()
	{
		if (!isSpeaking)
		{
			anim.Play("Interact", -1, 0f);
		}
		base.Interacted();
	}

	public override bool HandleConditionalInteraction()
	{
		switch (CurrentDialogIndex)
		{
		case 1:
			CurrentDialogIndex = albumDialog;
			break;
		case 2:
			SelectAlbum(BGMTrackType.Jazz);
			break;
		case 3:
			SelectAlbum(BGMTrackType.Piano);
			break;
		case 4:
			SelectAlbum(BGMTrackType.Original);
			break;
		}
		return false;
	}

	private void SelectAlbum(BGMTrackType givenType)
	{
		StartCoroutine(HandleTransition(givenType));
		albumDialog++;
		if (albumDialog > 3)
		{
			albumDialog = 1;
		}
		PlayDefaultEmote();
		anim.Play("Dance", -1, 0f);
		SetAlbumIndicator(givenType);
		SoundManager.PlayAudio("StandardChestSpawn");
		CurrentDialogIndex = 4;
		trackChanged = true;
	}

	private void SetAlbumIndicator(BGMTrackType givenType)
	{
		switch (givenType)
		{
		case BGMTrackType.Original:
			albumIndicatorSprite.enabled = false;
			break;
		case BGMTrackType.Jazz:
			albumIndicatorSprite.sprite = albumIndicatorSprites[0];
			albumIndicatorSprite.enabled = true;
			break;
		case BGMTrackType.Piano:
			albumIndicatorSprite.sprite = albumIndicatorSprites[1];
			albumIndicatorSprite.enabled = true;
			break;
		}
	}

	public override void OnTriggerEnter2D(Collider2D col)
	{
		if (!trackChanged)
		{
			base.OnTriggerEnter2D(col);
		}
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (!trackChanged)
		{
			base.OnTriggerStay2D(col);
		}
	}

	public override void OnTriggerExit2D(Collider2D col)
	{
		base.OnTriggerExit2D(col);
		trackChanged = false;
	}

	private IEnumerator HandleTransition(BGMTrackType givenType)
	{
		GameDataManager.gameVars.SetValue(GameVarsKey.BgmTrack, (int)givenType);
		GameDataManager.SaveGameVars();
		yield return null;
		SoundManager.bgmTrack = givenType;
		SoundManager.PlayBGM("PlayerRoom");
		yield return null;
		fxPosition = transform.position + Vector3.up;
		for (int i = 0; i < 5; i++)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SparkleAura").Emit(3, fxPosition + new Vector2(Random.Range(-0.75f, 0.75f), 0.25f), ParticleEffectOverrides.LayerOverlayDoodad);
			EmitNote();
			yield return null;
		}
		yield return waitForNote;
		while (trackChanged || SoundManager.BGMTransitionInProgress)
		{
			EmitNote();
			yield return waitForNote;
		}
		anim.Play("Idle");
	}

	private void EmitNote()
	{
		if (noteEmitter == null)
		{
			noteEmitter = PoolManager.GetPoolItem<ParticleEffect>("MusicNoteEmitter");
		}
		noteEmitter.Emit(1, fxPosition + new Vector2(Random.Range(-1.125f, 1f), Random.Range(1f, 1.5f)), ParticleEffectOverrides.LayerOverlayDoodad);
	}
}
