using UnityEngine;

public class SpellBookNpc : Npc
{
	private static GameObject prefab;

	private bool returnAnimPlayed = true;

	private bool openAnimPlayed;

	private int idleAnimTimer = -1;

	private float idleAnimTime = 1f;

	private float minIdleAnimTime = 2f;

	private float maxIdleAnimTime = 5f;

	private string[] idleAnimNames = new string[2] { "BigChomp", "LeftRight" };

	private bool dialogCompleted;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/SpellBookNpc.prefab"));

	public override void Start()
	{
		base.Start();
		overheadPromptHeight = 3.25f;
	}

	public override void Update()
	{
		HandleIdleAnim();
		if (PlayerRoomUI.CurrentUI.SpellBookElementChosen && !openAnimPlayed)
		{
			anim.Play("Open", -1, 0f);
			openAnimPlayed = true;
		}
		if (!PlayerRoomUI.CurrentUI.SpellBookElementChosen && openAnimPlayed)
		{
			anim.Play("Close", -1, 0f);
			openAnimPlayed = false;
		}
		if (!PlayerRoomUI.CurrentUI.SpellBookIsOpen && !returnAnimPlayed)
		{
			anim.Play("Unstraighten", -1, 0f);
			openAnimPlayed = false;
			returnAnimPlayed = true;
			idleAnimTimer = ChaosStopwatch.Begin(idleAnimTime);
		}
		if (!(player != null) || !PlayerRoomUI.CurrentUI.IsUsingSpellBook(player))
		{
			base.Update();
		}
	}

	public override void Interacted()
	{
		if (dialogCompleted || PlayerRoomUI.CurrentUI.AnyUIOpen)
		{
			CurrentOverheadPrompt = null;
			Exiting();
			return;
		}
		if (!isSpeaking)
		{
			anim.Play("BigChomp", -1, 0f);
		}
		base.Interacted();
	}

	public override void Exiting()
	{
		Player player = base.player;
		base.Exiting();
		if (myDialogID.EndsWith("Ending"))
		{
			return;
		}
		if (!PlayerRoomUI.CurrentUI.IsUsingSpellBook(player))
		{
			if (!PlayerRoomUI.CurrentUI.SpellBookIsOpen)
			{
				anim.Play("Straighten", -1, 0f);
				openAnimPlayed = false;
			}
			PlayerRoomUI.CurrentUI.OpenSpellBook(player, transform.position);
			returnAnimPlayed = false;
		}
		dialogCompleted = true;
	}

	public override void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact")
		{
			Player component = col.transform.parent.gameObject.GetComponent<Player>();
			if (player == null && component != null && !PlayerRoomUI.CurrentUI.IsUsingSpellBook(component))
			{
				player = component;
				CurrentOverheadPrompt.Initialize(transform, player.inputDevice.inputScheme, overheadPromptHeight);
				CurrentOverheadPrompt.DisplayPrompt("Interact");
			}
		}
	}

	public void HandleIdleAnim()
	{
		if (!PlayerRoomUI.CurrentUI.SpellBookIsOpen && returnAnimPlayed && (!PlayerRoomUI.CurrentUI.SpellBookIsOpen || openAnimPlayed) && anim.AnimPlayed() && ChaosStopwatch.Check(idleAnimTimer))
		{
			anim.Play(idleAnimNames.GetRandomValue(), -1, 0f);
			idleAnimTimer = ChaosStopwatch.Begin(idleAnimTime);
			idleAnimTime = Random.Range(minIdleAnimTime, maxIdleAnimTime);
		}
	}
}
