using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public class Destructible : Entity
{
	public class DestructibleIdleState : State<Destructible>
	{
		public DestructibleIdleState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}
	}

	public class DestructibleDeadState : State<Destructible>
	{
		public DestructibleDeadState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			if (parent.dropLoot && parent.health != null && parent.health.lastAttack != null && !parent.health.lastAttack.skillCategory.Contains("Player"))
			{
				parent.dropLoot = false;
			}
			parent.Break();
			if (parent.autoDestroyOnDeath && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject, parent.autoDestroyDelay);
			}
		}
	}

	public class DestructibleHurtState : HurtState
	{
		public DestructibleHurtState(string stateName, FSM parentFSM, Destructible parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			playHurtAnim = false;
		}
	}

	public bool destroyed;

	public string destroyedAudioID;

	public bool autoDestroyOnDeath;

	public float autoDestroyDelay = 1.4f;

	public bool hideSpritesOnBreak;

	public bool disableCollidersOnBreak;

	public bool useFacingDirOverride;

	public FacingDirection facingDirOverride;

	public bool emitParticleEffectOnBreak;

	public string particleEffectName = string.Empty;

	public int particleCount;

	public Vector3 breakParticleOffset;

	public bool dropLoot = true;

	public string lootTableName = "Destructible";

	protected Vector3 lootDropOffset = Vector3.zero;

	public Transform subObjectTrans;

	public Destructible[] subObjDestructibles;

	public GameObject[] subObjs;

	protected Collider2D[] colliders;

	protected SpriteRenderer[] spriteRenderers;

	protected string incColliderName = string.Empty;

	protected bool allyContact;

	public bool destroyOnContact = true;

	public bool destroyScriptOnBreak;

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
		destroyed = false;
		colliders = GetComponentsInChildren<Collider2D>();
		spriteRenderers = GetComponentsInChildren<SpriteRenderer>();
		Transform transform = base.transform.Find("DestructibleSprite") ?? base.transform.Find("Sprite");
		if (transform != null)
		{
			spriteRenderer = transform.GetComponent<SpriteRenderer>();
		}
		else
		{
			spriteRenderer = GetComponentInChildren<SpriteRenderer>();
		}
		InitFSM();
	}

	public override void InitComponents()
	{
		base.InitComponents();
		if (health != null)
		{
			health.ignoreSlow.Modify(Health.baseIgnoreMod, addMod: true);
			health.ignorePoison.Modify(Health.baseIgnoreMod, addMod: true);
			health.ignoreFreeze.Modify(Health.baseIgnoreMod, addMod: true);
		}
	}

	public virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new DestructibleIdleState("Idle", fsm, this));
		fsm.AddState(new DestructibleDeadState("Dead", fsm, this));
		fsm.AddState(new DestructibleHurtState("Hurt", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void Start()
	{
		base.Start();
		if (useFacingDirOverride)
		{
			facingDirection = facingDirOverride;
			if (facingDirection == FacingDirection.Left)
			{
				isFacingRight = true;
			}
			else
			{
				isFacingRight = false;
			}
		}
		subObjectTrans = base.transform.Find("SubObjects");
		if (subObjectTrans != null)
		{
			List<GameObject> list = new List<GameObject>();
			foreach (Transform subObjectTran in subObjectTrans)
			{
				list.Add(subObjectTran.gameObject);
			}
			subObjDestructibles = subObjectTrans.GetComponentsInChildren<Destructible>();
			for (int i = 0; i < subObjDestructibles.Length; i++)
			{
				list.Remove(subObjDestructibles[i].gameObject);
				if (subObjDestructibles[i].hurtBoxCollider != null)
				{
					subObjDestructibles[i].hurtBoxCollider.gameObject.SetActive(value: false);
				}
				if (subObjDestructibles[i].floorCollider != null)
				{
					subObjDestructibles[i].floorCollider.gameObject.SetActive(value: false);
				}
			}
			subObjs = list.ToArray();
		}
		if (health != null)
		{
			health.entitySprites = new List<SpriteRenderer>();
			health.entitySprites = health.entitySprites.Where((SpriteRenderer y) => !y.gameObject.name.Contains("Shadow")).ToList();
			health.entitySprites.AddRange(GetComponentsInChildren<SpriteRenderer>());
		}
	}

	public virtual void Reset()
	{
		destroyed = false;
		if (anim != null)
		{
			anim.Play("Idle");
		}
		transform.position = myOrigin;
	}

	public void DestroySubObjects(int maxRetry = 4)
	{
		if (subObjDestructibles != null)
		{
			for (int i = 0; i < subObjDestructibles.Length; i++)
			{
				if (subObjDestructibles[i] != null)
				{
					subObjDestructibles[i].Break();
				}
			}
		}
		if (subObjs != null)
		{
			for (int j = 0; j < subObjs.Length; j++)
			{
				Object.Destroy(subObjs[j]);
			}
		}
	}

	public void EmitParticlesOnBreak()
	{
		if (emitParticleEffectOnBreak && particleCount > 0 && particleEffectName != string.Empty)
		{
			PoolManager.GetPoolItem<ParticleEffect>(particleEffectName).Emit(particleCount, hurtBoxTransform.position + breakParticleOffset);
		}
	}

	public virtual void Break()
	{
		if (health != null)
		{
			ApplyKnockback(health.lastAttack);
		}
		destroyed = true;
		if (anim != null)
		{
			anim.Play("Destroyed");
		}
		if (hideSpritesOnBreak)
		{
			for (int i = 0; i < spriteRenderers.Length; i++)
			{
				if (spriteRenderers[i] != null)
				{
					spriteRenderers[i].enabled = false;
				}
			}
		}
		if (disableCollidersOnBreak)
		{
			for (int j = 0; j < colliders.Length; j++)
			{
				if (colliders[j] != null)
				{
					colliders[j].enabled = false;
				}
			}
		}
		if (destroyedAudioID != string.Empty)
		{
			string audioID = destroyedAudioID;
			Vector2? soundOrigin = transform.position;
			float overridePitch = Random.Range(0.8f, 1.2f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
		if (dropLoot && (allyContact || (health != null && health.lastAttack != null && health.lastAttack.skillCategory.Contains("Player"))))
		{
			LootManager.DropLoot(lootTableName, transform.position + lootDropOffset);
		}
		EmitParticlesOnBreak();
		if (destroyScriptOnBreak)
		{
			Object.Destroy(this);
		}
		DestroySubObjects();
	}

	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (destroyOnContact && !destroyed && col != null)
		{
			incColliderName = col.gameObject.name;
			allyContact = incColliderName == Globals.allyFCStr;
			if (allyContact || incColliderName == Globals.enemyFCStr)
			{
				Vector3 position = col.transform.position;
				CameraController.ShakeCamera(0.125f);
				PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Small, position, position);
				string audioID = "ImpactPhysicalLight";
				Vector2? soundOrigin = position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				Break();
			}
		}
	}
}
using UnityEngine;

public class Hazard : MonoBehaviour
{
	public enum ActivationType
	{
		Always,
		Timer,
		Trigger,
		Disabled
	}

	public enum ActivationState
	{
		Deactivated,
		Windup,
		Activated
	}

	public enum TimerType
	{
		Local,
		Global,
		GlobalAlt,
		GRapidAlt
	}

	private static ActivationState globalState;

	private static int globalStopwatchID;

	public const float globalDeactivatedTime = 2f;

	public const float globalWindupTime = 1f;

	public const float globalActivatedTime = 2f;

	private static int globalAltCounter;

	private static ActivationState globalAltPri;

	private static ActivationState globalAltSec;

	private static int globalAltStopwatchID;

	public const float globalAltOpen = 0.75f;

	public const float globalAltClosed = 2f;

	private static int gRapidAltCounter;

	private static ActivationState gRapidAltPri;

	private static ActivationState gRapidAltSec;

	public static int gRapidAltStopwatchID;

	public const float gRapidTime = 0.75f;

	protected static string hazardSkillCategory = "EnemyFFA";

	public ActivationType activationType = ActivationType.Disabled;

	public string skillID;

	protected ActivationState currentState;

	protected ActivationState tempState;

	protected bool stateCleared;

	public TimerType timerType;

	public bool isGlobalAltPrimary;

	public float windupTime = 1f;

	public float activatedTime = 2f;

	public float deactivatedTime = 2f;

	protected int instStopwatchID;

	protected Transform atkTrans;

	protected Attack attack;

	protected Collider2D atkCollider;

	protected ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch();

	protected bool atkTimerStarted;

	protected Collider2D activationCollider;

	protected bool hazardTriggered;

	protected bool queueStateChange;

	protected bool AtkColEnabled
	{
		set
		{
			if (atkCollider != null)
			{
				atkCollider.enabled = value;
			}
		}
	}

	protected bool ActivationColEnabled
	{
		set
		{
			if (activationCollider != null)
			{
				activationCollider.enabled = value;
			}
		}
	}

	public static void HandleGlobalTime()
	{
		if (ChaosStopwatch.Check(globalStopwatchID))
		{
			switch (globalState)
			{
			case ActivationState.Deactivated:
				globalStopwatchID = ChaosStopwatch.Begin(1f);
				globalState = ActivationState.Windup;
				break;
			case ActivationState.Windup:
				globalStopwatchID = ChaosStopwatch.Begin(2f);
				globalState = ActivationState.Activated;
				break;
			case ActivationState.Activated:
				globalStopwatchID = ChaosStopwatch.Begin(2f);
				globalState = ActivationState.Deactivated;
				break;
			}
		}
		if (ChaosStopwatch.Check(globalAltStopwatchID))
		{
			switch (globalAltCounter)
			{
			case 0:
				globalAltPri = ActivationState.Windup;
				globalAltSec = ActivationState.Deactivated;
				break;
			case 1:
				globalAltPri = ActivationState.Activated;
				globalAltSec = ActivationState.Deactivated;
				break;
			case 2:
				globalAltPri = ActivationState.Deactivated;
				globalAltSec = ActivationState.Windup;
				break;
			case 3:
				globalAltPri = ActivationState.Deactivated;
				globalAltSec = ActivationState.Activated;
				break;
			}
			globalAltStopwatchID = ChaosStopwatch.Begin((globalAltCounter % 2 != 0) ? 2f : 0.75f);
			globalAltCounter = (globalAltCounter + 1) % 4;
		}
		if (ChaosStopwatch.Check(gRapidAltStopwatchID))
		{
			switch (gRapidAltCounter)
			{
			case 0:
				gRapidAltPri = ActivationState.Windup;
				gRapidAltSec = ActivationState.Activated;
				break;
			case 1:
				gRapidAltPri = ActivationState.Activated;
				gRapidAltSec = ActivationState.Windup;
				break;
			}
			gRapidAltStopwatchID = ChaosStopwatch.Begin(0.75f);
			gRapidAltCounter = (gRapidAltCounter + 1) % 2;
		}
	}

	public virtual void Awake()
	{
		activationCollider = GetComponent<Collider2D>();
		atkTrans = transform.Find("Attack");
		if (atkTrans != null)
		{
			attack = atkTrans.GetComponent<Attack>();
			atkCollider = atkTrans.GetComponent<Collider2D>();
		}
	}

	public virtual void Start()
	{
		Initialize();
	}

	public virtual void Initialize()
	{
		if (attack != null)
		{
			attack.SetAttackInfo(hazardSkillCategory, skillID);
		}
		switch (activationType)
		{
		case ActivationType.Always:
			ActivationColEnabled = false;
			AtkColEnabled = true;
			currentState = ActivationState.Activated;
			OnActivated();
			break;
		case ActivationType.Timer:
			if (timerType == TimerType.Local)
			{
				currentState = ActivationState.Deactivated;
				instStopwatchID = ChaosStopwatch.Begin(deactivatedTime);
			}
			OnDeactivated();
			break;
		case ActivationType.Trigger:
			timerType = TimerType.Local;
			hazardTriggered = false;
			ActivationColEnabled = true;
			AtkColEnabled = false;
			OnDeactivated();
			break;
		case ActivationType.Disabled:
			Disable();
			break;
		}
	}

	public virtual void Disable()
	{
		currentState = ActivationState.Deactivated;
		activationType = ActivationType.Disabled;
		ActivationColEnabled = false;
		AtkColEnabled = false;
		OnDeactivated();
	}

	public virtual void FixedUpdate()
	{
		switch (activationType)
		{
		case ActivationType.Always:
			if (atkTimerStarted)
			{
				if (!atkStopwatch.IsRunning)
				{
					atkTimerStarted = false;
					AtkColEnabled = false;
				}
			}
			else
			{
				atkTimerStarted = true;
				atkStopwatch.IsRunning = true;
				AtkColEnabled = true;
			}
			break;
		case ActivationType.Disabled:
			break;
		default:
			if (queueStateChange)
			{
				queueStateChange = false;
				HandleStateChange(currentState);
			}
			else if (activationType == ActivationType.Timer || hazardTriggered)
			{
				HandleTimer();
			}
			break;
		}
	}

	public virtual void HandleTimer()
	{
		switch (timerType)
		{
		case TimerType.Local:
			if (ChaosStopwatch.Check(instStopwatchID))
			{
				queueStateChange = true;
				switch (currentState)
				{
				case ActivationState.Deactivated:
					currentState = ActivationState.Windup;
					break;
				case ActivationState.Windup:
					currentState = ActivationState.Activated;
					break;
				case ActivationState.Activated:
					currentState = ActivationState.Deactivated;
					break;
				}
			}
			break;
		case TimerType.Global:
			if (!stateCleared)
			{
				if (globalState != ActivationState.Deactivated)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != globalState)
			{
				currentState = globalState;
				queueStateChange = true;
			}
			break;
		case TimerType.GlobalAlt:
			tempState = ((!isGlobalAltPrimary) ? globalAltSec : globalAltPri);
			if (!stateCleared)
			{
				if (tempState != ActivationState.Deactivated)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != tempState)
			{
				currentState = tempState;
				queueStateChange = true;
			}
			break;
		case TimerType.GRapidAlt:
			tempState = ((!isGlobalAltPrimary) ? gRapidAltSec : gRapidAltPri);
			if (!stateCleared)
			{
				if (tempState != ActivationState.Windup)
				{
					break;
				}
				stateCleared = true;
			}
			if (currentState != tempState)
			{
				currentState = tempState;
				queueStateChange = true;
			}
			break;
		}
	}

	public virtual void HandleStateChange(ActivationState givenState)
	{
		switch (givenState)
		{
		case ActivationState.Deactivated:
			OnDeactivated();
