		case ActivationState.Windup:
			OnWindup();
			AtkColEnabled = false;
			if (timerType == TimerType.Local)
			{
				instStopwatchID = ChaosStopwatch.Begin(windupTime);
			}
			break;
		case ActivationState.Activated:
			OnActivated();
			AtkColEnabled = true;
			if (timerType == TimerType.Local)
			{
				instStopwatchID = ChaosStopwatch.Begin(activatedTime);
			}
			break;
		}
	}

	public virtual void OnTriggerEnter2D(Collider2D col)
	{
