		{
			hazardTriggered = true;
			queueStateChange = true;
			currentState = ActivationState.Windup;
			ActivationColEnabled = false;
		}
	}

	public virtual void OnWindup()
	{
	}

	public virtual void OnActivated()
	{
	}

	public virtual void OnDeactivated()
	{
	}
