	private Vector3 spreadVector;

	private string targetTransName = "AllyHurtBox";

	public bool targetHurtBox = true;

	public bool targetTriggerCollider;

	public bool lockOnToTriggerCollider;

	public bool alwaysShowTargetLine;

	public bool showTargetLineOnChargeUp;

	private Transform targetPosTrans;

	private Vector3 originalTargetTransPos;

	private Vector3 targetPosition;

	private LineRenderer targetLine;

	public float targetLineWidth = 1f;

	public string shootAudioID = string.Empty;

	public string triggeredAudioID = string.Empty;

	private SpriteRenderer baseSprite;

	private SpriteRenderer downSprite;

	private SpriteRenderer rightSprite;

	private void Awake()
	{
		targetPosTrans = transform.Find("TargetPosition");
		targetLine = transform.Find("TargetLine").GetComponent<LineRenderer>();
		attackStopwatchID = ChaosStopwatch.Begin(initAttackCooldown);
		baseSprite = transform.Find("BaseSprite").GetComponent<SpriteRenderer>();
		downSprite = transform.Find("DownBaseSprite").GetComponent<SpriteRenderer>();
		rightSprite = transform.Find("RightBaseSprite").GetComponent<SpriteRenderer>();
	}

	private void Start()
	{
		if (projectileHazardContainer == null)
		{
			projectileHazardContainer = new GameObject().transform;
			projectileHazardContainer.gameObject.name = "FiredProjectilesContainer";
		}
		float num = Mathf.Clamp(targetLineWidth, 0.0625f, 9999f);
		targetLine.SetWidth(num, num);
		targetLine.sortingLayerName = "TargetLineAir";
		targetLine.enabled = alwaysShowTargetLine;
		projectilePrefab = ChaosBundle.Get(prefabPath);
		originalTargetTransPos = targetPosTrans.position;
		if (!targetHurtBox)
		{
			targetTransName = "AllyFloorContact";
		}
		baseSprite.enabled = false;
		Vector3 normalized = (targetPosTrans.position - transform.position).normalized;
		switch (Globals.GetPrimaryDirection(normalized))
		{
		case FacingDirection.Down:
			downSprite.enabled = true;
			break;
		case FacingDirection.Right:
			rightSprite.enabled = true;
			break;
		case FacingDirection.Left:
			rightSprite.enabled = true;
			rightSprite.transform.localScale = new Vector3(0f - rightSprite.transform.localScale.x, rightSprite.transform.localScale.y, rightSprite.transform.localScale.z);
			break;
		}
	}

	private void Update()
	{
		if (fireType != FireType.Disable)
		{
			if (!targetLine.enabled)
			{
				targetLine.enabled = alwaysShowTargetLine;
			}
			if (targetLine.enabled)
			{
				targetLine.SetPosition(1, targetPosTrans.position - targetLine.transform.position);
			}
			if (fireType == FireType.OnTime && attackReady && ChaosStopwatch.Check(attackStopwatchID))
			{
				StartCoroutine(ShootProj(targetPosTrans));
			}
		}
	}

	private void OnTriggerStay2D(Collider2D col)
	{
		if (fireType == FireType.OnTrigger && attackReady && ChaosStopwatch.Check(attackStopwatchID) && col.gameObject.name == targetTransName)
		{
			StartCoroutine(ShootProj((!targetTriggerCollider) ? targetPosTrans : col.transform));
			if (triggeredAudioID != string.Empty)
			{
				SoundManager.PlayAudioWithDistance(triggeredAudioID, transform.position);
			}
		}
	}

	public void ShootProjectile(Transform trans = null)
	{
		StartCoroutine(ShootProj(trans ?? targetPosTrans));
	}

	private IEnumerator ShootProj(Transform targetTrans)
	{
		if (targetTrans == null || !attackReady)
		{
			yield break;
		}
		attackReady = false;
		chargeUpStopwatchID = ChaosStopwatch.Begin(attackChargeUpTime);
		while (showTargetLineOnChargeUp && !ChaosStopwatch.Check(chargeUpStopwatchID))
		{
			if (targetTrans == null)
			{
				yield break;
			}
			targetLine.enabled = true;
			yield return null;
		}
		if (targetTrans == null)
		{
			yield break;
		}
		targetLine.enabled = alwaysShowTargetLine;
		targetPosition = (targetTrans.position - transform.position).normalized;
		shotDelayStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotDelay, shotCount);
		while (!attackReady && !(targetTrans == null))
		{
			switch (ChaosStopwatch.CheckInterval(shotDelayStopwatchID))
			{
			default:
				yield break;
			case StopwatchState.Ready:
				if (targetTriggerCollider && lockOnToTriggerCollider)
				{
					targetPosition = (targetTrans.position - transform.position).normalized;
				}
				InstantiateProjectile(targetPosition);
				break;
			case StopwatchState.Done:
				attackStopwatchID = ChaosStopwatch.Begin(attackCooldown);
				attackReady = true;
				yield break;
			case StopwatchState.Running:
				break;
			}
			yield return null;
		}
	}

	private void InstantiateProjectile(Vector3 attackVector)
	{
		Projectile component = Object.Instantiate(projectilePrefab, transform.position, Quaternion.identity).GetComponent<Projectile>();
		component.transform.SetParent(projectileHazardContainer);
		if (!(component == null))
		{
			spreadVector = ((!(spreadModifier > 0f)) ? Vector3.zero : new Vector3(Random.Range(-1f, 1f) * spreadModifier, Random.Range(-1f, 1f) * spreadModifier));
			component.parentObject = gameObject;
			component.moveVector = attackVector + spreadVector;
			component.attackBox.SetAttackInfo(projectileSkillCategory, projectileSkillID);
			if (shootAudioID != string.Empty)
			{
				SoundManager.PlayAudioWithDistance(shootAudioID, transform.position);
			}
		}
	}
}
using UnityEngine;

public class UnstableGround : MonoBehaviour
{
	private static GameObject prefab;

	public Attack attack;

	public CircleCollider2D attackCol;

	public ParticleSystem dustPartSys;

	public float attackRadius = 3f;

	private int hitStopwatchID;

	public int hitCount = 5;

	public float hitInterval = 0.25f;

	public bool hitImmediate = true;

	private bool hitCompleted;

	private Vector2[] riftArray = new Vector2[6];

	private SectionedTrailEmitter stEmitter;

	private bool priCheck;

	private bool secCheck;

	private Vector2 priVec;

	private Vector2 secVec;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/UnstableGround.prefab"));

	private void Start()
	{
		attackCol.radius = attackRadius;
		if (!hitImmediate)
		{
			hitCount++;
		}
		hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitInterval, hitCount);
		for (int i = 0; i < 6; i++)
		{
			ref Vector2 reference = ref riftArray[i];
			reference = (Vector2)transform.position + Globals.GetCirclePositionVector(12, i * 2 + 1) * (attackRadius + 0.5f);
		}
	}

	private void FixedUpdate()
	{
		if (hitCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attackCol.enabled = false;
			break;
		case StopwatchState.Ready:
			CreateEffects(transform.position);
			if (hitImmediate)
			{
				attackCol.enabled = true;
			}
			else
			{
				hitImmediate = true;
			}
			break;
		case StopwatchState.Done:
			hitCompleted = true;
			attackCol.enabled = false;
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 0.25f);
			}
			break;
		}
	}

	private void CreateEffects(Vector2 givenPosition)
	{
		dustPartSys.Emit(Random.Range(10, 15));
		PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, givenPosition);
		string audioID = "GroundSlam";
		Vector2? soundOrigin = givenPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		stEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("FloorRift");
		for (int i = 0; i < 6; i++)
		{
			priVec = riftArray[i];
			secVec = riftArray[(i + 1) % 6];
			priCheck = Globals.CheckCircle(priVec, 0.25f, ChaosCollisions.layerAll);
			secCheck = Globals.CheckCircle(secVec, 0.25f, ChaosCollisions.layerAll);
			if (priCheck)
			{
				if (secCheck)
				{
					stEmitter.Emit(riftArray[i], riftArray[(i + 1) % 6]);
				}
				else
				{
					stEmitter.Emit(priVec, Globals.GetLinecastVector(priVec, secVec, ChaosCollisions.layerAll));
				}
			}
			else if (secCheck)
			{
				stEmitter.Emit(secVec, Globals.GetLinecastVector(secVec, priVec, ChaosCollisions.layerAll));
			}
		}
	}
}
using UnityEngine;

public class RetractableWall : MonoBehaviour
{
	private SpriteRenderer sprite;

	private Collider2D[] colliders;

	public bool activated;

	public bool destroyOnDeactivation;

	public MapDirections wallType;

	private void Awake()
	{
		sprite = GetComponent<SpriteRenderer>();
		colliders = GetComponentsInChildren<Collider2D>();
	}

	private void Start()
	{
		if (activated)
		{
			Activate(isOnAwake: true);
		}
		else
		{
			Disable(isOnAwake: true);
		}
	}

	public void Activate(bool isOnAwake = false)
	{
		if (!isOnAwake)
		{
			SoundManager.PlayAudio("Rumble");
		}
		sprite.enabled = true;
		Collider2D[] array = colliders;
		foreach (Collider2D collider2D in array)
		{
			collider2D.enabled = true;
		}
		activated = true;
	}

	public void Disable(bool isOnAwake = false)
	{
		if (!isOnAwake)
		{
			SoundManager.PlayAudio("Rumble");
			if (destroyOnDeactivation)
			{
				Object.Destroy(gameObject);
				return;
			}
		}
		sprite.enabled = false;
		Collider2D[] array = colliders;
		foreach (Collider2D collider2D in array)
		{
			collider2D.enabled = false;
		}
		activated = false;
	}
}
