public class ExplosiveBarrel : Destructible
{
	public static BoolVarStat ignorePlayerStat = new BoolVarStat(newBaseVal: false);

	private float explodeDelay = 0.25f;

	private float explodeScale = 2.25f;

	public override void Awake()
	{
		base.Awake();
		if (destroyedAudioID == string.Empty)
		{
			destroyedAudioID = "WoodBreak";
		}
	}

	public override void InitFSM()
	{
		base.InitFSM();
		fsm.AddState(new FallState("Fall", fsm, this));
	}

	public override void Break()
	{
		if (health != null)
		{
			ApplyKnockback(health.lastAttack);
			health.lastAttack = null;
		}
		StartCoroutine(DelayedExplosion());
	}

	private IEnumerator DelayedExplosion()
	{
		yield return new WaitForSeconds(explodeDelay);
		if (!(fsm.currentStateName == "Fall"))
		{
			if (ignorePlayerStat.CurrentValue)
			{
				FlameBurst.CreateBurst(transform.position, Enemy.globalEnemySkillCategory, "HazardExplosiveBarrelEnemyOnly", 1, explodeScale);
			}
			else
			{
				FlameBurst.CreateBurst(transform.position, "EnemyFFA", "HazardExplosiveBarrel", 1, explodeScale);
			}
			PoolManager.GetPoolItem<ParticleEffect>("BurnMarkLargeEmitter").Emit(1, transform.position, ParticleEffectOverrides.StartLifeTimeOne);
			string audioID = "BlazingBlitzEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
