	public override void InitComponents()
	{
		base.InitComponents();
		activationObj = transform.Find("ActivationCollider").gameObject;
		if (ignoreActivation)
		{
			activationObj.SetActive(value: false);
		}
	}

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new DestructibleIdleState("Idle", fsm, this));
		fsm.AddState(new BlockcadeDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

