	{
		if (!destroyed)
		{
			destroyed = true;
			GameController.enemies.Remove(gameObject);
			GameController.allies.Remove(gameObject);
			base.Break();
		}
	}

	private void SetAvailableStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			if (!GameController.allies.Contains(gameObject))
			{
				GameController.allies.Add(gameObject);
			}
			Enemy.AddEnemy(gameObject);
		}
		else
		{
			GameController.enemies.Remove(gameObject);
			GameController.allies.Remove(gameObject);
		}
	}

	public override void OnTriggerEnter2D(Collider2D col)
	{
		if (!ignoreActivation && !isActivated && ColliderIsPlayer(col))
		{
			isActivated = true;
			if (!autoResetActivation && activationObj != null)
			{
				activationObj.SetActive(value: false);
			}
			SetAvailableStatus(givenStatus: true);
		}
	}

	public void OnTriggerExit2D(Collider2D col)
	{
		if (autoResetActivation && !ignoreActivation && isActivated && ColliderIsPlayer(col))
		{
			isActivated = false;
			SetAvailableStatus(givenStatus: false);
		}
	}

	private bool ColliderIsPlayer(Collider2D col)
	{
		return col != null && ((1 << col.gameObject.layer) & ChaosCollisions.layerPlayer) != 0;
	}

	private new void Reset()
	{
		if (!destroyed)
		{
			fsm.ChangeState("Dead");
		}
	}

	private void ClearBlockGroup()
	{
		Blockcade[] componentsInChildren = transform.parent.GetComponentsInChildren<Blockcade>();
		foreach (Blockcade blockcade in componentsInChildren)
		{
			if (blockcade != null && blockcade != this)
			{
				blockcade.Reset();
			}
		}
	}
