def nums(text):
    text=re.sub(r'//.*','',text)
    out=set()
    for m in re.finditer(r'(?<![A-Za-z_0-9.])(-?\d+\.?\d*)f?(?![A-Za-z_0-9])',text):
        out.add(m.group(1))
