| Р-239 | `wild_disasters_hex` | проклятие: случайные катаклизмы | Прочее | TIMED, RUNMOD | Работает только в сценах этажей вне загрузки. Каждые 2.5–4 с (равномерно) вокруг экрана случайно (1/5 каждое): снежная буря; град валунов (2 + 50% третий, задержки 0.25 и 0.75 с); метеор (1 + 50% второй через 0.75 с); волна давления (1 + 50% вторая через 1 с); удар молнии. Урон по категории врагов. Минус реликвии — сама опасность. | — | проклятая, только хаб | Проклятая, hub-only. | Источник: RandomDisasters |
using System.Collections;
using UnityEngine;
public class RandomDisasters : Item
{
	public static string staticID = "RandomDisasters";
	private bool disasterRunning;
	private ChaosQuickStopwatch disasterStopwatch;
	private Vector2 parentPosition;
	private CastingCircle currentCircle;
	private static readonly string meteorID = "RandomDisastersMeteor";
	private MeteorStrike currentMS;
	private static readonly string pressureID = "RandomDisastersPressure";
	private PressureWave currentPW;
	private static readonly string boulderID = "RandomDisastersBoulder";
	private BoulderDrop currentBD;
	private static readonly string thunderID = "RandomDisastersThunder";
	private ThunderBlast currentTB;
	private static readonly string blizzardID = "RandomDisastersBlizzard";
	private Blizzard currentBL;
	private NumVarStatMod blizMoveMod;
	private float CooldownDelay => Random.Range(2.5f, 4f);
	private bool DiasterAllowed => !LoadingScreen.loading && NextLevelLoader.InTierScene(string.Empty);
	public RandomDisasters()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		hubOnly = true;
		disasterStopwatch = new ChaosQuickStopwatch();
		blizMoveMod = new NumVarStatMod(ID, 6f, 10, VarStatModType.Override);
	}
	public override void Activate()
	{
		if (!(parentEntity == null))
		{
			disasterRunning = true;
			parentEntity.StartCoroutine(SpawnDisasters());
		}
	}
	public override void Deactivate()
	{
		disasterRunning = false;
	}
	private IEnumerator SpawnDisasters()
	{
		WaitWhile waitWhileStopwatch = new WaitWhile(() => disasterStopwatch.IsRunning);
		while (disasterRunning)
		{
			yield return waitWhileStopwatch;
			disasterStopwatch.SetDelay(CooldownDelay, stopCurrent: false, autoStart: true);
			if (DiasterAllowed)
			{
				SpawnDisaster();
			}
			yield return null;
		}
	}
	private void SpawnDisaster()
	{
		if (parentEntity == null)
		{
			disasterRunning = false;
			return;
		}
		parentPosition = CameraController.V2Position;
		switch (Random.Range(0, 5))
		{
		case 0:
			parentEntity.StartCoroutine(SpawnBlizzard(parentPosition));
			break;
		case 1:
			parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition));
			parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition, 0.25f));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnBoulderDrop(parentPosition, 0.75f));
			}
			break;
		case 2:
			parentEntity.StartCoroutine(SpawnMeteor(parentPosition));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnMeteor(parentPosition, 0.75f));
			}
			break;
		case 3:
			parentEntity.StartCoroutine(SpawnPressureWave(parentPosition));
			if (Globals.RandBool)
			{
				parentEntity.StartCoroutine(SpawnPressureWave(parentPosition, 1f));
			}
			break;
		default:
			SpawnThunderBlast(parentPosition);
			break;
		}
	}
	private IEnumerator SpawnMeteor(Vector2 givenPosition, float givenDelay = 0f)
	{
		if (givenDelay > 0f)
		{
			yield return new WaitForSeconds(givenDelay);
		}
		givenPosition += new Vector2(Random.Range(-10f, 10f), Random.Range(-6f, 6f));
		currentMS = PoolManager.GetPoolItem<MeteorStrike>();
		currentMS.Initialize(givenPosition, useCast: true, useEnemyColor: true);
		currentMS.attack.SetAttackInfo(Enemy.globalEnemySkillCategory, meteorID);
		currentMS.anim.speed = Random.Range(1f, 2f);
		currentMS.shakeIntensity = 0.1f;
	}
	private IEnumerator SpawnBlizzard(Vector2 givenPosition)
	{
		Vector2 spawnVec = givenPosition + new Vector2(Random.Range(8f, 10f) * ((!Globals.RandBool) ? (-1f) : 1f), Random.Range(4f, 6f) * ((!Globals.RandBool) ? (-1f) : 1f));
		currentCircle = CastingCirclePool.Spawn("Draw", spawnVec, disableWithParentVal: false, null, trackParentVal: true, useCastTimeVal: true, 4.75f, 0f, 0f, CastingCircle.enemyColor, 0.75f);
		yield return Globals.waitForThreeQts;
		currentBL = Globals.ChaosInst<Blizzard>(Blizzard.Prefab, null, spawnVec);
		currentBL.attackBox.SetAttackInfo(Enemy.globalEnemySkillCategory, blizzardID);
		currentBL.maxHitCount = 16;
		currentBL.duration = 4f;
		currentBL.useMovement = true;
		currentBL.movement.moveSpeedStat.AddMod(blizMoveMod);
		currentBL.movement.moveVector = (givenPosition + Random.insideUnitCircle * 3f - spawnVec).normalized;
		currentBL.castingCircle = currentCircle;
	}
	private IEnumerator SpawnBoulderDrop(Vector2 givenPosition, float givenDelay = 0f)
	{
		if (givenDelay > 0f)
		{
			yield return new WaitForSeconds(givenDelay);
		}
		givenPosition += new Vector2(Random.Range(-9f, 9f), Random.Range(-6f, 6f));
		currentCircle = CastingCirclePool.Spawn("Draw", givenPosition, disableWithParentVal: false, null, trackParentVal: true, useCastTimeVal: true, 1.75f, 2.25f, 0f, CastingCircle.enemyColor, 1f);
		PoolManager.GetPoolItem<FloorCrackEffect>().Crack(givenPosition, 0.5f, 1f, 0f, FloorCrackEffectType.Small);
		yield return Globals.waitForOne;
		currentBD = Globals.ChaosInst<BoulderDrop>(BoulderDrop.Prefab, null, givenPosition);
		currentBD.attack.SetAttackInfo(Enemy.globalEnemySkillCategory, boulderID);
	}
	private IEnumerator SpawnPressureWave(Vector2 givenPosition, float givenDelay = 0f)
	{
		if (givenDelay > 0f)
		{
			yield return new WaitForSeconds(givenDelay);
		}
		Vector2 spawnVec = givenPosition + new Vector2(Random.Range(12f, 14f) * ((!Globals.RandBool) ? (-1f) : 1f), Random.Range(8f, 10f) * ((!Globals.RandBool) ? (-1f) : 1f));
		currentPW = Globals.ChaosInst<PressureWave>(PressureWave.Prefab, null, spawnVec);
		currentPW.SetSkillData(Enemy.globalEnemySkillCategory, pressureID);
		currentPW.maxWaveCount = 40;
		currentPW.maxSpeed = 1f;
		currentPW.moveVector = (givenPosition + Random.insideUnitCircle * 3f - spawnVec).normalized;
		currentPW.useMaxHitCount = false;
	}
	private void SpawnThunderBlast(Vector2 givenPosition)
	{
		givenPosition += new Vector2(Random.Range(-9f, 9f), Random.Range(-6f, 6f));
		currentCircle = CastingCirclePool.Spawn("Draw", givenPosition, disableWithParentVal: false, null, trackParentVal: true, useCastTimeVal: true, 0.8f, 4.25f, 0f, CastingCircle.enemyColor, 0.8f);
		currentTB = Globals.ChaosInst<ThunderBlast>(ThunderBlast.Prefab, null, givenPosition);
		currentTB.SetSkillData(Enemy.globalEnemySkillCategory, thunderID, 1);
		currentTB.delayTime = 0.8f;
	}
}

using System;

public abstract class Item
{
	public enum Category
	{
		Offense,
		Defense,
		Misc
	}

	public string ID = "UnnamedItem";

	public Player parentPlayer;

	public Entity parentEntity;

	public string parentSkillCategory = string.Empty;

	public string parentCombineID = string.Empty;

	public string parentGroupID = string.Empty;

	public Category category = Category.Misc;

	public bool isCursed;

	public bool hubOnly;

	public bool notForSale;

	public bool combineOnly;

	public bool isGroupItem;

	public bool destroyOnDrop;

	public bool useSimpleInfo;

	protected virtual string ExtraInfo => string.Empty;

	public virtual string FormattedExtraInfo
	{
		get
		{
			string result;
			if (ExtraInfo == string.Empty)
			{
				result = string.Empty;
			}
			else
			{
				result = ((!useSimpleInfo) ? ("\n<color=#009999>( </color><color=#00dddd>" + ExtraInfo + "</color><color=#009999> )</color>") : ("\n<color=#00dddd>" + ExtraInfo + "</color>"));
			}
			return result;
		}
	}

	public Item()
	{
	}

	protected string PercentToStr(float givenValue, string prefix = "")
	{
		return Globals.PercentToStr(givenValue, prefix);
	}

	protected string PercentToStr(NumVarStatMod givenMod, string prefix = "")
	{
		return Globals.PercentToStr(givenMod, prefix);
	}

	public virtual void Activate()
	{
	}

	public virtual void Deactivate()
	{
	}

	public bool GroupItemCreated(string givenID)
	{
		if (SetParentAsPlayer() && !parentPlayer.inventory.ContainsItem(givenID) && GroupItemManager.groupsDict.ContainsKey(givenID) && GroupItemManager.groupsDict[givenID].Contains(ID))
		{
			foreach (string item in GroupItemManager.groupsDict[givenID])
			{
				if (item != ID && parentPlayer.inventory.ContainsItem(item))
				{
					parentPlayer.inventory.AddItem(givenID, showNotice: false, ignoreMax: true);
					return true;
				}
			}
		}
		return false;
	}

	public static bool IsCursedItem(string itemID)
	{
		return LootManager.completeItemDict.ContainsKey(itemID) && LootManager.completeItemDict[itemID].isCursed;
	}

	public void SetParentSkillCategory()
	{
		if (parentEntity != null)
		{
			parentSkillCategory = parentEntity.skillCategory;
		}
	}

	public virtual bool SetParentAsPlayer()
	{
		return (parentPlayer = parentEntity as Player) != null;
	}

	public virtual void UpdateItemBar(ItemStatusBar.ItemState givenState)
	{
		if (SetParentAsPlayer())
		{
			ItemStatusBar.UpdateItem(parentPlayer.playerID, ID, givenState);
		}
	}

	public virtual void RemoveFromItemBar()
	{
		if (SetParentAsPlayer())
		{
			ItemStatusBar.RemoveItem(parentPlayer.playerID, ID);
		}
	}

	public static Item CreateItem(string givenID)
	{
		return (Item)Activator.CreateInstance(LootManager.completeItemDict[givenID].GetType());
	}

	public static bool IsUnlocked(string givenID, bool setUnlocked = false)
	{
		if (setUnlocked)
		{
			if (!GameDataManager.gameData.CheckItemDataEntry(givenID))
			{
				GameDataManager.gameData.UpdateItemDataEntry(givenID);
				GameDataManager.Save();
				AchievementManager.UnlockAchievement(Achievement.UnlockHalfRelics);
				AchievementManager.UnlockAchievement(Achievement.UnlockAllRelics);
			}
			return true;
		}
		return GameDataManager.gameData.CheckItemDataEntry(givenID);
	}

	public bool IgnoreStatusConditional(StatData givenStatData)
	{
		return !givenStatData.GetValue<bool>(StatData.isStatStr);
	}

	public bool BasicAndStatusConditional(StatData givenStatData)
	{
		return !givenStatData.GetValue<string>(StatData.idStr).Contains("Basic") && !givenStatData.GetValue<bool>(StatData.isStatStr);
	}

	public bool IgnoreBasicDashAndStatusCond(StatData givenStatData)
	{
		return BasicAndStatusConditional(givenStatData) && !givenStatData.GetValue<string>(StatData.idStr).Contains("Dash");
	}

	public static bool IsEmpowered(Player.SkillState givenSkill)
	{
		return givenSkill?.IsEmpowered ?? false;
	}

	public static bool IsNotEmpowered(Player.SkillState givenSkill)
	{
		return givenSkill != null && !givenSkill.IsEmpowered;
	}

	public static bool IsBasicSkill(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill.isBasic && givenSkill is Player.MeleeAttackState;
	}

	public static bool IsDashSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isDash ?? false;
	}

	public bool IsMovementSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isMovementSkill ?? false;
	}

	public bool IsJumpSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isJumpSkill ?? false;
	}

	public static bool IsMeleeSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isMeleeSkill ?? false;
	}

	public static bool IsProjectileSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isProjectileSkill ?? false;
	}

	public static bool IsSummonSkill(Player.SkillState givenSkill)
	{
		return givenSkill?.isSummonSkill ?? false;
	}

	public bool IsNegBasicSkill(Player.SkillState givenSkill)
	{
		return givenSkill is Player.NegMeleeState;
	}

	public static bool IsMinionSkill(Player.SkillState givenSkill)
	{
		return givenSkill != null && givenSkill is Player.UseBaseMinion;
	}
}

