using System;
public class EnhanceDash : Item
{
	public static string staticID = "EnhanceDash";
	private Player.SkillState prevDash;
	private BoolVarStatMod empMod;
	private NumVarStatMod cdMod;
	protected override string ExtraInfo => PercentToStr(cdMod, "-");
	public EnhanceDash()
	{
		ID = staticID;
		category = Category.Defense;
		empMod = new BoolVarStatMod(ID, newModValue: true);
		cdMod = new NumVarStatMod(ID, -0.4f, 10, VarStatModType.Multiplicative);
	}
	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}
	private void SetEventHandlers(bool givenStatus)
	{
		if (!SetParentAsPlayer())
		{
			return;
		}
		Player player = parentPlayer;
		player.skillDropEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillDropEventHandlers, new Player.SkillEventHandler(OnSkillLose));
		Player player2 = parentPlayer;
		player2.skillRemoveEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player2.skillRemoveEventHandlers, new Player.SkillEventHandler(OnSkillLose));
		Player player3 = parentPlayer;
		player3.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player3.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillGain));
		Player player4 = parentPlayer;
		player4.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player4.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
		if (givenStatus)
		{
			Player player5 = parentPlayer;
			player5.skillDropEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player5.skillDropEventHandlers, new Player.SkillEventHandler(OnSkillLose));
			Player player6 = parentPlayer;
			player6.skillRemoveEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player6.skillRemoveEventHandlers, new Player.SkillEventHandler(OnSkillLose));
			Player player7 = parentPlayer;
			player7.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player7.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillGain));
			Player player8 = parentPlayer;
			player8.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player8.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
		}
		Player.SkillState[] assignedSkills = parentPlayer.assignedSkills;
		foreach (Player.SkillState givenSkill in assignedSkills)
		{
			if (SetEmpStatus(givenSkill, givenStatus))
			{
				break;
			}
		}
		StatManager.ModifyAllStatData(cdMod, parentSkillCategory, "cooldown", IsDashConditional, givenStatus);
	}
	private void OnSkillGain(Player.SkillState givenSkill)
	{
		SetEmpStatus(givenSkill, givenStatus: true);
	}
	private void OnSkillLose(Player.SkillState givenSkill)
	{
		SetEmpStatus(givenSkill, givenStatus: false);
	}
	private void OnSkillAssign(Player.SkillState givenSkill, int givenSlot)
	{
		SetEmpStatus(givenSkill, givenStatus: true);
	}
	private bool SetEmpStatus(Player.SkillState givenSkill, bool givenStatus)
	{
		if (givenSkill == null || !givenSkill.isDash)
		{
			return false;
		}
		if (prevDash != null)
		{
			prevDash.SetEmpowered(givenStatus: false, empMod);
		}
		givenSkill.SetEmpowered(givenStatus, empMod);
		prevDash = givenSkill;
		GameUI.RefreshCDUI();
		return true;
	}
	public bool IsDashConditional(StatData givenStatData)
	{
		return givenStatData.GetValue<string>("ID").Contains("Dash");
	}
}

